window.LAW_DATA = {"id": "igraat-jinaiya", "title": "قانون الإجراءات الجنائية", "title_en": "CRIMINAL PROCEDURE", "cat": "إجراءات", "icon": "🚔", "desc": "القانون رقم 150 لسنة 1950 — إجراءات جمع الاستدلالات والتحقيق والمحاكمة الجنائية.", "article_count": 499, "articles": [{"number": "1", "chapter": "الفصل الأول", "text": "تختص النيابة العامة دون غيرها برفع الدعوى الجنائية ومباشرتها ولاترفع من غيرها إلا فى الأحوال المبينة فى القانون . ولا يجوز ترك الدعوى الجنائية أو وقفها أو تعطيل سيرها إلا فى الأحوال المبينة فى القانون"}, {"number": "2", "chapter": "الفصل الأول", "text": "يقوم النائب العام بنفسه أو بواسطة أحد أعضاء النيابة العامة بمباشرة الدعوى الجنائية كما هو مقرر بالقانون . ويجوز أن يقوم بأداء وظيفة النيابة العامة من يعين لذلك من غير هؤلاء بمقتضى القانون"}, {"number": "3", "chapter": "الفصل الأول", "text": "\" لا يجوز أن ترفع الدعوى الجنائية إلا بناء على شكوى شفهية أو كتابية من المجنى عليه أو من وكيله الخاص ، إلى النيابة العامة أو إلى أحد مأموري الضبط القضائى فى الجرائم المنصوص عليها فى المواد 185، 274، 279، 292 ، 293، 3.3، 3.6، 3.7، 3.8 ، من قانون العقوبات ، وكذلك فى الأحوال الأخرى التى ينص عليها القانون . ولا تقبل الشكوى بعد ثلاثة أشهر من يوم علم المجنى عليه بالجريمة وبمرتكبها مالم ينص القانون على خلاف ذلك \"\""}, {"number": "4", "chapter": "الفصل الأول", "text": "\"\" إذا تعدد المجني عليهم يكفى أن تقدم الشكوى من أحدهم وإذا تعدد المتهمون وكانت الشكوى مقدمة ضد أحدهم ، تعتبر أنها مقدمة ضد الباقين"}, {"number": "5", "chapter": "الفصل الأول", "text": "\"\" إذا كان المجنى عليه فى الجريمة لم يبلغ خمس عشر ة سنة كاملة أو كان مصابا بعاهة فى عقله ، تقدم الشكوى ممن له الولاية عليه . وإذا كانت الجريمة واقعة على المال تقبل الشكوى من الوصي أو القيم وتتبع فى هاتين الحالتين جميع الأحكام المتقدمة الخاصة بالشكوى \"\""}, {"number": "6", "chapter": "الفصل الأول", "text": "\"\" إذا تعارضت مصلحة المجنى عليه مع مصلحة من يمثله ، أو لم يكن له من يمثله ، تقوم النيابة العامة مقامه \"\""}, {"number": "7", "chapter": "الفصل الأول", "text": "\"\" ينقضى الحق فى الشكوى بموت المجني عليه ، وإذا حدثت الوفاة بعد تقديم الشكوى فلا تؤثر على سير الدعوى \"\""}, {"number": "8", "chapter": "الفصل الأول", "text": "لا يجوز رفع الدعوى الجنائية أو اتخاذ إجراءات فيها إلا بناء على طلب كتابى من وزير العدل فى الجرائم المنصوص عليها فى المادتين 181 و182 من قانون العقوبات ، وكذلك فى الأحوال الأخرى التى ينص عليها القانون ."}, {"number": "8", "chapter": "الفصل الأول", "text": "مكررا لا يجوز أن ترفع الدعوى الجنائية فى الجرائم المنصوص عليها فى المادة 116 مكررا (أ) من قانون العقوبات آلا من النائب العام أو المحامى العام"}, {"number": "9", "chapter": "الفصل الأول", "text": "لا يجوز رفع الدعوى الجنائية أو اتخاذ إجراءات فيها فى الجرائم المنصوص عليها فى المادة 184 من قانون العقوبات إلا بناء على طلب كتابى من الهيئة أو رئيس المصلحة المجنى عليها . وفى جميع الأحوال التي يشترط فيه القانون لرفع الدعوى الجنائية تقديم شكوى أو الحصول على إذن أو طلب من المجنى عليه أو غيره لا يجوز اتخاذ إجراءات التحقيق فيها آلا بعد تقديم هذه الشكوى أو الحصول على هذا الإذن أو الطلب ، على أنه فى الجريمة المنصوص عليها فى المادة 185 من قانون العقوبات وفى الجرائم المنصوص عليها فى المواد 302و306و 307 و308 من القانون المذكور ، إذا كان المجنى عليه فيها موظفا عاما أو شخصا ذا صفة نيابية عامة أو مكلفا بخدمة عامة وكان ارتكاب الجريمة بسبب أداء الوظيفة أو النيابة أو الخدمة العامة يجوز اتخاذ إجراءات التحقيق فيها دون حاجة إلى تقديم شكوى أو طلب أو إذن \"\""}, {"number": "10", "chapter": "الفصل الأول", "text": "\"\" لمن قدم الشكوى أو الطلب فى الأحوال المشار إليها فى المواد السابقة وللمجنى عليه فى الجريمة المنصوص عليها فى المادة 185 من قانون العقوبات وفى الجرائم المنصوص عليها فى المواد 3.2و 3.6 و 3.7 و3.8 من القانون المذكور إذا كان موظفا عاما أو شخصا ذا صفة نيابية عامة أو مكلفا بخدمة عامة وكان ارتكاب الجريمة بسبب أداء الوظيفة أو النيابة أو الخدمة العامة أن يتنازل عن الشكوى أو الطلب فى أى وقت إلى أن يصدر فى الدعوى حكم نهائي وتنقضي الدعوى الجنائية بالتنازل . وفى حالة تعدد المجنى عليهم لا يعتبر التنازل صحيحا إلا إذا صدر من جميع من قدموا الشكوى والتنازل بالنسبة لأحد المتهمين يعد تنازلا للباقين . وإذا توفى الشاكى فلا ينتقل حقه فى التنازل إلى ورثته ، إلا فى دعوى الزنا فلكل واحد من أولاد الزوج الشاكى من الزوج المشكو منه أن يتنازل عن الشكوى وتنقضي الدعوى ."}, {"number": "11", "chapter": "الفصل الأول", "text": "إذا رأت محكمة الجنايات فى دعوى مرفوعة أمامها أن هناك متهمين غير من أقيمت الدعوى عليهم ، أو وقائع أخرى غير المسندة فيها إليهم ، أو أن هناك جناية أو جنحة مرتبطة بالتهمة المعروضة عليها فلها أن تقيم الدعوى على هؤلاء الأشخاص أو بالنسبة لهذه الوقائع ، وتجيلها إلى النيابة العامة لتحقيقها والتصرف فيها طبقا للباب الرابع من الكتاب الأول من هذا القانون . وللمحكمة أن تندب أحد أعضائها للقيام بإجراءات التحقيق ، وفى هذه الحالة تسرى على العضو المنتدب جميع الأحكام الخاصة بقاضى التحقيق . وإذا صدر قرار فى نهاية التحقيق بإحالة الدعوى إلى المحكمة وجب إحالتها إلى محكمة أخرى ، ولا يجوز أن يشترك فى الحكم فيها أحد المستشارين الذين قرروا إقامة الدعوى . وإذا كانت المحكمة لم تفصل فى الدعوى الأصلية ، وكانت مرتبطة مع الدعوى الجديدة ارتباطا لا يقبل التجزئة ، وجب إحالة القضية كلها إلى محكمة أخرى ."}, {"number": "12", "chapter": "الفصل الأول", "text": "للدائرة الجنائية بمحكمة النقض عند نظر الموضوع بناء على الطعن فى المرة الثانية حق إقامة الدعوى طبقا لما هو مقرر بالمادة السابقة . وإذا طعن فى الحكم الذى يصدر فى الدعوى الجديدة للمرة الثانية فلا يجوز أن يشترك فى نظرها أحد المستشارين الذين قرروا إقامتها ."}, {"number": "13", "chapter": "الفصل الأول", "text": "لمحكمة الجنايات أو محكمة النقض فى حالة نظر الموضوع إذا وقعت أفعال من شأنها الإخلال بأوامرها ، أو بالاحترام الواجب لها أو التأثير فى قضائها أو فى الشهود ، وكان ذلك فى صدد دعوى منظورة أمامها أن تقيم الدعوى الجنائية على المتهم طبقا للمادة ( 11 )"}, {"number": "14", "chapter": "الفصل الثالث", "text": "تنقضى الدعوى الجنائية بوفاة المتهم , ولايمنع ذلك من الحكم بالمصادرة فى الحالة المنصوص عليها بالفقرة الثانية من المادة 30 من قانون العقوبات إذا حدثت الوفاة أثناء نظر الدعوى –"}, {"number": "15", "chapter": "الفصل الثالث", "text": "تنقضى الدعوى الجنائية فى مواد الجنايات لمضى عشر سنين من بوم وقوع الجريمة وفى مواد الجنح بمضى ثلاث سنين وفى مواد المخالفات بمضى سنة مالم ينص القانون على خلاف ذلك – أما فى الجرائم المنصوص عليها فى المواد 117 و126 و127و 282و 3.9 مكررا (أ) والجرائم المنصوص عليها فى القسم الأول من الباب الثانى من الكتاب الثانى من قانون العقوبات والتى تقع بعد تاريخ العمل بهذا القانون فلا تنقضى الدعوى الجنائية الناشئة عنها بمضي المدة . ومع عدم الإخلال بأحكام الفقرتين السابقتين لا تبدأ المدة المسقطة للدعوى الجنائية في الجرائم المنصوص عليها في الباب الرابع من الكتاب الثانى من قانون العقوبات والتي تقع من موظف عام إلا من تاريخ انتهاء الخدمة أو زوال الصفة مالم يبدأ التحقيق فيها قبل ذلك ."}, {"number": "16", "chapter": "الفصل الثالث", "text": "لا يوقف سريان المدة التي تسقط بها الدعوى الجنائية لأى سبب كان"}, {"number": "17", "chapter": "الفصل الثالث", "text": "تنقطع المدة بإجراءات التحقيق أو الاتهام أو المحاكمة وكذلك بالأمر الجنائي أو بإجراءات الاستدلال إذا اتخذت فى مواجهة المتهم أو إذا أخطر بها بوجه رسمى وتسرى المدة من جديد ابتداء من يوم الانقطاع وإذا تعددت الإجراءات التي تقطع المدة فإن سريان المدة يبدأ من تاريخ أخر إجراء"}, {"number": "18", "chapter": "الفصل الثالث", "text": "إذا تعدد المتهمون فإن انقطاع المدة بالنسبة لأحدهم يترتب عليها انقطاعها بالنسبة للباقين مالم تكن قد اتخذت ضدهم إجراءات قاطعة للمدة."}, {"number": "18", "chapter": "الفصل الثالث", "text": "مكرر - ( مستبدلة بالقانون 74 لسنة 2007 – الجريدة الرسمية العدد 22 تابع فى 31 مايو 2007 ) يجوز للمتهم التصالح فى المخالفات وكذلك فى الجنح التي لايعاقب عليها وجوبا بغير الغرامة أو التى يعاقب عليها جوازيا بالحبس الذى لايزيد حده الأقصى على ستة أشهر. وعلى محرر المحضر أو النيابة العامة بحسب الأحوال أن يعرض التصالح على المتهم أو وكيله ويثبت ذلك فى المحضر . وعلي المتهم الذي يرغب فى التصالح أن يدفع ، قبل رفع الدعوى الجنائية , مبلغا يعادل ثلث الحد الأقصى للغرامة المقرر للجريمة ، ويكون الدفع إلى خزانة المحكمة أو إلى النيابة العامة أو إلي من يرخص له فى ذلك من وزير العدل . ولا يسقط حق المتهم في التصالح برفع الدعوى الجنائية إلى المحكمة المختصة إذا دفع ثلثى الحد الأقصى للغرامة المقررة للجريمة أو قيمة الحد الأدنى المقرر لها أيهما أكثر ، وذلك قبل صدور حكم فى الموضوع . وتنقضي الدعوى الجنائية يدفع مبلغ التصالح ولا يكون لهذا الإنقضاء أثر على الدعوى المدنية"}, {"number": "18 مكرر", "chapter": "الفصل الثالث", "text": "يجوز التصالح فى مواد المخالفات وكذلك فى مواد الجنح التي يعاقب القانون فيها بالغرامة فقط وعلى مأمور الضبط القضائي المختص عند تحرير المحضر أن يعرض التصالح على المتهم أو وكيله في المخالفات ويثبت ذلك في محضره ويكون عرض التصالح في الجنح من النيابة العامة وعلي المتهم الذي يقبل التصالح أن يدفع خلال خمسة عشر يوما من اليوم التالى لعرض التصالح عليه , مبلغا يعادل ربع الحد الأقصى للغرامة المقررة للجريمة أو قيمة الحد الأدنى الحد الأدنى المقرر لها أيهما أكثر , ويكون الدفع إلى خزانة المحكمة أو إلى النيابة العامة أو إلي أى موظف عام يرخص له فى ذلك من وزارة العدل ولا يسقط حق المتهم في التصالح بفوات ميعاد الدفع ولا بإحالة الدعوى الجنائية إلي المحكمة المختصة إذا دفع مبلغا يعادل نصف الحد الأقصى للغرامة المقررة للجريمة أو قيمة الحد الأدنى المقرر لها أيهما أكثر وتنقضي الدعوى الجنائية يدفع مبلغ التصالح ولو كانت مرفوعة بطريق الإدعاء المباشر و ولا يكون لذلك تأثير على الدعوى المدنية"}, {"number": "18", "chapter": "الفصل الثالث", "text": "مكرر -أ – ( مستبدلة بالقانون 145 لسنة 2006 ) للمجني عليه أو وكيله الخاص ولورثته أو وكيلهم الخاص إثبات الصلح مع المتهم أمام النيابة العامة أو المحكمة بحسب الأحوال ، وذلك فى الجنح والمخالفات المنصوص عليها فى المواد 238 ( الفقرتان الأولى والثانية ) و 241( فقرتان أولى وثانية ) ,و 242( فقرات أولى وثانية وثالثة ) و244( الفقرتان الأولى والثانية) , 265, 321 مكررا , 323, 323مكررا , 323مكررا أولا , 324مكررا و336 ، و340, 341 , 342, ,354, 358 ,360, 361(الفقرتان أولى وثانية ),369 و370 و 371 و 373 و377 ( البند 9 ) و378 البنود ( 6، 7، 9 ) و379 ( البند 4 ) من قانون العقوبات وفى الأحوال الأخرى التى ينص عليه القانون ويجوز للمتهم أو وكيله إثبات الصلح المشار إليه فى الفقرة السابقة . ويجوز الصلح فى أية حالة كانت عليها الدعوى ، وبعد صيرورة الحكم باتا . ويترتب علي الصلح انقضاء الدعوى الجنائية ولو كانت مرفوعة بطريق الإدعاء المباشر , وتأمر النيابة العامة بوقف تنفيذ العقوبة إذا حصل الصلح أثناء تنفيذها ولا أثر للصلح على حقوق المضرور من الجريمة المادة19 –و المادة 20 ملغيتان بالقانون رقم 252 لسنة 1953 – الوقائع المصرية – عدد 42-"}, {"number": "21", "chapter": "الفصل الأول", "text": "يقوم مأمورو الضبط القضائى بالبحث عن الجرائم ومرتكبيها وجمع الاستدلالات التى تلزم للتحقيق فى الدعوى-"}, {"number": "22", "chapter": "الفصل الأول", "text": "يكون مأمورو الضبط القضائى تابعين للنائب العام وخاضعين لإشرافه فيما يتعلق بأعمال وظيفتهم . وللنائب العام أن يطلب إلى الجهة المختصة النظر فى كل أمر من تقع منه مخالفات لواجباته ، أو تقصير فى عمله وله أن يطلب رفع الدعوى التأديبية عليه ، وهذا كله لا يمنع من رفع الدعوى الجنائيه."}, {"number": "23", "chapter": "الفصل الأول", "text": "يكون من مأمورى الضبط القضائى فى دوائر اختصاصهم 1 -أعضاء النيابة العامة ومعاونوها . 2 - ضباط الشرطة وأمناؤها والكنستبلات والمساعدون . 3 - رؤساء نقط الشرطة . 4 - العمد والمشايخ البلاد ومشايخ الخفراء . 5 - نظار ووكلاء محطات السكك الحديدية الحكومية ولمد يرى أمن المحافظات ومفتشي مصلحة التفتيش العام بوزارة الداخلية أن يؤدوا الأعمال التى يقوم بها مأمورى الضبط القضائى فى دوائر اختصاصهم . (ب) ويكون من مأمورى الضبط القضائى فى جميع أنحاء الجمهورية 1 - مديرو وضباط إدارة المباحث العامة بوزارة الداخلية وفروعها بمديريات الأمن . 2 - مديرو الإدارات والأقسام ورؤساء المكاتب والمفتشون والضباط وأمناء الشرطة والكونستبلات والمساعدون وباحثات الشرطة العاملون بمصلحة الأمن العام وفى شعب البحث الجنائي بمديريات الأمن . 3 - ضباط مصلحة السجون 4 -مديرو الإدارة العامة لشرطة السكة الحديد والنقل والمواصلات وضباط هذه الإدارة . 5 - قائد وضباط أساس هجانة الشرطة . 6 - مفتشو وزارة السياحة ويجوز بقرار من وزير العدل بالاتفاق مع الوزير المختص تخويل بعض الموظفين صفة مأمورى الضبط القضائى بالنسبة إلى الجرائم التى تقع فى دوائر اختصاصهم وتكون متعلقة بأعمال وظائفهم . وتعتبر النصوص الواردة فى القوانين والمراسيم والقرارات الأخرى بشأن تخويل بعض الموظفين اختصاص مأمورى الضبط القضائى بمثابة قرارات صادرة من وزير العدل بالاتفاق مع الوزير المختص"}, {"number": "24", "chapter": "الفصل الأول", "text": "يجب على مأمورى الضبط القضائى أن يقبلوا البليغات والشكاوى التى ترد إليهم بشأن الجرائم ، وأن يبعثوا بها فورا إلى النيابة العانة ويجب على مرؤ سيهم أن يحصلوا على جميع الإيضاحات ويجروا المعاينات اللازمة لتسهيل تحقيق الوقائع التى تبلغ إليهم ، أو التى يعلنون بها بأى كيفية كانت ، وعليهم أن يتخذوا جميع الوسائل التحفظية اللازمة للمحافظة على أدلة الجريمة . . ويجب أن تثبت جميع الإجراءات التى يقوم بها مأمورو الضبط القضائى فى محاضر موقع عليها منهم يبين بها وقت اتخاذ الإجراءات ومكان حصوله ويجب أن تشمل تلك المحاضر زيادة على ما تقدم توقيع الشهود والخبراء الذين سمعوا، وترسل المحاضر إلى النيابة العامة مع الأوراق المضبوطة ."}, {"number": "24", "chapter": "الفصل الأول", "text": "مكررا – على مأمورى الضبط القضائى ومرؤ سيهم ورجال السلطة العامة أن يبرزوا ما يثبت شخصياتهم وصفاتهم عند مباشرة أى عمل أو إجراء منصوص عليه قانونا ، ولا يترتب على مخالفة هذا الواجب بطلان العمل أو الإجراء ، وذلك دون إخلال بتوقيع الجزاء التأديبي ."}, {"number": "25", "chapter": "الفصل الأول", "text": "لكل من علم بوقوع جريمة ، يجوز للنيابة العامة رفع الدعوى عنها بغير شكوى أو طلب أن يبلغ النيابة العامة أو أحد مأمورى الضبط القضائى عنها ."}, {"number": "26", "chapter": "الفصل الأول", "text": "يجب على كل من علم من الموظفين العموميين أو المكلفين بخدمة عامة أثناء تأدية عمله أو بسبب تأديته بوقوع جريمة من الجرائم يجوز للنيابة العامة رفع الدعوى عنا بغير شكوى أو طلب أن يبلغ عنها فورا النيابة العامة أو أقرب مأمور من مأمورى الضبط القضائى ."}, {"number": "27", "chapter": "الفصل الأول", "text": "لكل من يدعى حصول ضرر له من الجريمة أن يقيم نفسه مدعيا بحقوق مدنية فى الشكوى التى يقدمها إلى النيابة العامة ، أو أحد مأمورى الضبط القضائى . وفى هذه الحالة الأخيرة يقوم المأمور المذكور بتحويل الشكوى إلى النيابة العامة فى المحضر مع يحرره. وعلى النيابة العامة عند إحالة الدعوى إلى قاضى التحقيق أن تحيل معها الشكوى المذكورة ."}, {"number": "28", "chapter": "الفصل الأول", "text": "الشكوى التى لا يدعى فيها مقدمها بحقوق مدنية تعد من قبيل البليغات ولا يعتبر الشاكى مدعيا بحقوق مدنية إلا إذا صرح بذلك فى شكواه أو فى ورقة مقدمة منه بعد ذلك .أو إذا طلب فى إحداهما تعويضا ما ."}, {"number": "29", "chapter": "الفصل الأول", "text": "لمأمورى الضبط القضائى أثناء جمع الاستدلالات أن يسمعوا أقوال من يكون لديه معلومات عن الوقائع الجنائية ومرتكبها وأن يسألوا المتهم عن ذلك ، ولهم أن يستعينوا بالأطباء وغيرهم من أهل الخبرة ويطلبوا رأيهم شفهيا أو بالكتابة . ولا يجوز لهم تحليف الشهود أو الخبراء اليمين إلا إذا خيف ألا يستطاع فيما عد سماع الشهادة بيمين ."}, {"number": "30", "chapter": "الفصل الثانى", "text": "تكون الجريمة متلبسا بها حال إرتكابها أو عقب إرتكابها ببرهة يسيره. وتعتبر الجريمة متلبسا بها إذا إتبع المجنى عليه مرتكبهاأو تبعته العامة مع الصياح أثر وقوعها ، أو إذا وجد مرتكبها بعد وقوعها بوقت قريب حاملا ألات أو أوراقا أو أشياء أخرى يستدل منها على أنه فاعل أو شريك فيها ، أو إذا وجدت به فى هذا الوقت أثار أو علامات تفيد ذلك ."}, {"number": "31", "chapter": "الفصل الثانى", "text": "يجب على مأمور الضبط القضائى فى حالة التلبس بجناية أوجنحة أن ينتقل فورا إلى محل الواقعة ويعاين الأثار المادية للجريمة ويحافظ عليها ، ويثبت حالة الأشخاص ، وكل مايفيد فى كشف الحقيقة ويسمع أقوال من كان حاضرا ، أو من يمكن الحصول منه على إيضاحات فى شأن الواقعة ومرتكبها . ويجب عليه أن يخطر النيابة العامة فورا بإنتقاله ويجب على النيابة العامة بمجرد إخطارها بجناية متلبس بها الإنتقال فورا إلى محل الواقعة."}, {"number": "32", "chapter": "الفصل الثانى", "text": "لمأمور الضبط القضائى عند إنتقاله فى حلة التلبس بالجرائم أن يمنع الحاضرين من مبارحة محل الواقعة أو الإبتعاد عنه حتتى يتم تحرير المحضر ، وله أن يستحضر فى الحال من يمكن الحصول منه على إيضاحات فى شأن الواقعة ."}, {"number": "33", "chapter": "الفصل الثانى", "text": "إذا خالف أحد الحاضرين أمر مأمورى الضبط القضائى وفقا للمادة السابقة ، أو إمتنع أ؛د ممن دعاهم ، عن الحضور يذكر ذلك فى المحضر ويحكم على المخالف بغرامة لاتزيد على ثلاثين جنيها . ويكون الحكم بذلك من المحكمة الجزئية بناء على المحضر الذى يحرره مأمور الضبط القضائى ."}, {"number": "34", "chapter": "الفصل الثالث", "text": "لمأمور الضبط القضائى فى أحوال التلبس بالجنايات أو الجنح التى يعاقب عليها بالحبس لمدة تزيد على ثلاثة أشهر .أن يأمر بالقبض على المتهم الحاضر الذى توجد دلائل كافية على إتهامه ."}, {"number": "35", "chapter": "الفصل الثالث", "text": "— -إذا لم يكن المتهم حاضرا فى الأحوال المبينة بالمادة السابقة جاز لمأمور الضبط القضائى أن يصدر أمر بضبطه وإحضاره ويذكر ذلك فى المحضر . أو فى غير الأحوال المبينة فى المادة السابقة إذا وجدت دلائل كافبة على إتهام شخص بإرتكاب جناية أو جنحة سرقة أو نصب أو تعد شديد أومقاومة لرجال السلطة العامة بالقوة والعنف. جاز لمأمور الضبط القضائى أن يتخذ الإجراءات التحفظية المناسبة ’وأن يطلب فورا من النيابة العامة أن تصدر أمرا بالقبض عليه . وفى جميع الأحوال تنفذ أوامر الضبط والإحضار والإجراءات التحفظية بواسطة أحد المحضرين أو بواسطة أحد رجال السلطة العامة"}, {"number": "36", "chapter": "الفصل الثالث", "text": "يجب على مأمور الضبط القضائى أن يسمع فورا أقوال المتهم المضبوط ، وإذا لم يأت بما يبرئه ، يرسله فى مدى أربعة وعشرين ساعة إلى النيابة العامة المختصة . ويجب على النيابة العامة أن تستجوبه فى ظرف أربع وعشرين ساعة ثم تأمر بالقبض عليه أو إطلاق سراحه ."}, {"number": "37", "chapter": "الفصل الثالث", "text": "لكل من شاهد الجانى متلبسا بجناية أو جنحة يجوز فيها قانونا الحبس الإحتياطى ، أن يسلمه إلى أقرب رجل من رجال السلطة العامة دون إحتياج إلى أمر بضبطه ."}, {"number": "38", "chapter": "الفصل الثالث", "text": "لرجال السلطة العامة ، فى الجنح المتلبس بها التى يجوز الحكم فيها بالحبس أن يحضروا المتهم ويسلموه إلى أقرب مأمور من مأمورى الضبط القضائى . ولهم ذلك أيضا فى الجرائم الأخرى المتلبس بها إذا لم يمكن معرفة شخصية المتهم ."}, {"number": "39", "chapter": "الفصل الثالث", "text": "فيما عدا الأحوال المنصوص عليها فى المادة 9 ( فقرة ثانية ) من هذا القانون فإنه إذا كانت الجريمة المتلبس بها مما يتوقف رفع الدعوى العمومية عنها على شكوى فلا يجوز القبض على المتهم إلا إذا صرح بالشكوى من يملك تقديمها ويجوز فى هذه الحالة أن تكون الشكوى لمن يكون حاضرا من رجال السلطة العامة ."}, {"number": "40", "chapter": "الفصل الثالث", "text": "لا يجوز القبض على أى إنسان أو حبسه إلا بأمر من السلطات المختصة بذلك قانونا ، كما تجب معاملته بما يحفظ عليه كرامة الإنسان ولا يجوز إيذاؤه بدنيا أو معنويا ."}, {"number": "41", "chapter": "الفصل الثالث", "text": "لا يجوز حبس أى إنسان إلا فى السجون المخصصة لذلك ولا يجوز لمأمور أى سجن قبول أى إنسان فيه إلا بمقتضى أمر موقع عليه من السلطة المختصة ، ولا يبقيه بعد المدة المحددة بهذا الأمر ."}, {"number": "42", "chapter": "الفصل الثالث", "text": "لكل من أعضاء النيابة العامة ورؤساء ووكلاء المحاكم الإبتدائية والإستئنافية زيارة السجون العامة والمركزية الموجودة فى دوائر اختصاصهم ، والتأكد من عدم وجود محبوس بصفة غير قانونية ، ولهم أن يطلعوا على دفاتر السجن وعلى أوامر القبض والحبس وأن يأخذوا صورا منها وأن يتصلوا بأى محبوس ويسمعوا منه أى شكوى يريد أن يبديها لهم ، وعلى مدير وموظفى السجون أن يقدموا لهم كل مساعدة لحصولهم على المعلومات التى يطلبونها"}, {"number": "43", "chapter": "الفصل الثالث", "text": "لكل مسجون الحق فى أن يقدم فى أى وقت لمأمور السجن شكوى كتابية أو شفاهية . ويطلب منه تبليغها للنيابةالعامة وعلى المأمور قبولها وتبليغهل فىالحال بعد إثباتها فى سجل يعد لذلك فى السجن . ولكل من علم بوجود محبوس بصفة غير قانونية ، أو فى محل غير مخصص للحبس أن يخطر أحد أعضاء النيابة العامة – وعليه بمجرد علمه أن ينتقل فورا إلى المحل الموجود به النحبوس وأن يقوم بإجراء التحقيق وأن يأمر بالإفراج عن المحبوس بصفة غير قانونية وعليه أن يحرر محضر بذلك ."}, {"number": "44", "chapter": "الفصل الثالث", "text": "تسرى فى حق الشاكى المادة 62ولو لم يدع بحقوق مدنية ."}, {"number": "45", "chapter": "الفصل الرابع", "text": "لا يجوز لرجال السلطة الدخول فى أى محل مسكون إلا فى الأحوال المبينة فى القانون ،أو فى حالة طلب المساعدة من الداخل أو فى حالة الحريق أو الغرق أو ماشابه ذلك."}, {"number": "46", "chapter": "الفصل الرابع", "text": "فى الأحوال التى يجوز فيها القبض قانونا على المتهم يجوز لمأمور الضبط القضائى أن يفتشه . وإذا كان المتهم أنثى وجب أن يكون التفتيش بمعرفة أنثى يندبها لذلك مأمور الضبط القضائى"}, {"number": "47", "chapter": "الفصل الرابع", "text": "هذه المادة ملغاة بحكم المحكمة الدستورية فى الطعن رقم 5 لسنة 4ق فى 2/6/1984-"}, {"number": "48", "chapter": "الفصل الرابع", "text": "ملغاة بالقانون رقم 37 لسنة 1972- الجريدة الرسمية العدد رقم 39 الصادر فى 28/9/1972"}, {"number": "49", "chapter": "الفصل الرابع", "text": "إذا قامت أثناء تفتيش منزل متهم قرائن قوية ضد المتهم أو شخص ، موجود فيه على أنه يخفى معه شيئا يفيد فى كشف الحقيقة ، جاز لمأمور الضبط القضائى أن يفتشه ."}, {"number": "50", "chapter": "الفصل الرابع", "text": "لا يجوز التفتيش إلا للبحث عن الأشياء الخاصة بالجريمة الجارى جمع الإستدلالات أو حصول التحقيق بشأنها . ومع ذلك إذا ظهر عرضا أثناء التفتيش وجود أشياء تعد حيازتها جريمة أو تفيد فى كشف الحقيقة فى جريمة أخرى ، جاز لمأمور الضبط القضائى أن يضبطها ."}, {"number": "51", "chapter": "الفصل الرابع", "text": "يحصل التفتيش بحضور المتهم أو من ينيبه عنه كلما أمكن ذلك ، وإلا فيجب أن يكون بحضور شاهدين ، ويكون هذان الشاهدان بقدر الإمكان من أقاربه البالغين أو من القاطنين معه بالمنزل أو من الجيران ، ويثبت ذلك فى المحضر ."}, {"number": "52", "chapter": "الفصل الرابع", "text": "إذا وجدت فى منزل المتهم أوراق مختومة أو مغلقة بأية طريقة أخرى ، فلا يجوز لمأمور الضبط القضائى أن يفضها ."}, {"number": "53", "chapter": "الفصل الرابع", "text": "لمأمورى الضبط القضائى أن يضعوا الأختام على الأماكن التى بها أثار أو أشياء تفيد فى كشف الحقيقة ولهم أن يقيموا حراسا عليها . ويجب عليهم إخطار النيابة العامة بذلك فى الحال ، وعلى النيابة إذا مارأت ضرورة ذلك الإجراء أن ترفع الأمر إلى القاضى الجزئى لإقراره ."}, {"number": "54", "chapter": "الفصل الرابع", "text": "لحائز العقار أن يتظلم أمام القاضى من الأمر الذى أصدره بعريضة يقدمها إلى النيابة العامة ،وعليها رفع التظلم إلى القاضى فورا ."}, {"number": "55", "chapter": "الفصل الرابع", "text": "لمأمورى الضبط القضائى أن يضبطوا الأوراق والأسلحة وكل مايحتمل أن يكون قد استعمل فى إرتكاب الجريمة أو نتج عن إرتكابها أو ماوقعت عليه الجريمة وكل مايفيد فى كشف الحقيقة . وتعرض هذه الأشياء على المتهم ، ويطلب منه إبداء ملاحظاته عليها ويعمل بذلك محضر يوقع عليه من المتهم ، أو يذكر فيه إمتناعه عن التوقيع"}, {"number": "56", "chapter": "الفصل الرابع", "text": "توضع الأشياء والأوراق التى تضبط فى حرز مغلق وتربط كلما أمكن ،ـ ويختم عليها ، ويكتب على شريط داخل الختم تاريخ المحضر المحرر بضبط تلك الأشياء ، ويشار إلى الموضوع الذى حصل الضبط من أجله"}, {"number": "57", "chapter": "الفصل الرابع", "text": "لا يجوز فض الأختام الموضوعة طبقا للمادتين 53و56إلا بحضور المتهم أو وكيله ، ومن ضبطت عنده هذه الأشِياء أو بعد دعوتهم لذلك ."}, {"number": "58", "chapter": "الفصل الرابع", "text": "كل من يكون قد وصل إلى علمه بسبب التفتيش معلومات عن الأشياء والأوراق المضبوطة ، وأفضى بها إلى أى شخص غير ذى صفة أو إنتفع بها بأى طريقة كانت ، يعاقب بالعقوبات المقررة بالمادة 310من قانون العقوبات ."}, {"number": "59", "chapter": "الفصل الرابع", "text": "إذا كان لمن ضبطت عنده الأوراق مصلحة عاجلة فيها تعطى له صورة منها موقع عليها من مأمور الضبط القضائى ."}, {"number": "60", "chapter": "الفصل الرابع", "text": "لمأمورى الضبط القضائى فى حالة قيامهم بواجباتهم أن يستعينوا مباشرة بالقوة العسكرية ."}, {"number": "61", "chapter": "الفصل الخامس", "text": "إذا رأت النيابة العامة أن لامحل للسير فى الدعوى ، تأمر بحفظ الأوراق"}, {"number": "62", "chapter": "الفصل الخامس", "text": "إذا أصدرت النيابة العامة أمرا بالحفظ ، وجب عليها أن تعلنه إلى المجني عليه ، وإلي المدعي بالحقوق المدنية، فإذا توفى أحدهما كان الإعلان لورثته جملة فى محل إقامته"}, {"number": "63", "chapter": "الفصل الخامس", "text": "إذا رأت النيابة العامة فى مواد المخالفات والجنح أن الدعوى صالحة لرفع بناء على الاستدلالات التى جمعت ، تكلف المتهم بالحضور مباشرة أمام المحكمة المختصة . وللنيابة العامة فى مواد الجنح والجنايات أن تطلب ندب قاضى التحقيق طبقا للمادة 64 من هذا القانون ، أو أن تتولى هى التحقيق طبقا للمادة 199 وما بعدها من هذا القانون . وفيما عدا الجرائم المشار إليها فى المادة 123 من قانون العقوبات لا يجوز لغير النائب العام أو المحامى العام أو رئيس النيابة العامة رفع الدعوى الجنائية ضد موظف أو مستخدم عام أو أحد رجال الضبط لجناية أو جنحة وقعت منه أثناء تأدية وظيفته أو بسببها واستثناء من حكم المادة 237 من هذا القانون ، يجوز للمتهم عند رفع الدعوى عليه بطريق الإدعاء المباشر أن ينيب عنه – فى أية مرحلة كانت عليها الدعوى – وكيلا لتقديم دفاعه ،وذلك مع عدم الإخلال بما للمحكمة من حق فى أن تأمر بحضوره شخصيا"}, {"number": "64", "chapter": "الفصل الأول", "text": "إذا رأت النيابة العامة فى مواد الجنايات أو الجنح أن تحقيق الدعوى بمعرفة قاضى التحقيق أكثر ملاءمة بالنظر إلى ظروفها الخاصة جاز لها فى أية حالة كانت عليها الدعوى أن تطلب إلى رئيسٍ المحكمة الابتدائية ندب أحد قضاة المحكمة لمباشرة هذا التحقيق ."}, {"number": "65", "chapter": "الفصل الأول", "text": "لوزير العدل أن يطلب من محكمة الاستئناف ندب مستشار لتحقيق جريمة معينة أو جرائم من نوع معين ، ويكون الندب بقرار من الجمعية العامة، وفي هذه الحالة يكون المستشار المندوب هو المختص دون غيره بإجراء التحقيق من وقت مباشرته العمل ."}, {"number": "66", "chapter": "الفصل الأول", "text": "ملغاة بالمرسوم بقانون رقم 353 لسنة 1953 )"}, {"number": "67", "chapter": "الفصل الأول", "text": "لا يجوز لقاضى التحقيق مباشرة التحقيق فى جريمة معينة إلا بناء على طلب من النيابة العامة أو بناء على إحالتها إليه من الجهات الأخرى المنصوص عليها فى القانون ."}, {"number": "68", "chapter": "الفصل الأول", "text": "ملغاة بالمرسوم بقانون رقم 353 لسنة 1953 )"}, {"number": "69", "chapter": "الفصل الثانى", "text": "متى أحيلت الدعوى إلى قاضى التحقيق كان مختصا دون غيره بتحقيقها."}, {"number": "70", "chapter": "الفصل الثانى", "text": "لقاضى التحقيق أن يكلف أحد أعضاء النيابة العامة أو أحد مأموري الضبط القضائى القيام بعمل معين أو أكثر من أعمال التحقيق عدا استجواب المتهم ويكون للمندوب فى حدود ندبه كل السلطة التى لقاضى التحقيق . وله إذا دعت الحال لاتخاذ إجراء من الإجراءات خارج دائرة اختصاصه أن يكلف به قاضى محكمة الجهة أو أحد أعضاء النيابة العامة أو أحد مأموري الضبط القضائي بها . وللقاضى المندوب أن يكلف بذلك عند الضرورة أحد أعضاء النيابة العامة أو أحد مأموري الضبط القضائي طبقا للفقرة الأولى . ويجب على قاضى التحقيق أن ينتقل بنفسه للقيام بهذا الإجراء كلما اقتضت مصلحة التحقيق ذلك ."}, {"number": "71", "chapter": "الفصل الثانى", "text": "يجب على قاضى التحقيق فى جميع الأحوال التى يندب فيها غيره لإجراء بعض تحقيقات أن يبين المسائل المطلوب تحقيقها والإجراءات المطلوب اتخاذها . وللمندوب أن يجرى أى عمل أخر من أعمال التحقيق ،أو أن يستجوب المتهم فى الأحوال التى يخشى فيها فوات الوقت متى كان متصلا بالعمل المندوب له ولازما فى كشف الحقيقة ."}, {"number": "72", "chapter": "الفصل الثانى", "text": "يكون لقاضى التحقيق ما للمحكمة من الإختصاصات فيما يتعلق بنظام الجلسة . ويجوز الطعن فى الأحكام التى يصدرها وفقا لما هو مقرر للطعن فى الأحكام الصادرة من القاضى الجزئى."}, {"number": "73", "chapter": "الفصل الثانى", "text": "يستصحب قاضى التحقيق فى جميع إجراءاته كاتبا من كتاب المكمة يوقع معه المحاضر وتحفظ هذه المحاضر مع الأوامر وباقى الأوراق فى قلم كتاب المحكمة ."}, {"number": "74", "chapter": "الفصل الثانى", "text": "معدلة بالقانون رقم 107 لسنة 1963 ) على رئيس المحكمة الإشراف على قيام القضاة الذين يندبون لتحقيق وقائع معينة بأعمالهم بالسرعة اللازمة وعلى مراعاتهم للمواعيد المقررة فى القانون ."}, {"number": "75", "chapter": "الفصل الثانى", "text": "تعتبر إجراءات التحقيق ذاتها والنتائج التى تسفر عنها من الأسرار ويجب على قضاة التحقيق وأعضاء النيابة العامة ومساعديهم من كتاب وخبراء وغيرهم ممن يتصلون بالتحقيق أو يحضرونه بسبب وظيفتهم أو مهنتهم عدم إفشائها ومن يخالف ذلك منهم يعاقب طبقا للمادة 310 من قانون العقوبات"}, {"number": "76", "chapter": "الفصل الثانى", "text": "لمن لحقه ضرر من الجريمة أن يدعى بحقوق مدنية أثناء التحقيق فى الدعوى . ويفصل قاضى التحقيق نهائيا فى قبوله بهذه الصفة فى التحقيق"}, {"number": "77", "chapter": "الفصل الثانى", "text": "للنيابة العامة وللمتهم وللمجنى عليه وللمدعى بالحقوق المدنية وللمسئول عنها ولوكلائهم أن يحضروا جميع إجراءات التحقيق ، ولقاضى التحقيق أن يجرى التحقيق فى غيبتهم متى رأى ضرورة ذلك لإظهار الحقيقة وبمجرد إنتهاء تلك الضرورة يبيح لهم الإطلاع على التحقيق . ومع ذلك فلقاضى التحقيق أن يباشر فى حالة الإستعجال بعض إجراءات التحقيق فى غيبة الخصوم ، ولهؤلاء الحق فى الإطلاع على الأوراق المثبتة لهذه الإجراءات . وللخصوم دائما الحق فى إستصحاب وكلائهم فى التحقيق ."}, {"number": "78", "chapter": "الفصل الثانى", "text": "يخطر الخصوم باليوم الذى يباشر فيه القاضى إجراءات التحقيق وبمكانها ."}, {"number": "79", "chapter": "الفصل الثانى", "text": "يجب على كل من المجنى عليه والمدعى بالحقوق المدنية والمسئول عنها أن يعين له محلا فى البلدة الكائن فيها مركز المحكمة التى يجرى فيها التحقيق إذا لم يكن مقيما فيها ، وإذ لم يفعل ذلك يكون إعلانه فى قلم الكتاب بكل مايلزم إعلانه به صيحا ."}, {"number": "80", "chapter": "الفصل الثانى", "text": "للنيابة العامة الإطلاع فى أى وقت على الأوراق لتقف على ماجرى فى التحقيق على ألا يترتب على ذلك تأخير السير فيه ."}, {"number": "81", "chapter": "الفصل الثانى", "text": "للنيابة العامة وياقى الخصوم أن يقدموا إلى قاضى التحقيق الدفوع والطلبات التى يرون تقديمها أثناء التحقيق ."}, {"number": "82", "chapter": "الفصل الثانى", "text": "يفصل قاضى التحقيق فى ظرف أربعة وعشرين ساعة فى الدفوع والطلبات المقدمة إليه ، ويبين الأسباب التى يستند إليها ."}, {"number": "83", "chapter": "الفصل الثانى", "text": "إذا لم تكن أوامر قاضى التحقيق صدرت فى مواجهة الخصوم تبلغ إلى النيابة العامة وعليها أن تعلنها لهم فى ظرف أربع وعشرين ساعة من تاريخ صدورها ."}, {"number": "84", "chapter": "الفصل الثانى", "text": "للمتهم وللمجنى عليه وللمدعى بالحقوق المدنية وللمسئول عنها أن يطلبوا على نفقتهم أثناء التحقيق صورا من الأوراق أيا كان نوعها ، إلا إذا كان حاصلا بغير حضورهم بناء على قرار صادر بذلك ."}, {"number": "85", "chapter": "الفصل الثالث", "text": "إذا إستلزم إثبات الحالة الإستعانة بطبيب أو غيره من الخبراء يجب على قاضى التحقيق الحضور وقت العهمل وملاحظته وإذا إقتضى الأمر إثبات الالة بدون حضور قاضى التحقيق نظرا إلى ضرورة القيام بأعمال تحضيرية أو تجارب متكررة أو لأى سبب أخر وجب على قاضىة التحقيق أن يصدر أمرا يبين فيه أنواع التقيقات ومايرد إثباتن حالته . ويجوز فى جميع الأحوال ، أن يؤدى الخبير مأموريته بغير حضور الخصوم"}, {"number": "86", "chapter": "الفصل الثالث", "text": "يجب على الخبراء أن يحلفوا أمام قاضى التحقيق يمينا على أن يبدوا رأيهم بالذمة وعليهم أن يقدموا تنقريرهم كتابة ."}, {"number": "87", "chapter": "الفصل الثالث", "text": "يحدد قاضى التحقيق ميعادا للخبير ليقدم نقريره فيه وللقاضى أن يستبدل به خبيرا أخر إذا لم يقدم التقرير فى الميعاد المدد"}, {"number": "88", "chapter": "الفصل الثالث", "text": "للمتهم أن يستعين بخبير إستشارى ويطلب تمكينه من الإطلاع على الأوراق وسائر ماسبق تقديمه للخبير المعين من القاضى على ألا يترتب على ذلك تأخير السير فلا الدعوى ."}, {"number": "89", "chapter": "الفصل الثالث", "text": "للخصوم رد الخبير إذا وجدت أسباب قوية تدعو لذلك ويقدم طلب الرد إلى قاضى التحقيق للفصل فيه ، ويجب أن تبين بفيه أسباب الرد ، وعلى القاضى الفصل فيه فى مدة ثلاثة أيام من يوم تقديمه . ويترتب على هذا الطلب عدم إستمرار الخبير فى عمله إلا فى الة الإستعجال بأمر من القاضى"}, {"number": "90", "chapter": "الفصل الرابع", "text": "ينتقل قاضى التحقيق إلى أى مكان كلما رأى ذلك ليثبت حالة الأمكنة والأشياء والأشخاص ووجود الجريمة ماديا وكل مايلزم إثبات حالته ."}, {"number": "91", "chapter": "الفصل الرابع", "text": "( معدلة بالقانون رقم 37 لسنة 1972 الجريدة الرسمية – عدد رقم 39 الصادر فى 28/9/1972 ) تفتيش المنازل عمل من أعمال التحقيق ولا يجوز الالتجاء إليه إلا بمقتضى أمر من قاضى التحقيق بناء على اتهام موجه إلى شخص يقيم فى المنزل المراد تفتيشه بارتكاب جناية أو جنحة أو باشتراكه فى ارتكابها أو إذا وجدت قرائن تدل على أنه حائز لأشياء تتعلق بالجريمة ولقاضى التحقيق أن يفتش أى مكان ويضبط فيه الأوراق والأسلحة وكل ما يحتمل أنه استعمل فى ارتكاب الجريمة أو نتج عنها أو وقعت عليه وكل ما يفيد فى كشف الحقيقة وفى جميع الأحوال يجب أن يكون أمر التفتيش مسببا"}, {"number": "92", "chapter": "الفصل الرابع", "text": "يحصل التفتيش بحضور المتهم أو من ينيبه عنه إن أمكن ذلك . وإذا حصل التفتيش فى منزل غير المتهم يدعى صاحبه للحضور بنفسه أو بواسطة من ينيبه عنه إن أمكن ذلك \"\""}, {"number": "93", "chapter": "الفصل الرابع", "text": "على قاضى التحقيق كلما رأى ضرورة للانتقال للأمكنة أو للتفتيش أن يخطر بذلك النيابة العامة ."}, {"number": "94", "chapter": "الفصل الرابع", "text": "\"\" لقاضى التحقيق أن يفتش المتهم وله أن يفتش غير المتهم إذا اتضح من إمارات قوية أنه يخفى أِشياء تفيد فى كشف الحقيقة ويراعى فى التفتيش حكم الفقرة الثانية من المادة 46\"\""}, {"number": "95", "chapter": "الفصل الرابع", "text": "\"\" لقاضى التحقيق أن يأمر بضبط جميع الخطابات والرسائل والجرائد والمطبوعات والطرود لدى مكاتب البريد وجميع البرقيات لدى مكاتب البرق وأن يأمر بمراقبة المحادثات السلكية واللاسلكية أو إجراء تسجيلات لأحاديث جرت فى مكان خاص متى كان لذلك فائدة فى ظهور الحقيقة فى جناية أو جنحة معاقب عليها بالحبس لمدة تزيد على ثلاثة أشهر . وفى جميع الأحوال يجب أن يكون الضبط أو الإطلاع أو المراقبة أو التسجيل بناء على أمر مسبب ولمدة لاتزيد على ثلاثين يوما قابلة للتجديد لمدة أو لمدد أخرى مماثلة \"\""}, {"number": "95", "chapter": "الفصل الرابع", "text": "مكرر ( مضافة بالقانون رقم 98 لسنة 1995 – الوقائع المصرية – العدد رقم 18 مكرر ) \"\" لرئيس المحكمة الابتدائية المختصة فى حالة قيام دلائل قوية على أن مرتكب إحدى الجرائم المنصوص عليها فى المادتين 166 مكررا و308 مكررا من قانون العقوبات قد استعان فى ارتكابها بجهاز تليفونى معين أمر بناء على تقرير مدير عام مصلحة التلغرافات والتليفونات وشكوى المجني عليه فى الجريمة المذكورة بوضع جهاز التليفون المذكور تحت الرقابة للمدة التى يحددها \"\""}, {"number": "96", "chapter": "الفصل الرابع", "text": "\"\" لا يجوز لقاضى التحقيق أن يضبط لدى المدافع عن المتهم أو الخبير الاستشاري الأوراق والمستندات التى سلمها المتهم لهما لأداء المهمة التى عهد إليهما بها ، ولا المراسلات المتبادلة بينهما فى القضية \"\""}, {"number": "97", "chapter": "الفصل الرابع", "text": "يطلع قاضى التحقيق وحده على الخطابات والرسائل والأوراق الأخرى المضبوطة ، على أن يتم هذا إذا أمكن بحضور المتهم والحائز لها أو المرسلة إليه ويدون ملاحظاته عليها. وله عند الضرورة أن يكلف أحد أعضاء النيابة العامة بفرز الأوراق المذكورة وله حسب مايظهر من الفحص أن يأمر بضم تلك الأوراق إلى ملف القضية أو يردها إلى من كان حائزا لها أو إلى المرسلة إليه ."}, {"number": "98", "chapter": "الفصل الرابع", "text": "الأشياء التى تظبط يتبع نحوها أحكام المادة 56 ."}, {"number": "99", "chapter": "الفصل الرابع", "text": "لقاضى التحقيق أن يأمر الحائز لشىء يرى ضبطه أو الإطلاع عليه بتقديمه ، ويسرى حكم المادة 284 على من يخالف ذلك الأمر إلا إذا كان فى حالة من الأحوال التى يخو له القانون فيها الإمتناع عن أداء الشهادة ."}, {"number": "100", "chapter": "الفصل الرابع", "text": "تبلغ الخطابات والرسائل التلغرافية المضبوطة إلى المتهم أو المرسلة إليه ، أو تعطى إليهما صورة منها فى أقرب وقت إلا إذا كان فى ذلك إضرارا بسير التحقيق . ولكل شخص يدعى حقا فى الأِشياء المضبوطة أن يطلب إلى قاضى التحقيق تسليمها إليه ، وله فى حالة الرفض أن يتظلم أمام محكمة الجنح المستأنفة منعقدة فى غرفة المشورة وأن يطلب سماع أقواله أمامها ."}, {"number": "101", "chapter": "الفصل الخامس", "text": "يجوز أن يأمر برد الأشياء التى ضبطت أثناء التحقيق ولو كان ذلك قبل الحكم، مالم تكن لازمة للسير فى الد عوى أو محلا للمصادرة ."}, {"number": "102", "chapter": "الفصل الخامس", "text": "يكون رد الأشياء المضبوطة إلى من كانت فى حيازته وقت ضبطها وإذا كانت المضبوطات من الأشياء التى وقعت عليها الجريمة أو المتحصلة عنها يكون ردها إلى من فقد حيازتها بالجريمة ، مالم يكن لمن ضبطت معه حق فى حبسها بمقتضى القانون ."}, {"number": "103", "chapter": "الفصل الخامس", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) يصدر الأمر بالرد من النيابة العامة أو قاضى التحقيق أو محكمة الجنح المستأنفة منعقدة فى غرفة المشورة ، ويجوز للمحكمة أن تأمر بالرد أثناء نظر الدعوى ."}, {"number": "104", "chapter": "الفصل الخامس", "text": "لا يمنع الأمر بالرد ذوى الشأن من المطالبة أمام المحاكم المدنية بما لهم من حقوق ، وإنما لا يجوز ذلك للمتهم أو المدعى بالحقوق المدنية إذا كان الأمر بالرد قد صدر من المحكمة بناء على طلب أيهما فى مواجهة الأخر ."}, {"number": "105", "chapter": "الفصل الخامس", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) يؤمر بالرد ولو من غير طلب . ولا يجوز للنيابة العامة ولقاضى التحقيق الأمر بالرد عند المنازعة ويرفع الأمر فى هذه الحالة أو فى حالة وجود شك فيمن له الحق فى تسلم الشىء إلى محكمة الجنح المستأنفة منعقدة فى غرفة المشورة بالمحكمة الإبتدائية بناء على طلب ذوى الشأن لتأمر بما تراه ."}, {"number": "106", "chapter": "الفصل الخامس", "text": "يجب عند صدور أمر بالحفظ ، أو بـأن لاوجه لإقامة الدعوى أن يفصل فى كيفية التصرف فى الأِشياء المضبوطة وكذلك الحال عند الحكم فى الدعوى إذا حصلت المطالبة بالرد أمام المحكمة ."}, {"number": "107", "chapter": "الفصل الخامس", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) للمحكمة أو لمحكمة الجنح المستأنفة منعقدة فى غرفة المشورة أن تأمر بإحالة الخصوم للتقاضى أمام المحاكم المدنية إذا رأت موجبا لذلك وفى هذه الحالة يجوز وضع الأِشياء المضبوطة تحت الحراسة أو اتخاذ وسائل تحفظية أخرى نحوها ."}, {"number": "108", "chapter": "الفصل الخامس", "text": "الأِشياء المضبوطة التى لايطلبها أصحابها فى ميعاد ثلاث سنوات من تاريخ إنتهاء الدعوى تصبح ملكا للحكومة بغير حاجة إلى حكم يصدر بذلك ."}, {"number": "109", "chapter": "الفصل الخامس", "text": "إذا كان الشىء المضبوط مما يتلف بمرور الزمن أو يستلزم حفظه نفقات تستغرق قيمته ، جاز أن يؤمر ببيعه بطريق المزاد العام متى سمحت بذلك مقتضيات التحقيق ، وفى هذه الحالة يكون لصاحب الحق فيه أن يطالب فى الميعاد المبين فى المادة السابقة بالثمن الذى بيع به"}, {"number": "110", "chapter": "الفصل السادس", "text": "يسمع قاضى التحقيق شهادة الشهود الذين يطلب الخصوم سماعهم مالم ير عدم الفائدة من سماعهم . وله أن يسمع شهادة من يرى لزوم سماعه من الشهود عن الوقائع التى تثبت أو تؤدى إلى ثبوت الجريمة وظروفها وإسنادها إلى المتهم أو براءته منها ."}, {"number": "111", "chapter": "الفصل السادس", "text": "تقوم النيابة العامة بإعلان الشهود الذين يقرر قاضى التحقيق سماعهم ، ويكون تكليفهم بالحضور بواسطة المحضرين أو بواسطة رجال السلطة العامة . ولقاضى التحقيق أن يسمع شهادة أى شاهد يحضر من تلقاء نفسه وفى هذه الحالة يثبت ذلك فى المحضر ."}, {"number": "112", "chapter": "الفصل السادس", "text": "يسمع القاضى كل شاهد على إنفراد ، وله أن يواجه الشهود بعضهم ببعض وبالمتهم ."}, {"number": "113", "chapter": "الفصل السادس", "text": "يطلب القاضى من كل شاهد أن يبين إسمه ولقبه، وسنه ، وصناعته وسكنه ، وعلاقته بالمتهم ، ويدون هذه البيانات وشهادة الشهود بغير كشط أو تحشير . ولايعتمد أى تصحيح أو شطب أو تخريج إلا إذا صدق عليه القاضى والكاتب والشاهد ."}, {"number": "114", "chapter": "الفصل السادس", "text": "يضع كل من القاضى والكاتب إمضاءه على الشهادة وكذلك الشاهد بعد تلاوتها عليه وإقراره بـأنه مصر عليها فإن إمتنع عن إمضائه أو ختمه أو لم يمكنه وضعه أثبت ذلك فى المحضر مع ذكر الأسباب التى يبديها وفى كل الأحوال يضع كل من القاضى والكاتب إمضاءه على كل صفحة أولا بأول ."}, {"number": "115", "chapter": "الفصل السادس", "text": "عند الإنتهاء من سماع أقوال الشاهد يجوز للخصوم إبداء ملاحظاتهم عليها. ولهم أن يطلبوا من قاضى التحقيق سماع أقوال الشاهد عن نقط أخرى يبيوننها وللقاضى دائما أن يرفض توجيه أى سؤال ليس له تعلق بالدعوى أو يكون فى صيغته مساس بالغير ."}, {"number": "116", "chapter": "الفصل السادس", "text": "تطبق فيما يختص بالشهود أحكام المواد 283، 285، 286، 287 ، 288. ."}, {"number": "117", "chapter": "الفصل السادس", "text": "مستبدلة بالقانون رقم 29 لسنة 1982- الجريدة الرسمية – ) يجب على كل من دعى للحضور أمام قاضى التحقيق لتأدية شهادة أن يحضر بناء على الطلب المحرر إليه وإلا جاز للقاضى الحكم عليه بعد سماع أقوال النيابة العامة بدفع غرامة لاتجاوز خمسين جنيها ويجوز له أن يصدر أمرا بتكليفه بالحضور ثانيا بمصاريف من طرفه ، أو أن يصدر أمرا بضبطه وإحضاره ."}, {"number": "118", "chapter": "الفصل السادس", "text": "إذا حضر الشاهد أمام القاضى بعد تكليفه بالحضور ثانيا أو من تلقاء نفسه وأبدى أ‘ذار مقبولة ، جاز إعفاؤه من الغرامة بعد سماع أقوال النيابة العامة ، كما يجوز إعفاؤه بناء على طلب يقدم منه إذا لم يستطع الضور بنفسه ."}, {"number": "119", "chapter": "الفصل السادس", "text": "مستبدلة بالقانون رقم 29 لسنة 1982 – ) إذا حضر الشاهد أمام القاضى وإمتنع عن أداء الشهادة أو عن حلف اليمين ، يحكم عليه القاضى فى الجنح والجنايات بعد سماع أقوال النيابة العامة بغرامة لاتزيد على مائتى جنيه. ويجوز إعفاءه من كل أو بعض العقوبة إذا عدل عن إمتناعه قبل إنتهاء التحقيق ."}, {"number": "120", "chapter": "الفصل السادس", "text": "مستبدلة بالقانون رقم 29 لسنة 1982 - ) يجوز الطعن فى الأحكام الصادرة على الشهود من قاضى التحقيق طبقا للمادتين 117 ، 119 وتراعى فى ذلك القواعد والأوضاع المقررة فى القانون ."}, {"number": "121", "chapter": "الفصل السادس", "text": "مستبدلة بالقانون رقم 29 لسنة 1982 - ) إذا كان الشاهد مريضا أو لديه مايمنعه من الحضور تسمع شهادته فى محل وجوده ، فإذا إنتقل القاضى لسماع شهادته وتبين له عدم صحة العذر جاز له أن يحكم عليه بغرامة لاتجاوز مائتى جنيه . وللمحكوم عليه أن يطعن فى الحكم الصادر عليه بطريق المعارضة أو الإستئناف طبقا لما هو مقرر فى المواد السابقة ."}, {"number": "122", "chapter": "الفصل السادس", "text": "يقدر قاضى التحقيق بناء على طلب الشهود المصاريف والتعويضات التى يستحقونها بسبب حضورهم لأداءالشهادة ."}, {"number": "123", "chapter": "الفصل السابع", "text": "عند حضور المتهم لأول مرة فى التحقيق يجب على المحقق أن يثبت من شخصيته ثم يحيطه علما بالتهمة المنسوبة إليه ويثبت أقواله فى المحضر . ويجب على المتهم بارتكاب جريمة القذف بطريق النشر فى إحدى الصحف أو غيرها من المطبوعات أن يقدم للمحقق عند أول استجواب له وعلى الأكثر فى الخمسة الأيام التالية بيان الأدلة على كل فعل أسند إلى موظف عام أو شخص ذى صفة نيابية عامة أو مكلف بخدمة عامة وإلا سقط حقه فى إقامة الدليل المشار إليه فى الفقرة من المادة 302 من قانون العقوبات فإذا كلف المتهم بالحضور أمام المحكمة مباشرة وبدون تحقيق سابق وجب عليه أن يعلن إلى النيابة والمدعى بالحق المدنى بيان الأدلة فى الخمسة الأيام التالية لاعلان التكليف بالحضور وإلا سقط حقه كذلك فى إقامة الدليل . ولا يجوز تأجيل نظر الدعوى فى هذه الأحوال أكثر من مرة واحدة لمدة لا تزيد على ثلاثين يوما وينطق بالحكم مشفوعا بأسبابه ."}, {"number": "124", "chapter": "الفصل السابع", "text": "مستبدلة بالقانون 145 لسنة 2006 - ) \"\" لايجوز للمحقق فى الجنايات وفى الجنح المعاقب عليها بالحبس وجوبا أن يستجوب المتهم أو يواجهه بغيره من المتهمين أو الشهود إلا بعد دعوة محاميه للحضور عدا حالة التلبس وحالة السرعة بسبب الخوف من ضياع الأدلة على النحو الذى يثبته المحقق فى المحضر ، وعلى المتهم أن يعلن اسم محاميه بتقرير يكتب فى قلم كتاب المحكمة أو إلى مأمور السجن ، أو يخطر به المحقق ،كما يجوز لمحاميه أن يتولى هذا الإعلان أو الإخطار . وإذا لم يكن للمتهم محام ، أو لم يحضر محاميه بعد دعوته ، وجب على المحقق من تلقاء نفسه ، أن يندب له محاميا . وللمحامى أن يثبت فى المحضر مايعن له من دفوع أو طلبات أو ملاحظات . \"\" ويصدر المحقق بعد التصرف النهائى فى التحقيق بناء على طلب المحامى المنتدب أمرا بتقدير أتعابه وذلك إسترشادا بجدول تقدير الأتعاب الذى يصدر به قرار من وزير العدل بعد أخذ رأى مجلس النقابة العامة للمحامين وتأخذ هذه الأتعاب حكم الرسوم القضائية \""}, {"number": "125", "chapter": "الفصل السابع", "text": "معدلة بالقانون رقم 37 لسنة 1972 ) \"\" يجب السماح للمحامى بالإطلاع على التحقيق فى اليوم السابق على الاستجواب أو المواجهة مالم يقرر القاضى غير ذلك وفى جميع الأحوال لا يجوز الفصل بين المتهم ومحاميه الحاضر معه أثناء التحقيق \"\""}, {"number": "126", "chapter": "الفصل الثامن", "text": "\"\" لقاضى التحقيق فى جميع المواد أن يصدر حسب الأحوال أمرا بحضور المتهم ، أو بالقبض عليه وإحضاره \"\""}, {"number": "127", "chapter": "الفصل الثامن", "text": "يجب أن يشتمل كل أمر على اسم المتهم ، ولقبه ، وصناعته ، ومحل إقامته والتهمة المنسوبة إليه وتاريخ الأمر وإمضاء القاضى والختم الرسمي .ويشمل الأمر بحضور المتهم فضلا عن ذلك تكليفه بالحضور فى ميعاد معين .ويشتمل أمر القبض والإحضار تكليف رجال السلطة العامة بالقبض على المتهم وإحضاره أمام القاضى ، إذا رفض الحضور طوعا فى الحال .ويشمل أمر الحبس تكليف مأمور السجن بقبول المتهم ووضعه فى السجن مع بيان مادة القانون المنطبقة على الواقعة .\"\""}, {"number": "128", "chapter": "الفصل الثامن", "text": "تعلن الأوامر إلى المتهم بمعرفة أحد المحضرين أو أحد رجال السلطة العامة ، وتسلم له صورة منها ."}, {"number": "129", "chapter": "الفصل الثامن", "text": "تكون الأوامر التى يصدرها قاضى التحقيق نافذة فى جميع الأراضى المصرية ."}, {"number": "130", "chapter": "الفصل الثامن", "text": "\"\" إذا لم يحضر المتهم بعد تكليفه بالحضور دون عذر مقبول أو إذا خيف هربه ، أو إذا لم يكن له محل إقامة معروف أو إذا كانت الجريمة فى حالة تلبس ، جاز لقاضى التحقيق أن يصدر أمرا بالقبض على المتهم وإحضاره ولو كانت الواقعة مما لا يجوز فيها حبس المتهم"}, {"number": "131", "chapter": "الفصل الثامن", "text": "\"\" يجب على قاضى التحقيق أن يستجوب فورا المتهم المقبوض عليه وإذا تعذر ذلك يودع فى السجن إلى حين استجوابه ويجب ألا تزيد مدة إيداعه على أربع وعشرين ساعة فإذا مضت هذه المدة وجب على مأمور السجن تسليمه إلى النيابة العامة ، وعليها أن تطلب فى الحال إلى قاضى التحقيق استجوابه . وعند الاقتضاء تطلب ذلك إلى القاضى الجزئي أو رئيس المحكمة أو أى قاضى أخر يعينه رئيس المحكمة وإلا أمرت بإخلاء سبيله \"\""}, {"number": "132", "chapter": "الفصل الثامن", "text": "\"\" إذا قبض على المتهم خارج دائرة المحكمة التي يجرى التحقيق فيها ، يرسل إلى النيابة العامة بالجهة التي قبض عليه فيها . وعلى النيابة العامة أن تتحقق من جميع البيانات الخاصة بشخصه وتحيطه علما بالواقعة المنسوبة إليه وتدون أقواله فى شأنها \"\""}, {"number": "133", "chapter": "الفصل الثامن", "text": "إذا أعترض المتهم على نقله أو كانت حالته الصحية لاتسمح بالنقل يخطر قاضى التحقيق بذلك وعليه أن يصدر أمره فورا بما يتبع \"\""}, {"number": "134", "chapter": "الفصل التاسع", "text": "مستبدلة بالقانون 145 لسنة 2006 ) يجوز لقاضى التحقيق بعد استجواب المتهم أو فى حالة هربه إذا كانت الواقعة جناية أو جنحة معاقبا عليها بالحبس لمدة لاتقل عن سنة ، والدلائل عليها كافية ، أن يصدر أمر بحبس المتهم إحتياطيا ، وذلك إذا توافرت إحدى الحالات أو الدواعى الآتية : 1- إذا كانت الجريمة فى حالة تلبس 2- الخشية من هروب المتهم 3- خشية الإضرار بمصلحة التحقيق سواء بالتأثير على المجنى عليه أو الشهود ، أو العبث فى الأدلة أو القرائن المادية ، أو بإجراء إتفاقات مع باقى الجناة لتغيير الحقيقة أو طمس معالمها. 4- توقى الإخلال الجسيم بالأمن والنظام العام الذى قد يترتب على جسامة الجريمة . ومع ذلك يجوز حبس المتهم إحتياطيا إذا لم يكن له محل إقامة ثابت معروف فى مصر ، وكانت الجريمة جناية أو جنحة معاقبا عليها بالحبس ."}, {"number": "135", "chapter": "الفصل التاسع", "text": "( ملغاة بالقانون رقم 93 لسنة 95 العدد 21 مكرر فى 28/5/1995 )"}, {"number": "136", "chapter": "الفصل التاسع", "text": "( مستبدلة بالقانون 145 لسنة 2006 ) يجب على قاضى التحقيق قبل أن يصدر أمر بالحبس أن يسمع أقوال النيابة العامة ودفاع المتهم. ويجب أن يشتمل أمر الحبس على بيان الجريمة المسندة إلى المتهم والعقوبة المقررة لها ، والأسباب التى بنى عليها الأمر . ويسرى حكم هذه المادة على الأوامر التى تصدر بمد الحبس الإحتياطى ، وفقا لأحكام هذا القانون ."}, {"number": "137", "chapter": "الفصل التاسع", "text": "للنيابة العامة فى أى وقت أن تطلب حبس المتهم إحتياطيا ."}, {"number": "138", "chapter": "الفصل التاسع", "text": "يجب عند إيداع المتهم السجن بناء على أمر الحبس أن تسلم صورة من هذا الأمر إلى مأمور السجن بعد توقيعه على الأصل بالإستلام ."}, {"number": "139", "chapter": "الفصل التاسع", "text": "معدلة بالقانون رقم 37 لسنة 1972 – الجريدة الرسمية – ) يبلغ فورا كل من يقبض عليه أو يحبس احتياطيا بأسباب القبض عليه أو حبسه ، ويكون له حق الاتصال بمن يرى إبلاغه بما وقع والاستعانة بمحام ، ويجب إعلانه على ووجه السرعة بالتهم الموجهة إليه . ولا يجوز تنفيذ أوامر الضبط والإحضار وأوامر الحبس بعد مضى ستة أِشهر من تاريخ صدورها ، مالم يعتمدها قاضى التحقيق لمدة أخرى ."}, {"number": "140", "chapter": "الفصل التاسع", "text": "معدلة بالمرسوم بقانون رقم 353 لسنة 1952 ) \"\" لا يجوز لمأمور السجن أن يسمح لأحد من رجال السلطة بالاتصال بالمحبوس داخل السجن إلا بأذن كتابى من النيابة العامة ، وعليه أن يدون فى دفتر السجن اسم الشخص الذى سمح له بذلك ووقت المقابلة وتاريخ ومضمون الإذن \"\""}, {"number": "141", "chapter": "الفصل التاسع", "text": "معدلة بالمرسوم بقانون رقم 353 لسنة 1952 ) للنيابة العامة ولقاضى التحقيق فى القضايا التى يندب لتحقيقها فى كل الأحوال أن يأمر بعدم إتصال المتهم المحبوس بغيره من المسجونين وبألآ يزوره أحد وذلك بدون إخلال بحق المتهم فى الإتصال دائما بالمدافع عنه بدون حضور أحد ."}, {"number": "142", "chapter": "الفصل التاسع", "text": "الفقرة الأولى مستبدلة بالقانون 145 لسنة 2006 ) ينتهى الحبس الإحتياطي حتما بمضى خمسة عشر يوماعلى حبس المتهم ، ومع ذلك يجوز لقاضى التحقيق قبل إنقضاء تلك المدة ،و بعد سماع أقوال النيابة العامة والمتهم، أن يصدر أمرا بمد الحبس مددا مماثلة بحيث لاتزيد مدة الحبس فى مجموعه على خمسة وأربعين يوما . على أنه فى مواد الجنح يجب الإفراج حتما عن المتهم المقبوض عليه بعد مرور ثمانية أيام من تاريخ إستجوابه إذا كان له محل إقامة معروف فى مصر وكان الحد الأقصى للعقوبة قانونا لايتجاوز سنة واحدة ولم يكن عائدا وسبق الحكم عليه بالحبس أكثر من سنة ."}, {"number": "143", "chapter": "الفصل التاسع", "text": "معدلة بالقانون 153 لسنة 2007 ) إذا لم ينته التحقيق ورأى القاضى مد الحبس الإحتياطى زيادة على ماهو مقرر فى المادة السابقة وجب قبل انقضاء المدة السالفة الذكر إحالة الأوراق إلى محكمة الجنح المستأنفة منعقدة فى غرفة المشورة لتصدر أمرها بعد سماع أقوال النيابة العامة والمتهم بمد الحبس مددا متعاقبة لاتزيد كل منها على خمسةوأربعين يوما إذا إقتضت مصلحة التحقيق ذلك أو الإفراج عن المتهم بكفالة أو بغير كفالة . ومع ذلك يتعين عرض الأمر على النائب العام إذا إنقضى على حبس المتهم إحتياطيا ثلاث شهور وذلك لإتخاذ الإجراءات التى يراها كفيلة للإنتهاء من التحقيق ولايجوز أن تزيد مدة الحبس الإحتياطى على ثلاثة أشهر ، مالم يكن المتهم قد أعلن بإحالته إلى المحكمة المختصة قبل إنتهاء هذه المدة ، ويجب على النيابة العامة فى هذه الحالة أن تعرض أمر الحبس خلال خمسة أيام على الأكثر من تاريخ الإعلان بالإحالة على المحكمة المختصة وفقا لأحكام الفقرة الأولى من المادة (151) من هذا القانون لإعمال مقتضى هذه الأحكام ، وإلا وجب الإفراج عن المتهم ، فإذا كانت التهمة المنسوبة إليه جناية فلا يجوز أن تزيد مدة الحبس الإحتياطى على خمسة شهور إلا بعد الحصول قبل إنقضائها على أمر من المحكمة المختصة بمد الحبس مدة لاتزيد على خمسة وأربعين قابلة للتجديد لمدة أو مدد أخرى مماثلة ، وإلا وجب الإفراج عن المتهم . وفى جميع الأحوال لايجوز أن تجاوز مدة الحبس الإحتياطى فى مرحلة التحقيق الإبتدائى وسائر مراحل الدعوى الجنائية ثلث الحد الأقصى للعقوبة السالبة للحرية ، بحيث لاتجاوز ستة أِشهر فى الجنح وثمانية عشر شهرا فى الجنايات ، وسنتين إذا كانت العقوبة المقررة للجريمة هى السجن المؤبد أو الإعدام . \"\" ومع ذلك فلمحكمة النقض ولمحكمة الإحالة ، إذا كان الحكم صادرا بالإعدام ، أن تأمر بحبس المتهم إحتياطيا لمدة خمسة وأربعين يوما قابلة للتجديد دون اتقيد بالمدد المنصوص عليها فى الفقرة السابقة \"\"\""}, {"number": "144", "chapter": "الفصل العاشر", "text": "الفقرة الثانية معدلة بالقانون رقم 107 لسنة 1962 ) لقاضى التحقيق فى كل وقت سواء من تلقاء نفسه أو بناء على طلب المتهم أن يأمر بعد سماع أقوال النيابة العامة بالإفراج المؤقت عن المتهم إذا كان هو الذى أمر بحبسه إحتياطيا ، على شرط أن يتعهد المتهم بالحضور كلما طلب وبألا يفر من تنفيذ الحكم الذى يمكن أن يصدر ضده . فإذا كان الأمر بالحبس الإحتياطى صادرا من محكمة الجنح المستأنفة منعقدة فى غرفة المشورة بناء على إستئناف النيابة العامة للأمر بالإفراج السابق صدوره من قاضى التحقيق فلا يجوز صدور أمر جديد بالإفراج إلا منها ."}, {"number": "145", "chapter": "الفصل العاشر", "text": "فى غير الأحوال التى يكون فيها الإفراج واجبا حتما لايفرج عن المتهم بضمان أو بغير ضمان إلا بعد أن يعين له محلا فى الجهة الكائن بها مركز المحكمة إن لم يكن مقيما فيها."}, {"number": "146", "chapter": "الفصل العاشر", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) يجوز تعليق الإفراج المؤقت ، فى غير الأحوال التى يكون فيها واجبا حتما ، على تقديم كفالة ، ويقدر قاضى التحقيق أو محكمة الجنح المستأنفة منعقدة فى غرفة المشورة حسب الأحوال مبلغ الكفالة . ويخصص فى الأمر الصادر بتقدير مبلغ الكفالة جزء منه ليكون جزاءا كافيا لتخلف المتهم عن الحضور فى أى إجراء من إجراءات التحقيق والدعوى والتقدم لتنفيذ الحكم والقيام بكافة الواجبات الأخرى التى تفرض عليه ويخصص الجزء الأخر لدفع ما يأتى بترتيبه: (أولا) المصاريف التى صرفتها الحكومة . (ثانيا) العقوبات المالية التى قد يحكم بها على المتهم وإذا قدرت الكفالة بغير تخصيص ، إعتبرت ضمانا لقيام المتهم بواجب الحضور والواجبات الأخرى التى تفرض عليه وعدم التهرب من التنفيذ ."}, {"number": "147", "chapter": "الفصل العاشر", "text": "يدفع مبلغ الكفالة من المتهم أو من غيره ، ويكون ذلك بإيداع المبلغ المقدر فى خزانة المحكمة نقدا أو سندات حكومية أو مضمونة من الحكومة . ويجوز أن يقبل من أى شخص ملىء التعهد بدفع المبلغ المقدر للكفالة إذا أخل المتهم بشرط من شروط الإفراج ، ويؤخذ عليه التعهد بذلك فى محضر التحقيق أو بتقرير فى قلم الكتاب ، ويكون للمحضر أو للتقرير قوة السند الواجب التنفيذ ."}, {"number": "148", "chapter": "الفصل العاشر", "text": "إذا لم يقم المتهم بغير عذر مقبول بتنفيذ أحد الإلتزامات المفروضة عليه ، يصبح الجزء الأول من الكفالة ملكا للحكومة بغير حاجة إلى حكم يذلك . ويرد الجزء الثانى للمتهم إذا صدر فى الدعوى قرار بأن لاوجه ، أو حكم بالبراءة ."}, {"number": "149", "chapter": "الفصل العاشر", "text": "لقاضى التحقيق إذا رأى أن حالة المتهم لاتسمح بتقديم كفالة أن يلزمه بأن يقدم نفسه لمكتب البوليس فى الأوقات التى يحددها له فى أمر الإفراج مع مراعاة ظروفه الخاصة . وله أن يطلب منه إختيار مكان للإقامة فيه غير المكان الذى وقعت فيه الجريمة ، كما له أن يحظر عليه إرتياد مكان معين ."}, {"number": "150", "chapter": "الفصل العاشر", "text": "مستبدلة بالقانون 145 لسنة 2006 ) الأمر الصادر بالإفراج لا يمنع قاضى التحقيق من إصدار أمر جديد بالقبض على المتهم أو بحبسه ، إذا ظهرت أدلة جديدة ضده أو أخل بالشروط المفروضة عليه ، أو جدت ظروف تستدعى اتخاذ هذا الإجراء ن وذلك مع عدم الإخلال بأحكام المادة (143) من هذا القانون ."}, {"number": "151", "chapter": "الفصل العاشر", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) إذا أحيل المتهم إلى المحكمة يكون الإفراج عنه إن كان محبوسا أو حبسه إن كان مفرجا عنه من اختصاص الجهة المحال إليها . وفى حالة الإحالة إلى محكمة الجنايات يكون الأمر فى غير دور الإنعقاد من اختصاص محكمة الجنح المستأنفة منعقدة فلى غرفة المشورة . وفىحالة الحكم بعدم الإختصاص تكون محكمة الجنح المستأنفة منعقدة فى غرفة المشورة هى المختصة بالنظر فى طلب الإفراج أو الحبس إلى أن ترفع الدعوى إلى المحكمة المختصة ."}, {"number": "152", "chapter": "الفصل العاشر", "text": "لايقبل من المجنى علبه أو من المدعى بالحقوق المدنية طلب حبس المتهم ولاتسمع منه أقوال فى المناقشات المتعلقة بالإفراج عنه ."}, {"number": "153", "chapter": "الفصل الحادى عشر", "text": "متى إنتهى التحقيق يرسل قاضى التحقيق الأوراق إلى النيابة العامة وعليها أن تقدم له طلباتها كتابة خلال ثلاثة أيام إذا كان المتهم محبوسا وعشرة أيام إذا كان مفرجا عنه . وعليه أن يخطر باقى الخصوم ليبدوا ماقد يكون لديهم من أقوال ."}, {"number": "154", "chapter": "الفصل الحادى عشر", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) إذا رأى قاضى التحقيق أن الواقعة لايعاقب عليها القانون أو أن الأدلة غير كافية ، يصدر أمرا بأن لاوجه لإقامة الدعوى . ويفرج عن المتهم المحبوس إن لم يكن محبوسا لسبب أخر . ويجب أن يشتمل الأمر على الأسباب التى بنى عليها ويعلن الأمر للمدعى بالحقوق المدنية، وإذا كان قد توفى يكون الإعلان لورثته جملة فى محل إقامته ."}, {"number": "155", "chapter": "الفصل الحادى عشر", "text": "إذا رأى قاضى التحقيق أن الواقعة مخالفة ، يحيل المتهم إلى المحكمة الجزئية ، ويفرج عنه إن لم يكن محبوسا لسبب أخر ."}, {"number": "156", "chapter": "الفصل الحادى عشر", "text": "إذا رأى قاضى التحقيق أن الواقعة جنحة ، يحيل المتهم إلى المحكمة الجزئية مالم تكن الجريمة من الجنح التى تقع بواسطة الصحف أو غيرها من طرق النشر – عدا الجنح المضرة بأفراد الناس فيحيلها إلى محكمة الجنايات ."}, {"number": "157", "chapter": "الفصل الحادى عشر", "text": "على النيابة العامة عند صدور القرار بإحالة الدعوى إلى المحكمة الجزئية أن تقوم بإرسال جميع الأوراق إلى قلم كتاب المحكمة فى ظرف يومين وبإعلان الخصوم بالحضور أمام المحكمة فى أقرب جلسة فى المواعيد المقررة ."}, {"number": "158", "chapter": "الفصل الحادى عشر", "text": "مستبدلة بالقانون رقم 170 لسنة 1981 ) إذا رأى قاضى التحقيق أن الواقعة جناية وأن الأدلة على المتهم كافية يحيل الدعوى إلى محكمة الجنايات ويكلف النيابة العامة بإرسال الأوراق إليها فورا ."}, {"number": "159", "chapter": "الفصل الحادى عشر", "text": "معدلة بالقانون رقم 113 لسنة 1957 ) يفصل قاضى التحقيق فى الأمر الصادر بالإحالة إلى المحكمة الجزئية أو محكمة الجنايات فى إستمرار حبس المتهم إحتياطيا أو الإفراج عنه أو فى القبض عليه وحبسه إحتياطيا إذا لم يكن قد قبض عليه أو كان قد أفرج عنه"}, {"number": "160", "chapter": "الفصل الحادى عشر", "text": "تشتمل الأوامر التى يصدرها قاضى التحقيق طبقا للمواد 154 و155 و156 و158 على إٍسم ولقب وسن المتهم ومحل ميلاده وسكنه وصناعته وبيان الواقعة المنسوبة إليه ووصفها القانونى ."}, {"number": "160", "chapter": "الفصل الحادى عشر", "text": "مكرر ( مضافة بالقانون رقم 63 لسنة 1975 ) يجوز للنائب العام أو المحامى العام فى الأحوال المبينة فى الفقرة الأولى من المادة 118 مكررا (أ) من قانون العقوبات أن يحيل الدعوى إلى محاكم الجنح لتقضى فيها وفقا لأحكام المادة المذكورة ."}, {"number": "161", "chapter": "الفصل الثانى عشر", "text": "للنيابة العامة أن تستأنف ولو لمصلحة المتهم جميع الأوامر التى يصدرها قاضى التحقيق سواء من تلقاء نفسه أو بناء على طلب الخصوم ."}, {"number": "162", "chapter": "الفصل الثانى عشر", "text": "معدلة بالقانون رقم 37 لسنة 1972 ) للمدعى بالحقوق المدنية إستئناف الأوامر الصادرة من قاضى التحقيق بأن لاوجه للإقامة الدعوى إلا إذا كان الأمر صادرا فى تهمة موجهة ضد مكوظف عام أو مستخدم عام أو أحد رجال الضبط لجريمة وقعت منه أثناء تأدية وظيفته أو بسببها ، مالم تكن من الجرائم المشار إليه فى المادة 123 من قانون العقوبات ."}, {"number": "163", "chapter": "الفصل الثانى عشر", "text": "لجميع الخصوم أن يستأنفوا الأوامر المتعلقة بمسائل الإختصاص ولايوقف الإستئناف سير التحقيق ولايترتب على القضاء بعدم الإختصاص بطلان إجراءات التحقيق ."}, {"number": "164", "chapter": "الفصل الثانى عشر", "text": "مستبدلة بالقانون 145 لسنة 2006 ) للنيابة العامة وحدها إستئناف الأمر الصادر بالإحالة إلى المحكمة الجزئية بإعتبار الواقعة جنحة أومخالفة طبقا للمادتين 155 و156 ولها وحدها كذلك أن تستأنف الأمر الصادر فى جناية بالإفراج المؤقت عن المتهم المحبوس إحتياطيا ، وللمتهم أن يستأنف الأمر الصادر بحبسه إحتياطيا أو بمد هذا الحبس ."}, {"number": "165", "chapter": "الفصل الثانى عشر", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) يحصل الإستئناف بتقرير فى قلم الكتاب"}, {"number": "166", "chapter": "الفصل الثانى عشر", "text": "معدلة بالقانون رقم 107 لسنة 1962 ، ثم إستبدلت بالقانون 145 لسنة 2006 ) يكون ميعاد الإستئناف عشرة أيام من تاريخ صدور الأمر بالنسبة إلى النيابة العامة ومن تاريخ إعلانه بالنسبة إلى باقى الخصوم، عدا الحالات المنصوص عليها فى الفقرة الثانية من المادة (164 ) من هذا القانون ، فيكون ميعاد إستئناف النيابة لأمر الإفراج المؤقت أربعا وعشرين ساعة، ويجب الفصل فى الإستئناف خلال ثمانية وأربعين ساعة من تاريخ رفعه ، ويكون إستئناف المتهم فى أى وقت ، فإذا صدر قرار برفض إستئنافه جاز له أن يتقدم بإستئناف جديد كلما إنقضت مدة ثلاثين يوما من تاريخ صدور قرار الرفض ."}, {"number": "167", "chapter": "الفصل الثانى عشر", "text": "يرفع الإستئناف أمام محكمة الجنح المستأنفة منعقدة فى غرفة المشورة إذا كان الأمر المستأنف صادرا من قاضى التحقيق بالحبس الإحتياطى أو بمده ، فإذا كان الأمر صادرا من تلك المحكمة ، يرفع الإستئناف إلى محكمة الجنايات منعقدة فى غرفة المشورة ، وإذا كان صادرا من محكمة الجنايات يرفع الإسٍتئناف إلى الدائرة المختصة ، ويرفع الإستئناف فى غير هذه الحالات أمام محكمة الجنح المستنأنفة منعقدة فى غرفة المشورة إلا إذا كان الأمر المستأنف صادرا بأن لاوجه لإقامة الدعوى فى جناية أو صادرا من هذه المحكمة بالإفراج عن المتهم فيرفع الإستئناف إلى محكمة الجنايات منعقدة فى غرفة المشورة . وعلى غرفة المشورة عند إلغاء الأمر بألا وجه لإقامة الدعوى أن تعيد القضية معينة الجريمة والأفعال المكونة لها ونص القانون المنطبق عليها وذلك لإحالتها إلى المحكمة المختصة . وإذا كان الذى تولى التحقيق مستشارا عملا بالمادة 65 فلا يقبل الطعن فى الأمر الصادر منه إلا إذا كان متعلقا بالإختصاص أو بأن لا وجه لإقامة الدعوى أو بالحبس الإحتياطى أو بمده أو بالإفراج المؤقت ، ويكون الطعن أمام محكمة الجنايات منعقدة فى غرفة المشورة .ويكون الطعن أمام محكمة الجنايات منعقدة فى غرفة المشورة . وفى جميع الأحوال يتعين الفصل فى الطعن فى أوامر الحبس الإحتياطى أو مده أو الإفراج المؤقت ، خلال ثمانية وأربعين ساعة من تاريخ رفع الطعن، وإلا وجب الإفراج عن المتهم . وتختص دائرة أو أكثر من دوائر المحكمة الإبتدائية أو محكمة الجنايات لنظر الإستئناف أوامر الحبس الإحتياطى أو الإفراج المؤقت المشار إليهما فى هذه المادة وعلى غرفة المشورة عند الغاء الأمر بألا وجه لإقامة الدعوى أن تعيد القضية معينة الجريمة المكونة لها والأفعال المرتكبة ونص القانون المنطبق عليها وذلك لإحالتها إلى المحكمة المختصة . وتكون القرارات الصادرة من غرفة المشورة فى جميع الأحوال نهائية ."}, {"number": "168", "chapter": "الفصل الثانى عشر", "text": "ينفذ الأمر الصادر بالإفراجالمؤقت عن المتهم المحبوس إحتياطيا مالم تستأنفه النيابة العامة فى الميعاد المنصوص عليه فى المادة ( 166) من هذا القانون . ولممحكمة المختصة بنظر الإستئناف. أن تأمر بمد حبس المتهم طبقا لما هو مقرر فى المادة (143) من هذا القانون . وإذا لم يفصل فى الإستئناف خلال ثلاثة أيام من تاريخ التقرير به وجب تنفيذ الأمر بالإفراج فورا"}, {"number": "169", "chapter": "الفصل الثانى عشر", "text": "إذا رفض الإستئناف المرفوع من المدعى بالحقوق المدنية عن الأمر الصادر بأن لاوجه لإقامة الدعوى جاز للجهة المرفوع إليها اللإإستئناف أن تكم على المتهم بالتعويضات الناشئة عن رفع الإستئناف إذا كان لذلك محل ."}, {"number": "197", "chapter": "الفصل الخامس عشر", "text": "الأمر الصادر من قاضى التحقيق بأن لاوجه لإقامة الدعوى يمنع من العودة إلى التحقيق إلا إذا ظهرت دلائل جديدة قيبل إنتهاء المدة المقررةلسقوط الدعوى الجنائية . ويعد من الدلائل الجديدة شهادة الشهود والمحاضر والأوراق الأخرى التى لم تعرض على قاضى التحقيق أو غرفة المشورة ويكون من شأنها تقوية الدلائل التى وجدت غير كافية أو زيادة الإيضاح المؤدى إلى ظهور الحقيقة ولاتجوز العودة إلى التحقيق إلا بناء على طلب النيابة العامة ."}, {"number": "198", "chapter": "الباب الرابع", "text": "ملغاة بالقانون رقم 353 لسنة 1952 -"}, {"number": "199", "chapter": "الباب الرابع", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) فيما عدا الجرائم التى يختص قاضى التحقيق بتحقيقها وفقا لأحكام المادة 64 تباشر النيابة العامة التحقيق فى مواد الجنح والجنايات طبقا للأحكام المقررة من قاضى التحقيق مع مراعاة ماهو منصوص عليه فى المواد التالية ."}, {"number": "199", "chapter": "الباب الرابع", "text": "مكرر ( مضافة بالقانون رقم 353 لسنة 1952 ثم عدلت بالقانون رقم 107 لسنة 1962 ) لمن لحقه ضرر من الجريمة أن يدعى بحقوق مدنية أثناء التحقيق في االدعوى وتفصل النيابة العامة فى قبوله بهذه الصفة فى التحقيق خلال ثلاثة أيام من تقديم هذا الإدعاء ولمن رفض طلبه الطعن فى قرار الرفض أمام محكمة الجنح المستأنفة منعقدة فى غرفة المشورة خلال ثلاثة أيام تسرى من وقت إعلانه بالقرار"}, {"number": "200", "chapter": "الباب الرابع", "text": "لكل من أعضاء النيابة العامة فى حالة إجراء التحقيق بنفسه أن يكلف أى مأمور من مأمورى الضبط القضائى ببعض الأعمال التى من خصائصه ."}, {"number": "201", "chapter": "الباب الرابع", "text": "إستبدلت الفقرة الأولى بالقانون 145 لسنة 2006 ) يصدر الأمر بالحبس من النيابة العامة من وكيل نيابة على الأقل وذلك لمدة أقصاها أربعة أيام تالية للقبض على المتهم أو تسليمه للنيابة العامة إذا كان مقبوضا عليه من قبل . ويجوز للسلطة المختصة بالحبس الإحتياطى أن تصدر بدلا منه أمرا بأحد التدابير الآتية : 1- إلزام المتهم بعدم مبارحة مسكنه أو موطنه . 2- إلزام المتهم بأن يقدم نفسه لمقر الشرطة فى أوقات محدودة . 3- حظر إرتياد المتهم أماكن محددة فإذا خالف المتهم الإلتزامات التى يفرضها التدبير ، جاز حبسه إحتياطيا . ويسرى فى شأن مدة التدبير أو مدها والحد الأقصى لها وإستئنافها ذات القواعد المقررة بالنسبة إلى الحبس الإحتياطى. ولا يجوز تنفيذ أوامر الضبط والإحضار وأوامر الحبس الصادرة من النيابة العامة بعد مضى ستة أِشهر من تاريخ صدورها مالم تعتمدها النيابة العامة لمدة أخرى ."}, {"number": "202", "chapter": "الباب الرابع", "text": "معدلة بالقانون رقم 353 لسنة 1952 ، وإستبدلت الفقرة الثانية من المادة بالقانون 145 لسنة 2006 ) إذا رأت النيابة العامة مد الحبس الإحتياطى وجب قبل إنقضاء مدة أربعة أيام أن تعرض الأوراق على القاضى الجزئى ليصدر لأأمر بما يراه بعد سماع أقوال النيابة العامة والمتهم . وللقاضى مد الحبس الإحتياطى لمدة أو لمدد متعاقبة لاتجاوز كل منها خمسة عشر يوما ، و بحيث لاتزيد مدة الحبس الإحتياطى فى مجموعها على خمسة وأربعين يوما."}, {"number": "203", "chapter": "الباب الرابع", "text": "مضافة بالقانون رقم 353 لسنة 1952 ثم عدلت بالقانون 107 لسنة 1962 ) إذا لم ينته التحقيق بعد انقضاء مدة الحبس الاحتياطى المذكورة فى المادة السابقة وجب على النيابة العامة عرض الأوراق على محكمة الجنح المستأنفة منعقدة فى غرفة المشورة لتصدر أمرا بما تراه وفقا لأحكام المادة 143 ."}, {"number": "204", "chapter": "الباب الرابع", "text": "لنيابة العامة أن تفرج عن المتهم فى أى وقت بكفالة أو بغير كفالة ."}, {"number": "205", "chapter": "الباب الرابع", "text": "الفقرة الثانية مستبدلة بالقانون 145 لسنة 2006 ) للقاضى الجزئى أن يقدر كفالة للإفراج عن المتهم كلما طلبت النيابة العامة الأمر بامتداد الحبس وتراعى فى ذلك أحكام المواد من 146 إلى 150 . وللمتهم أن يستأنف الأمر الصادر بحبسه إحتياطيا أو بمد هذا الحبس من القاضى الجزئى أو محكمة الجنح المستأنفة منعقدة فى غرفة المشورة ، وللنيابة العامة إذا استلزمت ضرورة التحقيق أن تستأنف الامر الصادر من القاضى الجزئى أو من محكمة الجنح المستأنفة فى غرفة المشورة بالإفراج عن المتهم المحبوس إحتياطيا وتراعى فى ذلك أحكام الفقرة الثانية من المادة (164) والمواد ( من 165 إلى 168 ) من هذا القانون ."}, {"number": "206", "chapter": "الباب الرابع", "text": "لا يجوز للنيابة العامة تفتيش غير المتهم أو منزل غير منزله إلا إذا اتضح من امارات قوية أنه حائز لأشياء تتعلق بالجريمة. ويجوز لها أن تضبط لدى مكاتب البريد وجميع الخطابات والرسائل والجرائد والمطبوعات والطرود ولدى مكاتب البرق وجميع البرقيات وأن تراقب المحادثات السلكية واللاسلكية وأن تقوم بتسجيلات لمحادثات جرت فى مكان خاص متى كان لذلك فائدة فى ظهور الحقيقة فى جناية أو فى جنحة معاقب عليها بالحبس لمدة تزيد على ثلاثة أشهر . ويشترط لاتخاذ أى إجراء من الإجراءات السابقة الحصول مقدما على أمر مسبب بذلك من القاضى الجزئى بعد اطلاعه على الأوراق . وفى جميع الأحوال يجب أن يكون الأمر بالضبط أو الاطلاع أو المراقبة لمدة لا تزيد على ثلاثين يوما ويجوز للقاضى الجزئى أن يجدد هذا الأمر مدة أو مددا أخرى مماثلة . وللنيابة العامة أن تطلع على الخطابات والرسائل والأوراق الأخرى والتسجيلات المضبوطة على أن يتم هذا كلما أمكن ذلك بحضور المتهم والحائز لها أو المرسلة إليه وتدون ملاحظاتهم عليها ولها حسب ما يظهر من الفحص أن تأمر بضم تلك الأوراق إلى ملف الدعوى أو بردها إلى من كان حائزا لها أو من كانت مرسلة إليه ."}, {"number": "206 مكررا", "chapter": "الباب الرابع", "text": "مضافة بالقانون 95 لسنة 2003 ، وإستبدلت الفقرة الأولى بالقانون 145 لسنة 2006 ) \" يكون لأعضاء النيابة العامة من درجة رئيس نيابة على الأقل – بالإضافة إلى الإختصاصات المقررة للنيابة العامة – سلطات قاضى التحقيق فى تحقيق الجنايات المنصوص عليها فى الأبواب الأول والثانى والثانى مكررا والرابع من الكتاب الثانى من قانون العقوبات . ويكون لهم فضلا عن ذلك سلطة محكمة الجنح المستأنفة منعقدة فى غرفة المشورة المبينة فى المادة (143) من هذا القانون فى تحقيق الجرائم المنصوص عليها فى القسم الأول من الباب الثانى المشار إليه بشرط ألا تزيد مدة الحبس فى كل مرة عن خمسة عشر يوما . ويكون لهؤلاء الأعضاء من تلك الدرجة سلطات قاضى التحقيق فيما عدا مدد الحبس الإحتياطى المنصوص عليها فى المادة (142) من هذا القانون ، وذلك فى تحقيق الجنايات المنصوص عليها فى الباب الثالث من الكتاب الثانى من قانون العقوبات ."}, {"number": "207", "chapter": "الباب الرابع", "text": "ملغاة"}, {"number": "208", "chapter": "الباب الرابع", "text": "تسرى على الشهود فى التحقيق الذى تجريه النيابة العامة الأحكام المقررة أمام قاضى التحقيق . ويكون الحكم على الشاهد الذى يمتنع عن الحضور أما النيابة العامة والذى يحضر ويمتنع عن الإجابة من القاضى الجزئى فى الجهة التى طلب حضور الشاهد فيها حسب الأحوال المعتادة."}, {"number": "208 مكرر", "chapter": "الباب الرابع", "text": "ملغاة"}, {"number": "208 مكرر", "chapter": "الباب الرابع", "text": "أ ) : - ( مستبدلة بالقانون رقم 174 لسنة 1998 )"}, {"number": "208 مكرر", "chapter": "الباب الرابع", "text": "أ ) : - \" فى الأحوال التى تقوم فيها من التحقيق أدلة كافية على جدية الاتهام فى أى من الجرائم المنصوص عليها فى الباب الرابع من الكتاب الثانى من قانون العقوبات ، وغيرها من الجرائم التى تقع على الأموال المملوكة للدولة أو الهيئات والمؤسسات العامة والوحدات التابعة لها أو غيرها من الأشخاص الاعتبارية العامة ، وكذا فى الجرائم التى يوجب القانون فيها على المحكمة أن تقضى - من تلقاء نفسها - برد المبالغ أو قيمة الأشياء محل الجريمة أو تعويض الجهة المجنى عليها . إذا قدرت النيابة العامة أن الأمر يقتضى اتخاذ تدابير تحفظية على أموال المتهم بما فى ذلك منعه من التصرف فيها أو إدارتها ، رجب عليها أن تعرض الأمر على المحكمة الجنائية المختصة طالبة الحكم بذلك ضمانا لتنفيذ ما عسى أن يقضى به من غرامة أو رد أو تعويض . وللنائب العام عند الضرورة أو فى حالة الاستعجال أن يأمر مؤقتا بمنع المتهم أو زوجه أو أولاده القصر من التصرف فى أموالهم أو اداراتها ، ويجب أن يشتمل أمر المنع من الإدارة على تعيين من يدير الأموال المتحفظ عليها ، وعلى النائب العام فى جميع الأحوال أن يعرض أمر المنع على المحكمة الجنائية المختصة خلال سبعة أيام على الأكثر من تاريخ دوره ، بطلب الحكم بالمنع من التصرف أو الإدارة والا اعتبر الأمر كأن لم يكن . وتصدر المحكمة الجنائية المختصة حكمها فى الحالات السابقة بعد سماع أقوال ذوى الشأن خلال مدة لا تجاوز خمسة عشر يوما من تاريخ عرض الأمر عليها ، وتفصل المحكمة فى مدى استقرار العمل بالأمر الوقتى المشار اليه فى الفقرة السابقة كلما رأت وجها لتأجيل نظر الطلب . ويجب أن يشتمل الحكم على الأسباب التى بنى عليها ، وان يشمل المنع من الإدارة تعيين من يده الأموال المتحفظ عليها بعد أخذ رأى النيابة العامة . ويجوز للمحكمة - بناء على طلب النيابة العامة - أن تشمل فى حكمها أى مال لزوج المتهم أو أولاده القصر إذا توافرت أدلة كافية على انه متحصل من الجريمة موضوع التحقيق وال إليهم من المتهم وذلك بعد إدخالهم فى الطلب ، وعلى من يحين لدارة أن يتسلم الاموال المتحفظ عليها وادر إلى جردها بحضور ذوى الشأن وممثل للنيابة العامة أو خبير تندبه المحكمة ، وتتبع فى شأن الجرد أحكام المادتين 965 و 989 من قانون المرافعات المدنية والتجارية . ويلتزم من يعين لادارة بالمحافظة على الاموال ويحسن اداراتها ، وردها مع غلتها المقبوضة طبقا للأحكام المقررة فى القانون المدنى بشأن الوكالة فى أعمال الإدارة والوديعة والحراسة ، وذلك على النحو الذى يصدر بتنظيمه قرار من وزير العدل \" ."}, {"number": "208", "chapter": "الباب الرابع", "text": "مكرر(ب) ( مضافة بالقانون رقم 43 لسنة 1967 لكل من صدر ضده حكم بالمنع من التصرف أو الإدارة أن يتظلم منه أمام النمحكمة الجنائية المختصة بعد ‘تقضاء ثلاثة أشهر من تاريخ الحكم ، وإذا رفض تظلمه فله أن يتقدم بتظلم جديد كلنما إنقضت ثلاثة أشهر من تاريخ الحكم برفض التظلم . كما يجوز لمن صدر ضده حكم بالمنع من التصرف أو الإدارة ولكل ذى شأن أن يتظلم من إجراءات تنفيذه . ويحصل التظلم بتقرير فى قلم كتاب المحكمة الجنائية المختصة ، وعلى رئيس المحكمة أن يحدد جلسة لنظر التظلم يعلن بها المتظلم وكل ذى شأن ، وعلى المحكمة لآأن تفصل فى التظلم خلال مدة لاتجاوز خمسة عشر يوما من تاريخ التقرير به . وللمحكمة المختصة أثناء نظر الدعوى – من تلقاء نفسها أو بناء على طلب النيابةو العامة أو ذوى الشأن أن تحكم بإنهاء المنع من التصرف أو الإدارة المقضى به أو تعديل نطاقه أو إجراءات تنفيذه . ويجب أن يبين الأمر الصادر بالتصرف فى الدعوى الجنائية أو الحكم الصادر فيها مايتبع فى شأن التدلابير التحفظية المشار إليها فى فى المادة السابقة . وفى جميع الأحوال ينتهى المنع من التصرف أو الإدارة بصدور قرار بأن لاوجه لإقامة الدعوى الجنائية أوب صدورة حطكم نهائى فيها بالبراءة ، أو بتمام تنفيذ العقوبات المالية والتعويضات المقضى بهما . ولايحتج عند تنفيذ الحكم الصادر بالغرامة أو برد المبالغ أو قيمة الأِشياء محل الجريمة أو بتعوزيض الجهة المجنى عليها بحسب الأحوال بأى تصرف يصدر بالمخالفة للأمر أو الكم المشار إليهما فى المادة السابقة من تاريخ قيد أى منهما فى سجل خاص يصدر بتنظيمه قرار من وزير العدل ويكون لكل ذى شأن حق الإطلاع على هذا السجل ."}, {"number": "208", "chapter": "الباب الرابع", "text": "مكرر (ج) ( مضافة بالقانون رقم 43 لسنة 1967 ) للمحكمة عند الحكم برد المبالغ أو قيمة الأشياء محل الجرائم المشار إليها فى المادة 208 مكرر (أ) أو بتعويض تادجهة المجنى عليها فيها أن تقضى بناء على طلب النيابة العامة أو المدعى بالحقوق المدنية بحسب الأحوال وبعد سماع أقوال ذوى الشأن ، بتنفيذ هذا الحكم فى أموال زوج المتهم وأولاده القصر ،إذا ثبت أنها الت إليهم من المتهم وأنها متحصلة من الجريمة المحكوم فيها ."}, {"number": "208", "chapter": "الباب الرابع", "text": "مكرر(د) ( مضافة بالقانون رقم 63 لسنة 1975 ) لايحول انقضاء الدعوى الجنائية بالوفاة قبل أو بعد إحالتها غلىالمحكمة دون قضائها بالرد فىالجرائم المنصوص عليها فى المواد 112 و113 فقرة أولى وثانية ورابعة و113 مكرر فقرة أولى و114 و115 من قانون العقوبات . وعللى المكمة أن تأمر بالرد فى مواجهة الورثة والموصى لهم وكل من أفاد فائدة جدية فى الجريمة ليكون الحكم بالرد نافذا فى أموال كل منهم بقدر ما إستفاد ويجب أن تندب المحكمة محاميا للدفاع عمن وجه إليهم طلب الرد إذا لم ينوبوا من يتولى الدفاع عنهم ."}, {"number": "209", "chapter": "الباب الرابع", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) إذا رأت النيابة العامة بعد التحقيق أنه لاوجه لإقامة الدعوى تصدر أمرا بذلك وتأمر بالإفراج عن المتهم المحبوس مالم يكن محبوسا لسبب أخر ولايكونه صدور الأمر بألا وجه لإقامة الدعوى فى الجنايات إلا من المحامى العام أو من يقوم مقامه . ويجب أن يشمل الأمر على الأسباب التى بنى عليها . ويعلم الأمر للمدعى بالحقوق المدنية وإذا كان قد توفى يكون الإعلان لورثته جملة فى محل إقامته ."}, {"number": "210", "chapter": "الباب الرابع", "text": "معدلة بالقانون رقم 37 لسنة 1972 ) للمدعى بالحقوق المدنية الطعن فى الأمر الصادر من النيابة العامة بأن لاوجه لإقامة الدعوى إلا إذا كان صادرا فى تهمة موجهة ضد موظف أو مستخدم عام أو أحد رجال الضبط لجريمة وقعت منه أثناء تأدية وظيفته أو بسببها مالم تكن مكن الجرائم المشار إليها فى المادة 123 من قانون العقوبات . ويحصل الطعن بتقرير فى قلم الكتاب فى ميعاد عشرة أيام من تاريخ إعلان المدعى بالحق المدنى بالأمر . ويرفع الطعن إلى محكمة الجنايات منعقدة فى غرفة المشورة فى مواد الجنايات وإلى محكمة الجنح ا المستأنفة منعقدة فى غرفة المشورة فى مواد الجنح والمخالفات ويتبع فى رفعه والفصل فيه الأحكام المقررة فى شأن استئناف الأوامر الصادرة من قاضى التحقيق . ضد موظف أو مستخدم عام أو أحد رجال الضبط لجناية أو جنحة وقعت منه أثناء تأدية وظيفته أو بسببها"}, {"number": "211", "chapter": "الباب الرابع", "text": "مستبدلة بالقانون رقم 170 لسنة 1981 ) للنائب العام أن يلغى الأمر المذكور فى مدة الثلاثة أِشهر التالية لصدةوره مالم يكن قد صدر قرار من محكمة الجنايات أو من محكمة الجنح المستأنفة منعقدة فى غرفة المشورة بحسب الأحوال برفض الطعن المرفوع فى هذا الأمر ."}, {"number": "212", "chapter": "الباب الرابع", "text": "ملغاة بقرار بقانون رقم 170 لسنة 1981 )"}, {"number": "213", "chapter": "الباب الرابع", "text": "الأمر الصادر من النيابة العامة بأن لاوجه لإقامة الدعوى وفقا للمادة 209 لا يمنع من العود إلى التحقيق إذا ظهرت أدلة جديدة طبقا للمادة 197 ."}, {"number": "214", "chapter": "الباب الرابع", "text": "مستبدلة بالقانون رقم 170 لسنة 1981 ) إذا رأت النيابة العامة بعد التحقيق أن الواقعة جناية أوجنحة أو مخالفة وأن الأدلة على المتهم كافية رفعت الدعوى إلى المحكمة المختصة ويكون ذلك فى مواد المخالفات والجنح بطريق تكليف المتهم بالحضور أمام المحكمة الجزئية مالم تكن الجريمة من الجنح التى تقع بواسطة الصحف أو غيرها عن طريق النشر عدا الجنح المضرة بأفراد الناس فتحيلها النيابة العامة إلى محكمة الجنايات مباشرة وترفع الدعوى فى مواد الجنايات بإحالتها من المحامى العامى أو من يقوم مقامه إلى محكمة الجنايات بتقرير إتهام تبين فيه الجريمة المسندة إلى المتهم بأركانها المكونة لها وكافة الظروف المشددة أو المخففة للعقوبة ومواد القانون المراد تطبيقها ، وترفق به قائمة بمؤدى أقوال شهود وأدلة الإثبات . ويندب المحامى العام من تلقاء نفسه محاميا لكل متهم بجناية صدر أمر بإحالته إلى محكمة الجنايات إذا لم يكن قد وكل محاميا للدفاع عنه ، وتعلن النيابة العامة الخصوم بالأمر الصادر بالإحالة إلى محكمة الجنايات خلال العشرة أيام التالية لصدوره . ويراعى فى جميع الأحوال حكم الفقرة الأخيرة من المادة 63. على أنه إذا شمل التحقيق أكثر من جريمة واحدة من اختصاص محاكم من درجة واحدة وكانت مرتبطة تال جميعها بأمر إحالة واحد إلى المحكمة المختصة مكانا بأحدهم فإذا كانت الجرائم من اختصاص محاكم من درجات مختلفة تحال إلى المحكمة الأعلى درجة ، وفى أحوال الإرتباط التى يجب فيها رفع الدعوى عن جميع الجرائم أمام محكمة واحدة ن إذا كانت بعهض الجرائم من اختصاص محاكم عادية وبعضها من اختصاص ماكم خاصة يكون رفع الدعوى بجميع الجرائم أمام المحاكمى العادية مالم ينص القانون على غير ذلك ."}, {"number": "214", "chapter": "الباب الرابع", "text": "مكرر ( مضافة بالقانون رقم 170 لسنة 1981 ) إذا صدر – بعد صدور الأمر بالإحالة مايستوجب إجراء تحقيقات تكميلية فعلى النيابة العامة أن تقوم بإجرائها وتقدم المحضر إلى المحكمة ."}, {"number": "214", "chapter": "الباب الرابع", "text": "مكرر (أ))( مضافة بالقانون رقم 170 لسنة 1981 - ) يرسل ملف القضية إلى قلم كتاب محكمة الإستئناف فورا ، وإذا طلب محامى المتهم أجلا للإطلاع عليه يحدد له رئيس المخحكمة ميعادا لايجاوز عشرة أيام يبقى خلالها ملف القضية فى قلم الكتاب حتى يتسنى له الإطلاع عليه من غير أن ينقل من هذا القلم . وعلى الخصوم أن يعلنوا شهودهم الذين لم تدرج أٍسماؤهم فى القائمة سالفة الذكر على يد محضر بالحضور بالجدلسة المحددة لنظر الدعوى وذلك مع تحمل نفقلات الإعلان وإيداع مصاريف إنتقال الشهود ."}, {"number": "215", "chapter": "الفصل الأول", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) تحكم المحكمة الجزئية فى كل فعل يعد بمقتضى القانون مخالفة أو جنحة عدا الجنح التىتقع بواسطة الصحف أو غيرها من طرق النشر على غير الأفراد ."}, {"number": "216", "chapter": "الفصل الأول", "text": "معدلة بالقانون رقم 303 لسنة 1953 ) تحكم محكمة الجنايات فى كل فعل يعد بمقتضى القانون جناية وفى الجنح التى التى تقع بواسطة الصحف أو غيرها من طرق النشر عدا الجنح المضرة بأفراد الناس وغيرها من الجرائم الأخرى التى يص القانون على إختصاصها بها ."}, {"number": "217", "chapter": "الفصل الأول", "text": "يتعين الإختصاص بالمكان الذى وقعت فيه الجريمة أو الذى يقيم فيه المتهم ، أو الذى يقبض عليه فيه"}, {"number": "218", "chapter": "الفصل الأول", "text": "فى حالة الشروع تعتبر الجريمة أنها وقعت فى كل محل يقع فيه عمل من أعمال البدء فى التنفيذ وفى الجرائم المستمرة يعتبر مكانا للجريمة كل محل تقوم فيه حالة الإستمرار . وفى جرائم الإعتياد والجرائم المتتابعة يعتبر مكانا للجريمة كل محل يقع فيه أد الأفعال الداخلة فيها ."}, {"number": "219", "chapter": "الفصل الأول", "text": "إذا وقعت فى الخارج جريمة من الجرائم التى تسرى عليها أحكام القانون المصرى ، ولم يكن لمرتكبها مل إقامة فى مصر ولم يضبط فيها . ترفع عليه الدعوى فى الجنايات أمام محكمة جنايات القاهرة وفى الجنح أمام محكمة عابدين الجزئية ."}, {"number": "220", "chapter": "الفصل الثانى", "text": "يجوز رفع الدعوى المدنية . مهما بلغت قيمتها بتعويض الضرر الناشىء عن الجريمة أمام المحاكم الجنائية لنظرها مع الدعوى الجنائية ."}, {"number": "221", "chapter": "الفصل الثانى", "text": "تختصالمحكمة الجنائية بالفصل فى جميع المسائل التى يتوقف عليها الحكم فى الدعوى الجنائية المرفوعة أمامها ، مالم ينص القانون على خلاف ذلك ."}, {"number": "222", "chapter": "الفصل الثانى", "text": "إذا كان الحكم فى الدعوى الجنائية يتوقف على نتيجة الفصل فى دعوى جنائية أخرى ، وجب وقف الأولى حتى يتم الفصل فى الثانية"}, {"number": "223", "chapter": "الفصل الثانى", "text": "معدلة بالقانون رقم 303 لسنة 1953 ) إذا كان الحكم فى الدعوى الجنائية يتوقف على الفصل فى مسألة من مسائل الأحوال الشخصية ، جاز للمحكمة الجنائية أن توقف الدعوى ، وتحدد للمتهم أو للمدعى بالحقوق المدنية أو المجنى عليه حسب الأحوال أجلا لرفع المسألة المذكورة إلى الجهة ذات الإختصاص . ولايمنع وقف الدعوى من اتخاذ اتلإجراءات أو التحفظات الضرورية أو المستعجلة"}, {"number": "224", "chapter": "الفصل الثانى", "text": "إذا انقضى الأجل المشار إليه فى المادة السابقة ولم ترفع الدعوى إلى الجهة ذات الإختصاص يجوز للمحكمة أن تصرف النظر عن وقف الدعوى وتفصل فيها . كما يجوز لها أن تحدد للخصم أجلا أخر إذا رأت أن هناك أٍسباب مقبولة تبرر ذلك ."}, {"number": "225", "chapter": "الفصل الثانى", "text": "تتبع المحاكم الجنائية فى المسائل غير الجنائية التى تفصل فيها تبعا للدعوى الجنائية طرق الإثبات المقررة فى القانون الخاص بتلك المسائل ."}, {"number": "226", "chapter": "الفصل الثالث", "text": "إذا قدمت دعوى عن جريمة واحدة أو عدة جرائم مرتبطة إلى جهتين من جهات التحقيق أو الحكم تابعتين لمحكمة ابتدائية واحدة وقررت كل واحدة منهما نهائيا اختصاصها أو عدم اختصاصها وكان الإختصاص منحصرا فيهما ، يرفع طلب تعيين الجهة التى تفصل فيها إلى دائرة الجنح المستأنفة بالمحكمة الإبتدائية ."}, {"number": "227", "chapter": "الفصل الثالث", "text": "إذا صدر حكمان بالاختصاص أو بعدم الإختصاص من جهتين تابعتين لمحكمتين إبتدائيتين ، أو من محكمتين إبتدائيتين أو من محكمتين من محاكم الجنايات أو نمن محكمة عادية أو محكمة استثنائية يرفع طلب تعيين المحكمة المختصة إلى محكمة النقض ."}, {"number": "228", "chapter": "الفصل الثالث", "text": "لكل من الخصوم فى الدعوى تقديم طلب تعيين المحكمة التى تفصل فيها بعريضة مشفوعة بالأوراق المؤيدة لهذا الطلب ."}, {"number": "229", "chapter": "الفصل الثالث", "text": "تأمر المحكمة بعد إطلاعها على الطلب بإيداع الأوراق فى قلم الكتاب يطلع عليها كل من الخصوم الباقيين ، ويقدم مذكرة بأقواله فى مدة العشرة أيام التالية لإعلانه بالإيداع ، ويترتب على أمر الإيداع وقف السير فى الدعوى المقدم بشأنها الطلب ، مالم تر المحكمة غير ذلك ."}, {"number": "230", "chapter": "الفصل الثالث", "text": "تعين محكمة النقض أو المحكمة الإبتدائية بعد الإطلاع على الأوراق المحكمة أو الجهة التى تتولى السير فى الدعوى ، وتفصل أيضا فى شأن الإجراءات والأحكام التى تكون قد صدرت من المحاكم الأخرى التى قضت بإلغاء اختصاصها ."}, {"number": "231", "chapter": "الفصل الثالث", "text": "إذا رفض الطلب ، يجوز الحكم على الطالب إذا كان من غير النيابة العامة ، أو من يقوم بوظيفتها لدى جهات الحكم الاستثنائية بغرامة لا تتجاوز خمسة جنيهات .الباب الثاني فى محاكم المخالفات والجنح"}, {"number": "232", "chapter": "الفصل الأول", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) تحال الدعوى إلى محكمة الجنح والمخالفات بناء على أمر يصدر من قاضى التحقيق أو محكمة الجنح المستأنفة منعقدة فى غرفة المشورة أو بناء على تكليف المتهم مباشرة بالحضور من قبل أحد أعضاء النيابة العامة أو من المدعى بالحقوق المدنية . ويجوز الاستغناء عن تكليف المتهم بالحضور إذا حضر الجلسة ووجهت إليه التهمة من النيابة العامة وقبل المحاكمة ، ومع ذلك فلا يجوز للمدعى بالحقوق المدنية أن يرفع الدعوى إلى المحكمة بتكليف خصمه مباشرة بالحضور أمامها فى الحالتين الآتيتين : (_أولا ) إذا صدر أمر من قاضى التحقيق أو النيابة العامة بأن لاوجه لإقامة الدعوى ولم يستأنف المدعى بالحقوق المدنية هذا الأمر فى الميعاد أو إستأنفه فأيدته محكمة الجنح المستأنفة منعقدة فى غرفة المشورة . (ثانيا ) إذا كانت الدعوى موجهة ضد موظف أو مستخدم عام أو أحد رجال الضبط لجريمة وقعت منه أثناء تأدية وظيفته أو بسببها مالم تكن من الجرائم المشار إليها فى المادة 123 من قانون العقوبات ."}, {"number": "233", "chapter": "الفصل الأول", "text": "يكون تكليف الخصوم بالحضور أمام المحكمة قبل انعقاد الجلسة بيوم كامل فى المخالفات، وبثلاثة أيام كاملة على الأقل فى الجنح غير مواعيد مسافة الطريق ، وذلك بناء على طلب النيابة العامة أو المدعى بالحقوق المدنية . وتذكر فى ورقة التكليف بالحضور التهمة ومواد القانون التي تنص على العقوبة . ويجوز فى حالة التلبس ، وفى الحالات التى يكون فيها المتهم محبوسا احتياطيا فى إحدى الجنح ، أن يكون التكليف بالحضور بغير ميعاد ، فإذا حضر المتهم وطلب إعطائه ميعادا لتحضير دفاعه تأذن له المحكمة بالميعاد المقرر بالفقرة الأولى"}, {"number": "234", "chapter": "الفصل الأول", "text": "تعلن ورقة التكليف بالحضور لشخص المعلن إليه ، أو فى نمحل إقامته بالطرق المقررة فى قانون المرافعات فى المواد المدنية أو التجارية . وإذا لم يؤد البحث إلى معرفة محل إقامة المتهم ، يسلم الإعلان للسلطة الإدارية التابع لها أخر محل كان يقيم فيه فى مصر ، ويعتبر المكان الذي وقعت فيه الجريمة أخر محل إقامة للمتهم مالم يثبت خلاف ذلك . ويجوز فى مواد المخالفات إعلان ورقة التكليف بالحضور بواسطة رجال السلطة العامة كما يجوز ذلك فى مواد الجنح التي يعينها وزير العدل بقرار منه بعد موافقة وزير الداخلية"}, {"number": "235", "chapter": "الفصل الأول", "text": "يكون إعلان المحبوسين إلى مأمور السجن أومن يقوم مقامه ويكون إعلان الضباط وضابط الصف والعساكر الذين فى خدمة الجيش إلى إدارة الجيش . وعلى من يجب تسليم الصورة إليه فى الحالتين المذكورتين أن يوقع على الأًصل بذلك ، وإذا امتنع عن التسليم أو التوقيع ، يحكم عليه من قاضى المواد الجزئية بغرامة لاتزيد عن خمسة جنيهات ، وإذا أصر بعد ذلك على امتناعه تسلم الصورة إلى النيابة العامة بالمحكمة التابع لها المحضر لتسليمها إليه أو إلى المطلوب إعلانه شخصيا ."}, {"number": "236", "chapter": "الفصل الأول", "text": "للخصوم أن يطلعوا على أوراق الدعوى بمجرد إعلانهم بالحضور أمام المحكمة ."}, {"number": "237", "chapter": "الفصل الثانى", "text": "مستبدلة بالقانون 145 لسنة 2006 ) يجب على المتهم فى جنحة معاقب عليها بالحبس الذى يوجب القانون تنفيذه فور صدور الحكم به أن يحضر بنفسه، وإذا لم يكن للمتهم الحاضر فى جنحة معاقب عليها بالحبس وجوبا محام ، وجب على المحكمة أن تندب له محاميا للدفاع عنه . أما في الجنح الأخرى وفى المخالفات فيجوز لهى أن ينيب عنه وكيلا لتقديم دفاعه ، وهذا مع عدم الإخلال بما للمحكمة من الحق فى أن تأمر بحضوره شخصيا ."}, {"number": "238", "chapter": "الفصل الثانى", "text": "مستبدلة بالقانون رقم 170 لسنة 1981 ) إذا لم يحضر الخصم المكلف بالحضور حسب القانون فى اليوم المبين بورقة التكليف بالحضور ولم يرسل وكيلا عنه فى الأحوال التى يسوغ فيها ذلك يجوز الحكم فى غيبته بعد الإطلاع على الأوراق ، إلا إذا كانت ورقة التكليف بالحضور قد سلمت لشخصه وتبين للمحكمة أنه لامبرر لعدم حضوره فيعتبر الحكم حضوريا . ويجوز للمحكمة بدلا من الحكم غيابيا أن تؤجل الدعوى إلى جلسة تاليه وتأمر بإعادة إعلان الخصم فة موطنه مع تنبيهه إلى أنه إذا تخلف عن الحضور فى هذه الجلسة يعتبر الحكم الذى يصدر حضوريا فى حقه فإذا لم يحضر وتبين للمحكمة ألا مبرر لعدم حضوره يعتبر الحكم حضوريا ."}, {"number": "239", "chapter": "الفصل الثانى", "text": "يعتبر الحكم حضوريا بالنسبة إلى كل من يحضر من الخصوم عند النداء على الدعوى ولوغادر الجلسة بعد ذلك أو تخلف عن الحضور فى الجلسات التى تؤجل إليها الدعوى بدون أن يقدم عذرا مقبولا ."}, {"number": "240", "chapter": "الفصل الثانى", "text": "مستبدلة بالقانون رقم 170 لسنة 1981 - ) إذا رفعت الدعوى على عدة أِشخاص عن واقعة واحدة وحضر بعضهم وتخلف البعض الأخر رغم تكليفهم بالحضور حسب القانون فعلى المحكمة أن تؤجل الدعوى إلى جلسة تاليه وتأمر بإعادة إعلان من تخلف فى موطنه مع تنبيههم إلى أنهم إذا تخلفوا عن الحضور فى هذه الجلسة يعتبر الحكم الذى يصدر حضوريا فإذا لم يحضروا وتبين للمحكمة ألا مبرر لعدم حضورهم يعتبر الحكم حضوريا بالنسبة لهم ."}, {"number": "241", "chapter": "الفصل الثانى", "text": "فى الأحوال المتقدمة التى يعتبر الحكم فيها حضوريا يجب على المحكمة أن تحقق الدعوى أمامها كما لوكان الخصم حاضرا . ولتقبل المعارضة فى الحكم الصادر فى هذه الأحوال إلا إذا أثبت المحكوم عليه قيام عذر منعه من الحضور ولم يستطع تقديمه قبل الحكم وكان استئنافه غير جائز ."}, {"number": "242", "chapter": "الفصل الثانى", "text": "إذا حضر الخصم قبل انتهاء الجلسة التى صدر فيها الحكم عليه فى غيبته ، وجب إعادة نظر الدعوى فى حضوره ."}, {"number": "243", "chapter": "الفصل الثالث", "text": "مستبدلة بالقانون رقم 29 لسنة 1982 ) ضبط الجلسة وإدارتها منوطان برئيسها ، وله فى سبيل ذلك أن يخرج من قاعة الجلسة من يخل بنظامها فإن لم يمتثل وتمادى كان للمحكمة أن تأمر على الفور بحبسه أربعا وعشرين ساعة أو بتغريمه عشرة جنيهات ويكون حكمها بذلك غير جائز استئنافه ، فإذا كان الإخلال قد وقع ممن يؤدى وظيفة فى المحكمة كان لها أن توقع عليه أثناء انعقاد الجلسة ما لرئيس المصلحة توقيعه من الجزاءات التأديبية . وللمحكمة إلى ما قبل انتهاء الجلسة أن ترجع عن الحكم الذى تصدره ."}, {"number": "244", "chapter": "الفصل الثالث", "text": "معدلة بالقانون رقم 353 لسنة 1952 ) إذا وقعت جنحة أو مخالفة فى الجلسة ، يجوز للمحكمة أن تقيم الدعوى على المتهم فى الحال ، وتحكم فيها بعد سماع أقوال النيابة العامة ودفاع المتهم . ولا يتوقف رفع الدعوى فى هذه الحالة على شكوى أ, طلب إذا كانت من الجرائم المنصوص عليها فى المواد 3و8و9 من هذا القانون ، أما إذا وقعت جناية يصدر رئيس المحكمة أمرا بإحالة المتهم إلى النيابة العامة بدون إخلال بحكم المادة 13 من هذا القانون وفى جميع الأحوال يحرر رئيس المحكمة محضرا ، ويأمر بالقبض على المتهم إذا اقتضى الحال ذلك ."}, {"number": "245", "chapter": "الفصل الثالث", "text": "معدلة بالقانون رقم 353 لسنة 1952 ) استثناء من الأحكام المنصوص عليها فى المادتين السابقتين إذا وقع من المحامى أثناء قيامه بواجبه فى الجلسة وبسببه ما يجوز اعتباره تشويشا مخلا بالنظام ، أو ما يستدعى مؤاخذته جنائيا يحرر رئيس الجلسة محضرا بما حدث . وللمحكمة أن تقرر إحالة المحامى إلى النيابة العامة لإجراء التحقيق إذا كان ما وقع منه ما يستدعى مؤاخذته جنائيا ، وإلى رئيس المحكمة إذا كان ما وقع منه يستدعى مؤاخذته تأديبيا . وفى الحالتين لا يجوز أم يكون رئيس الجلسة التى وقع فيها الحادث أو أحد أعضائها عضوا فى الهيئة التى تنظر الدعوى ."}, {"number": "246", "chapter": "الفصل الثالث", "text": "الجرائم التى تقع فى الجلسة ، ولم تقم المحكمة الدعوى فيها حال انعقادها ، يكون نظرها وفقا للقواعد العادية ."}, {"number": "247", "chapter": "الفصل الرابع", "text": "يمتنع على القاضى أن يشترك فى نظر الدعوى إذا كانت الجريمة قد وقعت عليه شخصيا ، أو إذا كان قد قام فى الدعوى بعمل مأمور الضبط القضائي أو بوظيفة النيابة العامة أو المدافع عن أحد الخصوم ، أو أدى فيها شهادة . أو باشر عملا من أعمال أهل الخبرة . ويمتنع عليه كذلك أن يشترك فى الحكم إذا كان قد قام فى الدعوى بعمل من أعمال التحقيق أو الإحالة ، أو أن يشترك فى الحكم فى الطعن إذا كان المحكم المطعون فيه صادرا منه ."}, {"number": "248", "chapter": "الفصل الرابع", "text": "للخصوم رد القضاة عن الحكم فى الحالات الواردة فى المادة السابقة ، وفى سائر حالات الرد المبينة فى قانون المرافعات فى المواد المدنية والتجارية . ولا يجوز رد أعضاء النيابة العامة ولا مأمورى الضبط القضائى. ويعتبر المجنى عليه فيما يتعلق بطلب الرد بمثابة خصم فى الدعوى ."}, {"number": "249", "chapter": "الفصل الرابع", "text": "يتعبن على القاضى إذا قام سبب من أسباب الرد أن يصرح للمحكمة ، لا تفصل فى أنمر تنحيه فى غرفة المشورة ، وعلى القاضي الجزئي أن يطرح الأمر على رئيس المحكمة . وفيما عدا أحوال الرد المقررة بالقانون ، يجوز للقاضى إذا قامت لديه أسباب يستشعر منها الحرج من نظر الدعوى أ، يعرض أمر تنحيه على المحكمة ، أو على رئيس المحكمة حسب الأحوال للفصل فيه ."}, {"number": "250", "chapter": "الفصل الرابع", "text": "يتبع فى نظر طلب الرد والحكم فيه ، القواعد المنصوص عليها فى قانون المرافعات المدنية والتجارية ."}, {"number": "251", "chapter": "الفصل الخامس", "text": "لمن لحقه ضرر من الجريمة أن يقيم نفسه مدعيا بحقوق مدنية أمام المحكمة المنظورة أمامها الدعوى الجنائية ، وفى أية حالة كانت عليها الدعوى حتى صدور القرار بإقفال باب المرافعة طبقا للمادة 275 ، ولا يقبل منه ذلك أمام المحكمة الاستئنافية . ويحصل الإدعاء مدنيا بإعلان المتهم على يد محضر ، أو بطلب فى الجلسة المنظورة فيها الدعوى ، إذا كان المتهم حاضرا ، وإلا وجب تأجيل الدعوى وتكليف المدعى بإعلان المتهم بطلباته إليه . فإذا كان قد سبق قبوله فى التحقيق بهذه الصفة ، فإحالة الدعوى الجنائية إلى المحكمة تشمل الدعوى المدنية . ولا يجوز أن يترتب على تدخل المدعى بالحقوق المدنية تأخير الفصل فى الدعوى الجنائية ، وإلا حكمت المحكمة بعدم قبول دخوله"}, {"number": "251", "chapter": "الفصل الخامس", "text": "مكرا – ( مضافة بالقانون رقم 174 لسنة 1998 ) لا يجوز الإدعاء بالحقوق المدنية وفقا لأحكام هذا القانون إلا عن الضرر الشخصى المباشر الناشئ عن الجريمة والمحقق الوقوع ، حالا أو مستقبلا."}, {"number": "252", "chapter": "الفصل الخامس", "text": "إذا كان من لحقه ضرر من الجريمة فاقد الأهلية ولم يكن له من يمثله قانونا جاز للمحكمة المرفوعة أمامها الدعوى الجنائية بناء على طلب النيابة العامة أن تعين له وكيلا ليدعى بالحقوق المدنية بالنيابة عنه ولا يترتب على ذلك فى أى حال إلزامه بالمصاريف القضائية ."}, {"number": "253", "chapter": "الفصل الخامس", "text": "ترفع الدعوى المدنية بتعويض الضرر على المتهم بالجريمة إذا كان بالغا ، وعلى من يمثله إذا كان فاقد الأهلية ، فإن لم يكن له من يمثله ، وجب على المحكمة أن تعين من يمثله طبقا للمادة السابقة . ويجوز رفع الدعوى المدنية أيضا على المسئولين عن الحقوق المدنية عن فعل المتهم . وللنيابة العامة أن تدخل المسئولين عن الحقوق المدنية ، ولو لم يكن فى الدعوى مدع بحقوق مدنية للحكم عليهم بالمصاريف المستحقة للحكومة . ولا يجوز أمام المحاكم الجنائية أن ترفع دعوى الضمان ، ولا أن يدخل فى الدعوى غير المدعى عليهم بالحقوق المدنية والمسئول عن الحقوق المدنية والمؤمن لديه ."}, {"number": "254", "chapter": "الفصل الخامس", "text": "للمسئول عن الحقوق المدنية أن يدخل من تلقاء نفسه فى الدعوى الجنائية . فى أية حالة كانت عليها . وللنيابة العامة والمدعى بالحقوق المدنية المعارضة فى قبول تدخله ."}, {"number": "255", "chapter": "الفصل الخامس", "text": "يجب على المدعى بالحقوق المدنية أن يعين له محلا فى البلدة الكائن فيها مركز المحكمة . مالم يكن مقيما فيها ، ويكون ذلك بتقرير فى قلم الكتاب ، وإلا صح إعلان الأوراق إليه بتسليمها إلى قلم الكتاب ."}, {"number": "256", "chapter": "الفصل الخامس", "text": "على المدعى بالحقوق المدنية أن يدفع الرسوم القضائية ، وعليه أن يودع مقدما الأمانة التى تقدرها النيابة العامة أو قاضى التحقيق أو المحكمة على ذمة أتعاب ومصاريف الخبراء والشهود وغيرهم . وعليه أيضا إيداع الأمانة التكميلية التى قد تلزم أثناء سير الإجراءات ."}, {"number": "257", "chapter": "الفصل الخامس", "text": "لكل من المتهم والمسئول عن الحقوق المدنية والنيابة العامة أن يعارض فى الجلسة فى قبول المدعى بالحقوق المدنية إذا كانت الدعوى المدنية غير جائزة أو غير مقبولة ، وتفصل المحكمة فى المعارضة بعد سماع أقوال الخصوم ."}, {"number": "258", "chapter": "الفصل الخامس", "text": "لا يمنع القرار الصادر من قاضى التحقيق بعدم قبول المدعى بالحقوق المدنية من الإدعاء مدنيا بعد ذلك أمام المحكمة الجنائية ، أو من رفع دعواه أمام المحكمة المدنية . ولا يترتب على القرار الصادر من المحكمة بقبول الدعوى المدنية بطلان الإجراءات التى لم يشترك فيها المدعى بالحقوق المدنية قبل ذلك . والقرار الصادر من قاضى التحقيق بقبول المدعى بالحقوق المدنية لا يلزم المحكمة المرفوعة أمامها الدعوى ."}, {"number": "258", "chapter": "الفصل الخامس", "text": "مكرر – ( مضافة بالقانون رقم 865 لسنة 1976 ) يجوز رفع الدعوى المدنية قبل المؤمن لديه لتعويض الضرر الناشئ عن الجريمة أمام المحكمة التي تنظر الدعوى الجنائية . وتسرى على المؤمن لديه جميع الأحكام الخاصة بالمسئول عن الحقوق المدنية المنصوص عليه فى القانون ."}, {"number": "259", "chapter": "الفصل الخامس", "text": "معدلة بالقانون رقم 37 لسنة 1972 – ) تنقضي الدعوى المدنية بمضى المدة المقررة فى القانون المدنى ومع ذلك لاتنقضى بالتقادم الدعوى المدنية الناشئة عن الجرائم المنصوص عليها فى الفقرة الثانية من المادة 15 من هذا القانون والتي تقع بعد تاريخ العمل به . وإذا انقضت الدعوى الجنائية بعد رفعها لسبب من الأٍسباب الخاصة بها فلا تأثير لذلك فى سير الدعوى المدنية المرفوعة معها ."}, {"number": "260", "chapter": "الفصل الخامس", "text": "للمدعى بالحقوق المدنية أن يترك دعواه فى أية حالة كانت عليها الدعوى ، ويلزم بدفع المصاريف السابقة على ذلك ، مع عدم الإحلال بحق المتهم فى التعويضات إن كان لها وجه ولا يكون لهذا الترك تأثير على الدعوى الجنائية ، ومع ذك إذا كانت الدعوى قد رفعت بطريق الإدعاء المباشر فإنه يجب فى حالتى ترك الدعوى المدنية واعتبار المدعى بالحقوق المدنية تاركا دعواه ن الكم بترك الدعوى الجنائية مالم تطلب النيابة العامة الفصل فيها . ويترتب على الحكم بترك الدعوى الجنائية سقوط حق المدعى نفسه فى الإدعاء مدنيا عن ذات الفعل أمام المحكمة الجنائية"}, {"number": "261", "chapter": "الفصل الخامس", "text": "يعتبر تركا للدعوى عدم حضور المدعى أمام المحكمة بغير عذر مقبول بعد إعلانه لشخصه ، أو عدم إرساله وكيلا عنه ، وكذلك عدم إبدائه طلبات بالجلسة ."}, {"number": "262", "chapter": "الفصل الخامس", "text": "إذا ترك المدعى بالحقوق المدنية دعواه المرفوعة أمام المحاكم الجنائية ، يجوز له أن يرفعها أمام المحاكم المدنية . مالم يكن قد صرح بترك الحق المرفوع به الدعوى ."}, {"number": "263", "chapter": "الفصل الخامس", "text": "يترتب على ترك المدعى بالحقوق المدنية دعواه أو عدم قبوله مدعيا بحقوق مدنية ، استبعاد المسئول عن الحقوق المدنية من الدعوى إذا كان دخوله فيها بناء على طلب المدعى ."}, {"number": "264", "chapter": "الفصل الخامس", "text": "إذا رفع من ناله ضرر من الجريمة دعواه بطلب التعويض إلى المحكمة المدنية ، ثم رفعت الدعوى الجنائية ، جاز له إذا ترك دعواه أمام المحكمة المدنية أن يرفعها إلى المحكمة الجنائية مع الدعوى الجنائية ."}, {"number": "265", "chapter": "الفصل الخامس", "text": "إذا رفعت الدعوى المدنية أمام المحاكم المدنية ، يجب وقف الفصل فيها حتى يحكم نهائيا فى الدعوى الجنائية المقامة قبل رفعها أو فى أثناء السير فيها . على أنه إذا أوقف الفصل فى الدعوى الجنائية لجنون المتهم يفصل فى الدعوى المدنية"}, {"number": "266", "chapter": "الفصل الخامس", "text": "يتبع فى الفصل فى الدعوى المدنية التى ترفع أمام المحاكم الجنائية الإجراءات المقررة بهذا القانون ."}, {"number": "267", "chapter": "الفصل الخامس", "text": "مستبدلة بالقانون 174 لسنة 1998 ) للمتهم أن يطالب المدعى بالحقوق المدنية أمام المحاكم الجنائية بتعويض الضرر الذى لحقه بسبب رفع الدعوى المدنية عليه إن كان لذلك وجه ، وله كذلك أن يقيم عليه لذات السبب الدعوى المباشرة أمام ذات المحكمة بتهمة البلاغ الكاذب إن كان لذلك وجه ، وذلك بتكليفه مباشرة بالحضور أمامها ، ويجوز الاستغناء عن هذا التكليف إذا حضر المدعى بالحقوق المدنية الجلسة ووجه إليه المتهم التهمة وقبل المحاكمة ."}, {"number": "268", "chapter": "الفصل السادس", "text": "يجب أن تكون الجلسة علنية ن ويجوز للمحكمة مع ذلك مراعاة االنظام العام أو محافظة علىالأداب ن أن تأمر بسماع الدعوى كلها أو بعضها فى جلسة سرية ، أو تمنع فئات معينة من الحضور فيها ."}, {"number": "269", "chapter": "الفصل السادس", "text": "يجب أن يحضر أعضاء النيابة العامة جلسات المحاكم الجنائية وعلى المحكمة أن تسمع أقواله وتفصل فى طلباته ."}, {"number": "270", "chapter": "الفصل السادس", "text": "يحضر المتهم الجلسة بغير قيود ولا أغلال ، إنما تجرى عليه الملاحظة اللازمة . ولا يجوز إبعاده عن الجلسة أثناء نظر الدعوى ن إلا إذا وقع منه تشويش يستدعى ذلك ، وفى هذه الحالة تستمر الإجراءات إلى أن يمكن السير فيها بحضوره ، وعلى المحكمة أن توقفه على ماتم فى غيبته من الإجراءات ."}, {"number": "271", "chapter": "الفصل السادس", "text": "يبدأ التحقيق فى الجلسة بالمناداة على لخصوم والشهود ، ويسأل المتهم عن إسمه ولقبه وسنه وصناعته ومحل لإقامته ومولده وتتلى التهمة الموجهه إليه بأمرالإحالة أو بورقة لتكليف بالحضور على حسب الأحوال ثم تقدم للنيابة العامة والمدعى بالحقوق المدنية إن وجد طلباتهما . وبعد ذلك يسأل المتهم عما إذا كان معترفا بإرتكاب الفعل المستند إليه ، فإن إعترف جاز للمحكمة الإكتفاء بإعترافه والحكم عليه بغير سماع الشهود وإلا فتسمع شهادة شهود الإثبات ، ويكون توجيه الأسئله للشهود من النيابة العامة أولا ، ثم من المجنى عليه ثم من المدعى بالحقوق المدنية ثممن المتهم ، ثم من المسئول عن الحقوق المدنية . وللنيابة العامة وللمجنى عليه وللمدعى بالحقوق المدنية أ، يستجوبا الشهود – المذكورين مرة ثانية ، لإيضاح الوقائع التى أدووا الشهادة عنها فى أجوبتهم ."}, {"number": "272", "chapter": "الفصل السادس", "text": "بعد سماع شهادة شهود الإثبات يسمع شهود النفى ويسألأون بمعرفة المتهم أولا ، ثم بمعرفة المسئول عن الحقوق المدنية ، ثم بمعرفة النيابة العامة ، ثم بمعرفة المجتى عليه ، ثم بمعرفة المدعى بالحقوق المدنية ، وللمتهم والمسئول عن الحقوق المدنية أن يوجها للشهود المذكورين أسئلة مرة ثانية ، لإيضاح الوقائع التى أدوا الشهادة عنها فى أجوبتهم عن الأسئلة التى وجهت إليهم . ولكل من الخصوم أن يطلب إعادة سماع الشهود المذكورين لإيضاح أو تحقيق الوقائع التى أدوا شهادتهم عنها ، أو أن يطلب سماع شهود غيرهم لهذا الغرض ."}, {"number": "273", "chapter": "الفصل السادس", "text": "للمحكمة فى أية حالة كانت عليها الدعوى أن توجه للشهود أى سؤال ترى لزومه لظهور الحقيقة ، أو تأذن للخصوم بذلك . ويجب عليها منع توجيه أسئلة للشاهد إذا كانت غير متعلقة بالدعوى أو غير جائزة القبول ويجب عليها أ تمنع عن الشاهد كل كلام بالتصريح أو التلميح وكل إِشارة مما ينبني عليه إضطراب أفكاره أوتخويفه . ولها أن تمتنع عن سماع شهادة شهود عن وقائع ترى أنها واضحة وضوحا كافيا ."}, {"number": "274", "chapter": "الفصل السادس", "text": "لا يجوز استجواب المتهم إلا إذا قبل ذلك . وإذا ظهر أثناء المرافعة والمناقشة بعض وقائع ، يرى لزوم تقديم إيضاحات عنها من المتهم لظهور الحقيقة ، يلفته القاضى إليها ، ويرخص له بتقديم تلك الإيضاحات . وإذا أمتنع المتهم عن الإجابة ، أو إذا كانت أقواله فى الجلسة مخالفة لأقواله فى محضر جمع الإستدلالات أو التحقيق ، جاز للمحكمة أن تأمر بتلاوة أقواله الأولى ."}, {"number": "275", "chapter": "الفصل السادس", "text": "بعد سماع شهادة شهود الإثبات وشهود النفى يجوز للنيابة العامة وللمتهم ولكل من باقي الخصوم فى الدعوى أن يتكلم . وفى كل الأحوال يكون المتهم أخر من يتكلم . وللمحكمة أن تمنع المتهم أومحاميه من الإسترسال فىالمرافعة إذا خرج عن موضوع الدعوى أو كرر أقواله . وبعد ذلك تصدر المحكمة قرارها بإقفال باب المرافعة ، ثم تصدر حكمها بعد المداولة."}, {"number": "276", "chapter": "الفصل السادس", "text": "يجب أن يحرر محضرا بما يجرى فى جلسة المحاكمة ويوقع على كل صفحة منه رئيس المحكمة وكاتبها فى اليوم التالى على الأكثر ، ويشتمل هذا المحضر على تاريخ الجلسة ، ويبين به ما إذا كانت علنية أوسريه ، وأسماء القضاة والكاتب وعضو النيابة العامة الحاضر بالجلسة وأسماء الخصوم والمدافعين عنهم وشهادة الشهود وأقوال الخصوم ، ويشار فيه إلى الأوراق التى تليت ن وسائر الإجراءات التى تمت وتدون به الطلبات التى قدمت أثناء نظر الدعوى وماقضى به فى المسائل الفرعية ، ومنطوق الأحكام الصادرة ، وغير ذلك مما يجرى فى الجلسة ."}, {"number": "276", "chapter": "الفصل السادس", "text": "مكرر ( مضافة بالقانون رقم 113 لسنة 1957 ) يحكم على وجه السرعة فى القضايا الخاصة بالأداث ، والخاصة بالجرائم المنصوص عليها فى الأبواب الأول والثانى والثانى مكرر والثالث والرابع ، والرابع عشر من الكتاب الثانى من قانون العقوبات والجرائم المنصوص عليها فى المواد 302و303و306و307و308 من قانون العقوبات إذا وقعت بواسطة الصحف ، والقانون رقم 394 لسنة 1954 فى شأن الأسلحة والذخائر المعدل بالقانون رقم 546 لسنة 1954. ويكون تكليف المتهم بالحضور أمام المحكمة فى القضايا المبينة بالفقرة السابقة قبل إنعقاد الجلسة بيوم كامل فى مواد الجنح وثلاثة أيام كاملة فى مواد الجنايات غير مواعيد مسافة الطريق. ويجوز أن يكون الإعلان بواسطة أحد المحضرين أو أحد رجال السلطة العامة . وتنظر القضية فى جلسة تعقد فى ظرف أسبوعين من يوم إحالتها إلى المحكمة المختصة ، وإذا كانت القضية محالة على محكمة الجنايات، يقوم رئيس محكمة الاستئناف المختصة بتحديد جلسة فى الميعاد المذكور ."}, {"number": "277", "chapter": "الفصل السابع", "text": "يكلف الشهود بالحضور بناء على طلب الخصوم بواسطة أحد المحضرين أو أ؛د رجال الضبط قبل الجلسة بأربع وعشرين ساعة غير مواعيد مسافة الطريق إلا فى حالة التلبس بالجريمة . فإنه يجوز تكليفهم بالحضور فى أى وقت ولو شفهيا بواسطة أحد مأمورى الضبط القضائي . وللمحكمة أثناء نظر الدعوى أن تستدعى وتسمع أقوال أى شخص ولو بإصدار أمر بالضبط والإحضار ، إذا دعت الضرورة لذلك ن ولها أن تأمر بتكليفه بالحضور فى جلسة أخرى . وللمحكمة أن تسمع شهادة أى إنسان يحضر من تلقاء نفسه لإبداء معلومات فى الدعوى"}, {"number": "278", "chapter": "الفصل السابع", "text": "ينادى على الشهود بأسمائهم ، وبعد الإجابة منهم يحجزون فى الغرفة المخصصة لهم ، ولا يخرجون منها إلا بالتوالى لتأدية الشهادة أمام المحكمة ، ومن تسمع شهادته منهم يبقى فى قاعة الجلسة إلى حين إقفال باب المرافعة مالم ترخص له المحكمة بالخروج ، ويجوز عند الإقتضاء أن يبعد شاهد أثناء سماع شاهد أخر ، وتسوغ مواجهة الشهود بعضهم ببعض"}, {"number": "279", "chapter": "الفصل السابع", "text": "إذا تخلف الشاهد عن الحضور أمام المحكمة بعد تكليفه به جاز الحكم عليه بعد سماع أقوال النيابة العامة بدفع غرامة لاتجاوز عشرة جنيهات فى المخالفات وثلاثين جنيها فى الجنح ، وخمسين جنيها فى الجنايات . ويجوز للمحكمة إن رأت شهادته ضرورية أن تؤجل الدعوى لإ عادة تكليفه بالحضور ولها أن تأمر بالقبض عليه وإحضاره ."}, {"number": "280", "chapter": "الفصل السابع", "text": "إذا حضر الشاهد بعد تكليفه بالحضور مرة ثانية أومن تلقاء نفسه ، وأبدى أعذارا مقبوله ، جاز إعفاؤه من الغرامة بعد سماع أقوال النيابة العامة . وإذا لم يحضر الشاهد فى المرة الثانية جاز الحكم عليه بغرامة لاتتجاوز ضعف الحد الأقصى المقرر فى المادة السابقة وللمحكمة أن تأمر بالقبض عليه وإحضاره فى نفس الجلسة أو فى جلسة أخرى تؤجل إليها الدعوى ."}, {"number": "281", "chapter": "الفصل السابع", "text": "للمحكمة إذا أعتذر الشاهد بأعذار مقبولة عن عدم إمكانه الحضور أن تنتقل إليه وتسمع شهادته بعد إحطار النيابة العامة وباقى الخصوم ، وللخصوم أن يحضروا بأنفسهم أو بواسطة وكلائهم ، وأن يوجهوا للشاهد الأسئلة اتلتى يرون لزوم توجيهها إليه."}, {"number": "282", "chapter": "الفصل السابع", "text": "إذا لم يحضر الشاهد أمام المحكمة حتى صدور الحكم فى الدعوى ، جاز له الطعن فى كم الغرامة بالطرق المعتادة ."}, {"number": "283", "chapter": "الفصل السابع", "text": "يجب على الشهود الذين بلغت سنهم أربعة عشرة سنة أن يحلفوا يمينا قبل أداء الشهادة على أنهم يشهدون بالحق ولا يقولون إلا الحق ويجوز سماع الشهود الذين لم يبلغوا أربعة عشرة سنة كاملة بدون حلف يمين على سبيل الاستدلال ."}, {"number": "284", "chapter": "الفصل السابع", "text": "إذاأمتنع الشاهد عن أداء اليمين أو عن الإجابة فى غير الأحوال التى يجيز له القانون فيها بذلك ن حكم عليه فى مواد المخالفات بغرامة لاتزيد على عشرة جنبهات وفى مواد الجنح والجنايات بغرامة لاتزيد عن مائتى جنيه . وإذا عدل الشاهد عن إمتناعه قبل إقفال باب المرافعة يعفى من العقوبة المحكوم بها عليه كلها أو بعضها ."}, {"number": "285", "chapter": "الفصل السابع", "text": "لا يجوز رد الشهود لأى سبب من الأسباب ."}, {"number": "286", "chapter": "الفصل السابع", "text": "يجوز أن يمتنع عن الشهادة ضد المتهم أصوله وفروعه وأقاربه وأصهاره إلى الدرجة الثانية ، وروجه ولو بعد انقضاء رابطة الزوجية . وذلك مالم تكن الجريمة قد وقعت على الشاهد أوعلى أحد أقاربه أو أصهاره الأقربين أو إذا كان المبلغ عنها ، أو إذا لم تكن هناك أدلة إثبات أخرى ."}, {"number": "287", "chapter": "الفصل السابع", "text": "تسرى أمام المحاكم الجنائية القواعد المقررة فى قانون المرافعات لمنع الشاهد عن أداء الشهادة أو لإعفائه من لأدائها ."}, {"number": "288", "chapter": "الفصل السابع", "text": "يسمع المدعى بالحقوق المدنية كشاهد ويحلف اليمين ."}, {"number": "289", "chapter": "الفصل السابع", "text": "معدلة بالقانون رقم 113 لسنة 1957) للمحكمة أن تقرر تلاوة الشهادة التى أبديت فى التحقيق الإبتدائى أو فى محضر جمع الاستدلالات أو خبير الخطوط إذا تعذر سماع الشاهد لأي سبب من الأسباب أو قبل المتهم أو المدافع عنه ذلك ."}, {"number": "290", "chapter": "الفصل السابع", "text": "إذا قرر الشاهد أنه لم يعد يذكر واقعة من الوقائع يجوز أن يتلى من شهادته التى أقرها فى التحقيق ، أو من أقواله فى محضر جمع الاستدلالات الجزء الخاص بهذه الواقعة . وكذلك الحال إذا تعارضت شهادة الشاهد التى أداها فى الجلسة مع شهادته أو أقواله السابقة ."}, {"number": "291", "chapter": "الفصل السابع", "text": "للمحكمة أن تأمر ، ولو من تلقاء نفسها أثناء نظر الدعوى بتقديم أى دليل تراه لازما لظهور الحقيقة."}, {"number": "292", "chapter": "الفصل السابع", "text": "للمحكمة سواء من تلقاء نفسها ، أو بناء على طلب الخصوم أن تعين خبيرا واحدا أو أكثر فى الدعوى ."}, {"number": "293", "chapter": "الفصل السابع", "text": "للمحكمة من تلقاء نفسها ، أو بناء على طلب الخصوم أن تأمر بإ‘لان الخبراء ليقدموا إيضاحات بالجلسة عن التقارير المقدمة منهم فى التحقيق الإبتدائى أو أمام المحكمة ."}, {"number": "294", "chapter": "الفصل السابع", "text": "إذا تعذر تحقيق دليل أمام المحكمة ، جاز لها أن تندب أحد أعضائها أو قاضيا أخر لتحقيقه ."}, {"number": "295", "chapter": "الفصل الثامن فى دعوى التزوير الفرعية", "text": "للنيابة العامة ولسائر الخصوم فى أية حالة كانت عليها الدعوى ، أن يطعنوا بالتزوير فى أية ورقة من أوراق القضية ومقدمة فيها ."}, {"number": "296", "chapter": "الفصل الثامن فى دعوى التزوير الفرعية", "text": "يحصل الطعن بتقرير فى قلم كتناب المحكمة المنظورة أمامها الدعوى ، ويجب أن تعين فيه الورقة المطعون فيها بالتزوير والأدلة على تزويرها ."}, {"number": "297", "chapter": "الفصل الثامن فى دعوى التزوير الفرعية", "text": "مستبدلة بالقانون 74 لسنة 2007 ) إذا رأت المحكمة المنظور أمامها الدعوى وجها للسير فى تحقيق الإدعاء بالتزوير، و كان الفصل فى الدعوى المنظورة أمامها يتوقف على الورقة المطعون فيها، تحقق المحكمة الواقعة بنفسها ،ومع ذلك يجوز لها إذا تعذر عليها ذلك أن تحيل الأوراق إلى النيابة العامة ، وفى هذه الحالة توقف الدعوى إلى أن يفصل فى الإدعاء بالتزوير . وإذا تبين للمحكمة أن الورقة المطعون فيها مزورة تفصل فى الدعوى وتحيل وتحيل الواقعة للنيابة العامة لإتخاذ شئونها فيها . وفى حالة عدم وجود تزوير تقضى المحكمة بإلزام مدعى التزوير بغرامة لاتجاوز خمسة ألاف جنيه ."}, {"number": "297", "chapter": "الفصل الثامن فى دعوى التزوير الفرعية", "text": "إذا رأت الجهة المنظورة أمامها الدعوى وجها للسير فى تحقيق التزوير تحيل الأوراق إلى النيابة العامة ولها أن توقف الدعوى إلى أن يفصل فى التزوير من الجهة المختصة ، إذا كان الفصل فى الدعوى المنظورة أمامها يتوقف على الورقة المطعون فيها."}, {"number": "298", "chapter": "الفصل الثامن فى دعوى التزوير الفرعية", "text": "ملغاة بالقانون 74 لسنة 2007"}, {"number": "299", "chapter": "الفصل الثامن فى دعوى التزوير الفرعية", "text": "إذا حكم بتزوير ورقة رسمية ، كلها أو بعضها ، تأمر المحكمة التى حكمت بالتزوير بإلغائها أو تصحيحها حسب الأحوال ، ويحرر بذلك محضر يحرر على الورقة بمقتضاه ."}, {"number": "300", "chapter": "الفصل التاسع", "text": "لا تتقيد المحكمة بما هو مدون فى التحقيق الإبتدائى أو فى محاضر جمع الاستدلالات ، إلا إذا وجد فى القانون نص على خلاف ذلك ."}, {"number": "301", "chapter": "الفصل التاسع", "text": "تعتبر المحاضر المحررة فى مواد المخالفات حجة بالنسبة للوقائع التى يثبتها المأمورون المختصون إلى أن تثبت ما ينفيها ."}, {"number": "302", "chapter": "الفصل التاسع", "text": "يحكم القاضى فى الدعوى حسب العقيدة التى تكونت لديه بكامل حريته ، ومع ذلك لا يجوز له أن يبنى حكمه على أى دليل لم يطرح أمامه فى الجلسة . وكل قول يثبت أنه صدر من أحد المتهمين أو الشهود تحت وطأة الإكراه أو التهديد به يهدر ولايعول عليه ."}, {"number": "303", "chapter": "الفصل التاسع", "text": "يصدر الحكم فى الجلسة العلنية ، ولو كانت الدعوى نظرت فى جلسة سرية ، ويجب إثباته فى محضر الجلسة ويوقع عليه رئيس المحكمة والكاتب . وللمحكمة أن تأمر باتخاذ الوسائل اللازمة لمنع المتهم من مغادرة قاعة الجلسة قبل النطق بالحكم أو لضمان حضوره فى الجلسة التى يؤجل لها الحكم ، ولو كان ذلك بإصدار أمر بحبسه ، إذا كانت الواقعة مما يجوز فيها الحبس الاحتياطي ."}, {"number": "304", "chapter": "الفصل التاسع", "text": "إذا كانت الواقعة غير ثابتة أو كان القانون لايعاقب عليها تحكم المحكمة ببراءة المتهم ويفرج عنه إن كان محبوسا من أجل هذه الواقعة وحدها . أما إذا كانت الواقعة ثابتة وتكون فعلا معاقبا عليها ن تقضى المحكمة بالعقوبة المقررة فى القانون"}, {"number": "305", "chapter": "الفصل التاسع", "text": "معدلة بالقانون رقم 107 لسنة 1963 ) إذا تبين للمحكمة الجزئية أن الواقعة جناية أو أنها جنحة من الجنح التى تقع بواسطة الصحف أو غيرها من طرق النشر على غير الأفراد، تحكم بعدم اختصاصها وتحيلها للنيابة العامة لاتخاذ ما يلزم فيها"}, {"number": "306", "chapter": "الفصل التاسع", "text": "ملغاة بالقانون رقم 107 لسنة 1963 )"}, {"number": "307", "chapter": "الفصل التاسع", "text": "لاتجوز معاقبة المتهم عن واقعة غير التى وردت بأمر الإحالة أو طلب التكليف بالحضور ، كما لا يجوز الحكم على غير المتهم المقامة عليه الدعوى ."}, {"number": "308", "chapter": "الفصل التاسع", "text": "للمحكمة أن تغير فى حكمها الوصف القانوني للفعل المسند إلى المتهم ، ولها تعديل التهمة بإضافة الظروف المشددة التى تثبت من التحقيق أو من المرافعة فى الجلسة ، ولو كانت لم تذكر بأمر الإحالة أو التكليف بالحضور . ولها أيضا إصلاح كل خطأ مادى وتدارك كل سهو فى عبارة الاتهام مما يكون فى أمر الإحالة ، أو فى طلب التكليف بالحضور . وعلى المحكمة أن تنبه المتهم إلى هذا التغيير ، وأن تمنحه أجلا لتحضير دفاعه بناء على الوصف أو التعديل الجديد إذا طلب ذلك ."}, {"number": "309", "chapter": "الفصل التاسع", "text": "كل حكم يصدر فى موضوع الدعوى الجنائية يجب أن يفصل فى التعويضات التى يطلبها المدعى بالحقوق المدنية أو المتهم ، وكذلك فى الدعوى المباشرة التى يقيمها المتهم على المدعى بالحقوق المدنية طبقا للمادة (267) من هذا القانون . ومع ذلك إذا رأت المحكمة أن الفصل فى التعويضات يستلزم إجراء تحقيق خاص ينبني عليه إرجاء الفصل فى الدعوى الجنائية ، فعندئذ تحيل المحكمة الدعوى المدنية إلى المحكمة المختصة بلا مصروفات ."}, {"number": "310", "chapter": "الفصل التاسع", "text": "يجب أن يشتمل الحكم على الأسباب التى بنى عليها ن وكل حكم بالإدانة يجب أن يشتمل على بيان الواقعة المستوجبة للعقوبة والظروف التى وقعت فيها ، وأن يشير إلي نص القانون الذى حكم بموجبه ."}, {"number": "311", "chapter": "الفصل التاسع", "text": "يجب على المحكمة أن تفصل فى الطلبات التى تقدم لها من الخصوم ، وتبين الأسباب التى تستند إليها ."}, {"number": "312", "chapter": "الفصل التاسع", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) يحرر الحكم بأسبابه كاملا خلال ثمانية أيام من تاريخ صدوره بقدر الإمكان . ويوقع عليه رئيس المحكمة وكاتبها ، وإذا حصل مانع للرئيس يوقعه أحد القضاة الذين اشتركوا معه فى إصداره وإذا كان الحكم صادرا من المستشار الفرد أو من المحكمة الجزئية وكان القاضى الذى أصدره قد وضع أسبابه بخطه يجوز لرئيس محكمة الاستئناف أو رئيس المحكمة الابتدائية حسب الأحوال أو يوقع بنفسه على نسخة الحكم الأصلية ، أو يندب أحد القضاة للتوقيع عليها بناء على تلك الأسباب ، فإذا لم يكن القاضى قد كتب الأسباب بخطه يبطل الحكم لخلوه من الأسباب . ولا يجوز تأخير توقيع الحكم على الثمانية أيام المقررة إلا لأسباب قوية ، وعلى كل حال يبطل الحكم إذا مضى ثلاثون يوما دون حصول التوقيع ، مالم يكن صادرا بالبراءة ، وعلى قلم الكتاب أن يعطى صاحب الشأن بناء على طلبه ، شهادة بعدم توقيع الحكم فى الميعاد المذكور ."}, {"number": "312", "chapter": "الفصل التاسع", "text": "مكرر ( مضافة بالقانون 145 لسنة 2006 ) تلتزم النيابة العامة بنشر كل حكم بات ببراءة من سبق حبسه إحتياطيا ، وكذلك كل أمر صادر بأن لاوجه لإقامة الدعوى الجنائية قبله فى جريدتين يوميتين واسعتى الإنتشار على نفقة الحكومة ، ويكون النشر فى الحالتين بناء على طلب النيابة العامة أو المتهم أو أحد ورثته وبموافقة النيابة العامة فى حالة صدور أمر بأن لاوجه لإقامة الدعوى . وتعمل الدولة على أن تكفل الحق فى مبدأ التعويض المادى عن الحبس الإحتياطى فى الحالتين المشار إليهما فى الفقرة السابقة وفقا للقواعد والإجراءات التى يصدر بها قانون خاص ."}, {"number": "313", "chapter": "الفصل العاشر", "text": "كل من حكم عليه فى جريمة ، يجوز إلزامه بالمصاريف كلها أو بعضها ."}, {"number": "314", "chapter": "الفصل العاشر", "text": "إذا حكم فى الاستئناف بتأييد الحكم الإبتدائى جاز إلزام المتهم المستأنف بكل مصاريف الاستئناف أو بعضها ."}, {"number": "315", "chapter": "الفصل العاشر", "text": "إذا برىء المحكوم عليه غيابيا ، بناء على معارضته يجوز إلزامه بكل أو بعض مصاريف الحكم الغيابي وإجراءاته ."}, {"number": "316", "chapter": "الفصل العاشر", "text": "لمحكمة النقض أن تحكم بمصاريف الطعن كلها أو بعضها على المتهم المحكوم عليه ، إذا لم يقبل طلبه أو إذا رفض ."}, {"number": "317", "chapter": "الفصل العاشر", "text": "إذا حكم على عدة متهمين بحكم واحد لجريمة واحدة . فاعلين كانوا أو شركاء ، فالمصاريف التى يحكم بها تحصل منهم بالتساوى ، مالم يقض الحكم بتوزيعها بينهم على خلاف ذلك أو إلزامهم بها متضامنين ."}, {"number": "318", "chapter": "الفصل العاشر", "text": "إذا لم يحكم على المتهم بكل المصاريف ، وجب أـ، يحدد فى الحكم مقدار مايحكم به عليه منها ."}, {"number": "319", "chapter": "الفصل العاشر", "text": "يكون المدعى بالحقوق المدنية ملزما للحكومة بمصاريف الدعوى ، ويتبع فى تقدير المصاريف وكيفية تحصيلها ماهو وارد فى لائحة الرسوم القضائية ."}, {"number": "32", "chapter": "الفصل العاشر", "text": ".- إذا حكم بإدانة المتهم فى الجريمة ، وجب الحكم عليه للمدعى بالحقوق المدنية بالمصاريف التى تحملها وللمحكمة مع ذلك أن تخفض مقدارها إذا رأت أن بعض هذه المصاريف كان غير لازم . إلا أنه إذا لم يحكم للمدعى بالحقوق المدنية بتعويضات تكون عليه المصاريف التى إستلزمها دخوله فى الدعوى ن أما إذا قضى له ببعض التعويضات التى طلبها يجوز تقديلار هذه المصاريف على نسبة تبين فى الحكم ."}, {"number": "321", "chapter": "الفصل العاشر", "text": "يعامل المسئول عن الحقوق المدنية معاملة المتهم فيما يختص بمصاريف الدعوى المدنية ."}, {"number": "322", "chapter": "الفصل العاشر", "text": "إذا حكم على المتهم بمصاريف الدعوى الجنائية كلها أو بعضها ، وجب إلزام المسئول عن الحقوق المدنية معه بما حكم به ، وفى هذه الحالة تحصل المصاريف المحكوم بها من كل منهما بالتضامن"}, {"number": "323", "chapter": "الفصل الحادى عشر", "text": "للنيابة العامة فى مواد الجنح التى لا يوجب القانون الحكم فيها بعقوبة الحبس ، إذا رأت أن الجريمة بحسب ظروفها تكفى فيها عقوبة الغرامة فضلا عن العقوبات التكميلية والتضمينات وما يجب رده والمصاريف ، أن تطلب من قاضى المحكمة الجزئية التى من اختصاصها نظر الدعوى توقيع العقوبة على المتهم بأمر يصدره بناء على محضر جمع الاستدلالات أو أدلة الاثبات الأخرى بغير إجراء أو سماع مرافعة . مضافة بالقانون 74 لسنة 2007"}, {"number": "323 مكرر", "chapter": "الفصل الحادى عشر", "text": "للقاضى ، من تلقاء نفسه ، عند نظر إحدى الجنح المبينة فى المادة 323 أن يصدر فيها أمرا جنائيا ، وذلك إذا تغيب المتهم عن الحضور رغم إعلانه ، ولم تكن النيابة العامة قد طلبت توقيع أقصى العقوبة ."}, {"number": "324", "chapter": "الفصل الحادى عشر", "text": "لا يقضى فى الأمر الجنائى بغير الغرامة والعقوبات التكميلية والتضمينات وما يجب رده والمصاريف ، ويجوز أن يقضى فيه بالبراءة أو برفض الدعوى المدنية أو بوقف تنفيذ العقوبة . مستبدلة بالقانون 74 لسنة 2007"}, {"number": "325", "chapter": "الفصل الحادى عشر", "text": "يرفض القاضى إصدار الأمر إذا رأى : أولاً : أنه يمكن الفصل فى الدعوى بحالتها التى هى عليها أو بدون تحقيق أو مرافعة . ثانياً : أن الواقعة نظراً لسوابق المتهم ، أو لأى سبب آخر ، تستوجب توقيع عقوبة أشد من الغرامة التى يجوز صدور الأمر بها . ويصدر القاضى قراره بالرفض بتأشيرة على الطلب الكتابى المقدم له ، ولا يجوز الطعن فى هذا القرار . ويترتب على قرار الرفض وجوب السير فى الدعوى بالطرق العادية ."}, {"number": "325 مكرر", "chapter": "الفصل الحادى عشر", "text": "لكل عضو نيابة ، من درجة وكيل نيابة على الأقل ، بالمحكمة التى من اختصاصها نظر الدعوى ، أن يصدر الأمر الجنائى فى الجنح التى لا يوجب القانون الحكم فيها بالحبس أو الغرامة التى يزيد حدها الأدنى على ألف جنيه فضلا عن العقوبات التكميلية والتضمينات وما يجب رده والمصاريف. ولا يجوز أن يؤمر بغير الغرامة التى لا يزيد حدها الأقصى على ألف جنيه والعقوبات التكميلية والتضمينات وما يجب رده والمصاريف ، ويكون إصدار الأمر الجنائى وجوبيا فى المخالفات وفى الجنح المعاقب عليها بالغرامة وحدها التى لا يزيد حدها الأقصى على خمسمائة جنيه ، والتى لا يرى حفظها. وللمحامى العام ولرئيس النيابة ، حسب الأحوال ، فى ظرف عشرة أيام من تاريخ صدور الأمر الجنائى ، أن يأمر بتعديله أو بإلغائه وحفظ الأوراق والتقرير فى الدعوى بأن لا وجه لإقامتها أو رفعها إلى المحكمة المختصة والسير فى الدعوى الجنائية بالطرق العادية ، ولا يجوز إعلان الأمر للخصوم قبل انقضاء هذه المدة. معدلة بالقانون 74 لسنة 2007"}, {"number": "326", "chapter": "الفصل الحادى عشر", "text": "يجب أن يعين فى الأمر فضلاً عما قضى به اسم المتهم والواقعة التى عوقب من أجلها ومادة القانون التى طبقت . ويعلن الأمر إلى المتهم والمدعى بالحقوق المدنية على النموذج الذى يقره وزير العدل ، ويجوز أن يكون الإعلان بواسطة أحد رجال السلطة العامة ."}, {"number": "327", "chapter": "الفصل الحادى عشر", "text": "للنيابة العامة أن تعلن عدم قبولها للأمر الجنائى الصادر من القاضى ، ولباقى الخصوم أن يعلنوا عدم قبولهم للأمر الصادر من القاضى أو من النيابة العامة ، ويكون ذلك بتقرير بقلم كتاب محكمة الجنح المستأنفة فيما يتعلق بالأمر الصادر من القاضى طبقاً للمادة 323 مكرراً من هذا القانون ، وبتقرير بقلم كتاب محكمة الجنح فى غير هذه الحالات ، وذلك كله خلال عشرة أيام من تاريخ صدور الأمر بالنسبة للنيابة العامة ، ومن تاريخ إعلانه بالنسبة لباقى الخصوم. ويترتب على هذا التقرير سقوط الأمر واعتباره كأن لم يكن. ويحدد الكاتب اليوم الذى تنظر فيه الدعوى أمام المحكمة مع مراعاة المواعيد المقررة فى المادة 233. وينبه على المقرر بالحضور فى هذا اليوم ويكلف باقى الخصوم والشهود بالحضور فى الميعاد المنصوص عليه فى المادة 400. أما إذا لم يحصل اعتراض على الأمر بالطريقة المتقدمة يصبح نهائيا واجب التنفيذ. ولا يكون لما قضى به الأمر فى موضوع الدعوى الجنائية حجية أمام المحاكم المدنية. معدلة بالقانون 74 لسنة 2007"}, {"number": "328", "chapter": "الفصل الحادى عشر", "text": "إذا حضر الخصم الذى لم يقبل الأمر الجنائى فى الجلسة المحددة ، تنظر الدعوى فى مواجهته وفقاً للإجراءات العادية . أما إذا لم يحضر تعود للأمر قوته ، ويصبح نهائياً واجب التنفيذ . الفقرة الثانية ملغاة بالقانون 74 لسنة 2007"}, {"number": "329", "chapter": "الفصل الحادى عشر", "text": "إذا تعدد المتهمون وصدر ضدهم أمر جنائى وقرروا عدم قبوله ، وحضر بعضهم فى اليوم المحدد لنظر الدعوى ولم يحضر البعض الآخر تنظر الدعوى بالطرق المعتادة بالنسبة لمن حضر ، ويصبح الأمر نهائياً بالنسبة لمن لم يحضر ."}, {"number": "330", "chapter": "الفصل الحادى عشر", "text": "إذا ادعى المتهم عند التنفيذ عليه أن حقه فى عدم قبول الأمر لا يزال قائماً لعدم إعلانه بالأمر ، أو لغير ذلك من الأسباب أو أن مانعاً قهرياً منعه من الحضور فى الجلسة المحددة لنظر الدعوى ، أو إذا حصل إشكال آخر فى التنفيذ يقدم الإشكال الى القاضى الذى أصدر الأمر ، ليفصل فيه بغير مرافعة ، إلا إذا رأى عدم إمكان الفصل فيه بحالته أو بدون تحقيق أو مرافعة ويحدد يوماً لينظر فى الإشكال وفقاً للإجراءات العادية ، ويكلف المتهم وباقى الخصوم فى اليوم المذكور ، فإذا قبل الإشكال تجرى المحاكمة وفقاً للمادة 328 ."}, {"number": "331", "chapter": "الفصل الثانى عشر", "text": "يترتب البطلان على عدم مراعاة أحكام القانون المتعلقة بأى إجراء جوهرى ."}, {"number": "332", "chapter": "الفصل الثانى عشر", "text": "إذا كان البطلان راجعاً لعدم مراعاة أحكام القانون المتعلقة بتشكيل المحكمة أو بولايتها بالحكم فى الدعوى أو باختصاصها من حيث نوع الجريمة المعروضة عليها أو بغير ذلك مما هو متعلق بالنظام العام ، جاز التمسك به فى أية حالة كانت عليها الدعوى ، وتقضى به المحكمة ولو بغير طلب ."}, {"number": "333", "chapter": "الفصل الثانى عشر", "text": "فى غير الأحوال المشار إليها فى المادة السابقة يسقط الحق فى الدفع ببطلان الإجراءات الخاصة بجمع الاستدلالات أو التحقيق الابتدائى أو التحقيق بالجلسة فى الجنح والجنايات إذا كان للمتهم محام وحصل الإجراء بحضوره بدون اعتراض منه . أما فى مواد المخالفات فيعتبر الإجراء صحيحاً اذا لم يعترض عليه المتهم ولو لم يحضر معه محام فى الجلسة . وكذلك يسقط حق الدفع بالبطلان بالنسبة للنيابة العامة إذا لم تتمسك به فى حينه ."}, {"number": "334", "chapter": "الفصل الثانى عشر", "text": "إذا حضر المتهم فى الجلسة بنفسه أو بواسطة وكيل عنه فليس له أن يتمسك ببطلان ورقة التكليف بالحضور ، وإنما له أن يطلب تصحيح التكليف أو استيفاء أى نقص وإعطاءه ميعاداً لتحضير دفاعه قبل البدء فى سماع الدعوى ، وعلى المحكمة إجابته الى طلبه ."}, {"number": "335", "chapter": "الفصل الثانى عشر", "text": "يجوز للقاضى أن يصحح ، ولو من تلقاء نفسه ، كل إجراء يتبين له بطلانه ."}, {"number": "336", "chapter": "الفصل الثانى عشر", "text": "إذا تقرر بطلان أى إجراء فإنه يتناول جميع الآثار التى تترتب عليه مباشرة ، ولزم إعادته متى أمكن ذلك ."}, {"number": "337", "chapter": "الفصل الثانى عشر", "text": "إذا وقع خطأ مادى فى حكم أو فى أمر صادر من قاضى التحقيق أو من محكمة الجنح المستأنفة منعقدة فى غرفة المشورة ، ولم يكن يترتب عليه البطلان تتولى الهيئة التى أصدرت الحكم أو الأمر تصحيح الخطأ من تلقاء نفسها ، أو بناء على طلب أحد الخصوم وذلك بعد تكليفهم بالحضور . ويقضى بالتصحيح فى غرفة المشورة بعد سماع أقوال الخصوم ويؤشر بالأمر الذى يصدر على هامش الحكم أو الأمر . ويتبع هذا الإجراء فى تصحيح اسم المتهم ولقبه ."}, {"number": "338", "chapter": "الفصل الثالث عشر", "text": "إذا دعا الأمر الى فحص حالة الاضطراب العقلى للمتهم يجوز لقاضى التحقيق أو للقاضى الجزئى كطلب النيابة العامة أو المحكمة المنظورة أمامها الدعوى حسب الأحوال أن يأمر بوضع المتهم إذا كان محبوساً احتياطياً تحت الملاحظة فى إحدى منشآت الصحة النفسية الحكومية المخصصة لذلك لمدة أو لمدد لا يزيد مجموعها على خمسة وأربعين يوماً ، بعد سماع أقوال النيابة العام والمدافع عن المتهم إن كان له مدافع . ويجوز إذا لم يكن المتهم محبوساً احتياطياً أن يأمر بوضعه تحت الملاحظة فى أى مكان آخر . معدلة بالقانون رقم 71 لسنة 2009"}, {"number": "339", "chapter": "الفصل الثالث عشر", "text": "إذا ثبت أن المتهم غير قادر على الدفاع عن نفسه بسبب اضطراب عقلى ، طرأت بعد وقوع الجريمة ، يوقف رفع الدعوى عليه أو محاكمته حتى يعود إليه رشده . ويجوز فى هذه الحالة لقاضى التحقيق أو للقاضى الجزئى كطلب النيابة العامة ، أو المحكمة المنظورة أمامها الدعوى ، إذا كانت الواقعة جناية أو جنحة عقوبتها الحبس إصدار الأمر بحجز المتهم فى أحد المحال المعدة للأمراض العقلية الى أن يتقرر إخلاء سبيله. معدلة بالقانون رقم 71 لسنة 2009"}, {"number": "340", "chapter": "الفصل الثالث عشر", "text": "لا يحول إيقاف الدعوى دون اتخاذ إجراءات التحقيق التى يرى أنها مستعجلة أو لازمة ."}, {"number": "341", "chapter": "الفصل الثالث عشر", "text": "فى الحالة المنصوص عليها فى المادتين 338 ، 339 تخصم المدة التى يقضيها المتهم تحت الملاحظة ، أو فى الحجز من مدة العقوبة التى يحكم بها عليه ."}, {"number": "342", "chapter": "الفصل الثالث عشر", "text": "إذا صدر أمر بأن لا وجه لإقامة الدعوى أو حكم ببراءة المتهم ، وكان ذلك بسبب اضطراب عقلى تأمر الجهة التى أصدرت الأمر أو الحكم إذا كانت الواقعة جناية أو جنحة عقوبتها الحبس بحجز المتهم فى أحد المحال المعدة للأمراض النفسية الى أن تأمر الجهة التى أصدرت الأمر أو الحكم بالإفراج عنه ، وذلك بعد الإطلاع على تقرير مدير المحل وسماع أقوال النيابة العامة ، وإجراء ما تراه لازماً للتثبت من أن المتهم قد عاد الى رشده . معدلة بالقانون رقم 71 لسنة 2009"}, {"number": "365", "chapter": "الفصل الخامس عشر", "text": "يجوز عند الضرورة فى كل جناية أو جنحة تقع على نفس الصغير الذى لم يبلغ خمس عشر سنة ، أن يؤمر بتسليمه الى شخص مؤتمن يتعهد بملاحظته والمحافظة عليه ، أو الى معهد خيرى معترف به من وزارة الشئون الإجتماعية ، حتى يفصل فى الدعوى . ويصدر الأمر بذلك من قاضى التحقيق سواء من تلقاء نفسه أو بناء على طلب النيابة العامة أو من القاضى الجزئى بناء على طلب النيابة العامة أو من المحكمة المنظورة أمامها الدعوى على حسب الأحوال . وإذا وقعت الجناية أو الجنحة على نفس معتوه جاز أن يصدر الأمر بإيداعه مؤقتاً فى مصحة أو مستشفى للأمراض العقلية أو تسليمه الى شخص مؤتمن على حسب الأحوال ."}, {"number": "366", "chapter": "الفصل الأول", "text": "معدلة بالقانون رقم 107 لسنة 1962 ) تشكل محكمة أو أكثر للجنايات فى كل محكمة من محاكم الاستئناف وتؤلف كل منها من ثلاثة من مستشاريها . ومع ذلك تشكل محكمة الجنايات من مستشار فرد من بين رؤساء الدوائر عند النظر فى جناية من الجنايات المنصوص عليها فى المادتين 51 و24. من قانون العقوبات وفى القانون رقم 394 لسنة 1954 فى شأن الأسلحة والذخائر والقوانين المعدلة له . مالم تكن هذه الجناية مرتبطة ارتباطا غير قابل للتجزئة بجناية أخرى غير ماذكر ، فتكون محكمة الجنايات المشكلة من ثلاثة مستشارين هى المختصة بنظر الدعوى برمتها . ولا يجوز للمستشار الفرد أن يقضى بعقوبة الأشغال الشاقة أو السجن مدة تزيد على خمس سنين ، فإذا رأى أن ظروف الدعوى تستوجب القضاء بعقوبة تجاوز هذا الحد ، أو أن الجناية المعروضة عليه ليست من اختصاصه ، أو أنها مرتبطة بجناية أخرى لا يختص بها ، وجب عليه إحالة الدعوى إلى محكمة الجنايات المشار إليها فى الفقرة الأولى التى يتعين عليها فى هذه الأحوال أن تفصل فيها . وإذا رأت محكمة الجنايات المذكورة أن الواقعة كما هى مبينة فى أمر الإحالة . وقبل تحقيقها بالجلسة من الجنايات التى يختص بها المستشار الفرد بنظرها فلها أن تحيلها إليه ."}, {"number": "366", "chapter": "الفصل الأول", "text": "مكرر تختص دائرة أو أ كثر من دوائر محكمة الجنايات – يكون رئيس كل منها بدرجة رئيس محاكم الإستئناف – لنظر الجنايات المنصوص عليها فى الأبواب الأول والثانى مكررا والثالث والرابع من الكتاب الثانى من قانون العقوبات ، والجرائم المرتبطة بتلك الجنايات ، ويفصل فى هذه القضايا على وجه السرعة ."}, {"number": "367", "chapter": "الفصل الأول", "text": "تعين الجمعية العامة لكل محكمة من محاكم الاستئناف فى كل سنة بناء على طلب رئيسها ن من يعهد إليه من مستشاريها قضاة بمحاكم الجنايات . وإذا حصل مانع لأحد المستشارين المعينين لدور من أدوار انعقاد محكمة الجنايات يستبدل به أخر من المستشارين يندبه رئيس محكمة الاستئناف . ويجوز عند الاستعجال أن يجلس مكانه رئيس المحكمة الابتدائية الكائن بالجهة التى تنعقد بها محكمة الجنايات أو وكيلها . ولا يجوز فى هذه الحالة أن يشترك فى الحكم أكثر من واحد من غير المستشارين ."}, {"number": "368", "chapter": "الفصل الأول", "text": "تنعقد محاكم الجنايات فى كل جهة بها محكمة ابتدائية وتشمل دائرة اختصاصها ما تشمله دائرة المحكمة الابتدائية ، ويجوز إذا اقتضت الحال أن تنعقد محكمة الجنايات فى مكان أخر يعينه وزير العدل بناء على طلب رئيس محكمة الاستئناف ."}, {"number": "369", "chapter": "الفصل الأول", "text": "تنعقد محاكم الجنايات فى كل شهر ، مالم يصدر قرار من وزير العدل يخالف ذلك ."}, {"number": "370", "chapter": "الفصل الأول", "text": "يحدد تاريخ افتتاح كل دور من أدوار الانعقاد قبله بشهر على الأقل ، بقرار من وزير العدل ، بناء على طلب رئيس محكمة الاستئناف ، وينشر فى الجريدة الرسمية ."}, {"number": "371", "chapter": "الفصل الأول", "text": "يعد فى كل دور جدول للقضايا التى تنظر فيه ، وتوالى محكمة الجنايات جلساتها إلى أن تنتهى القضايا المقيدة بالجدول ."}, {"number": "372", "chapter": "الفصل الأول", "text": "يجوز لوزير العدل عند الضرورة ن بناء على طلب رئيس محكمة الإستئناف أن يندب أحد رؤساء المحاكم الإبتدائية أو وكلائها للجلوس بمحكمة الجنايات ، مدة دور واحد من أدوار إنعقادها. ويجوز له ندبه لأكثر من دور واحد بموافقة مجلس القضاء الأعلى ."}, {"number": "373", "chapter": "الفصل الأول", "text": "يتبع فى الدعاوى التى ينظرها المستشار الفرد الأحكام والأوضاع المقررة أمام محاكم الجنايات ، ويكون له ما لرئيس محكمة الجنايات من سلطة فى ذلك ."}, {"number": "374", "chapter": "الفصل الثانى", "text": "يكون تكليف المتهم والشهود بالحضور أمام المحكمة قبل الجلسة بثمانية أيام كاملة على الأقل."}, {"number": "375", "chapter": "الفصل الثانى", "text": "فيما عدا حالة العذر أو المانع الذى يثبت صحته يجب على المحامى سواء أكان منتدبا من قبل قاضى التحقيق أوالنيابة العامة ، أو رئيس محكمة الجنايات أو المستشار الفرد ، أم كان موكلا من قبل المتهم أن يدافع عن المتهم فى الجلسة أو يعين من يقوم مقامه ، وإلا حكم عليه من محكمة الجنايات بغرامة لاتتجاوز خمسين جنيها مع عدم الإخلال بالمحاكمة التأديبية إذا إقتضتها الحال . وللمحكمة إعفاؤه من الغرامة إذا ثبت لها أنه كان من المستحيل عليه أن يحضر فى الجلسة بنفسه أو أن ينيب عنه غيره ."}, {"number": "376", "chapter": "الفصل الثانى", "text": "للمحامى المنتدب من قبل قاضى التحقيق أو النيابة العامة أو رئيس محكمة الجنايات أو المستشار الفرد أن يطلب تقدير أتعاب له على الخزانة العامة إذا كان المتهم فقيرا ، وتقدر المحكمة هذه الأتعاب فى حكمها فى الدعوى . ولا يجوز الطعن فى هذا التقدير بأى وجه . ويجوز للخزانة متى زالت حالة فقر المتهم ، أن تستصدر عليه أمر تقد ير بأداء الأتعاب المذكورة"}, {"number": "377", "chapter": "الفصل الثانى", "text": "المحامون المقبولون للمرافعة أمام محاكم الاستئناف أو المحاكم الابتدائية يكونون مختصين ، دون غيرهم ، بالمرافعة أمام محكمة الجنايات ."}, {"number": "378", "chapter": "الفصل الثانى", "text": "على رئيس محكمة الإستئناف عند ووصول ملف القضية أن يحدد الدور الذى يجب أن تنظر فيه القضية وعليه أن يعد جدول قضايا كل دور من أدوار الإنعقاد ويرسل صور ملفات القضايا إلى المستشارين المعينين للدور الذى أحيلت إليه ، ويأمر بإعلان المتهم والشهود باليوم الذى يحدد لنظر القضية . وإذا دعت أٍسباب جدية لتأجيل نظر القضية فيجب أن يكون التأجيل ليوم معين سواء فى ذات الدور أو فى دور مقبل ."}, {"number": "379", "chapter": "الفصل الثانى", "text": "لكل من النيابة العامة والمتهم والمدعى بالحقوق المدنية والمسئول عنها ، أن يعارض فى سماع شهادة الشهود الذين لم يسبق إعلانهم بأسمائهم ."}, {"number": "380", "chapter": "الفصل الثانى", "text": "لمحكمة الجنايات فى جميع الأحوال أن تأمر بالقبض على المتهم وإحضاره ، ولها أن تأمر بحبسه احتياطيا ، وأن تفرج بكفالة أو بغير كفالة عن المتهم المحبوس احتياطيا ."}, {"number": "381", "chapter": "الفصل الثانى", "text": "تتبع أمام محاكم الجنايات جميع الأحكام المقررة فى الجنح والمخالفات ، مالم ينص القانون على خلاف ذلك . ولا يجوز لمحكمة الجنايات أن تصدر حكما بالإعدام إلا بإجماع أراء أعضائها ، ويجب عليها قبل أن تصدر هذا الحكم أن تأخذ رأى مفتى الجمهورية ويجب إرسال أوراق القضية إليه ، فإذا لم يصل رأيه إلى المحكمة خلال العشرة أيام التالية لإرسال الأوراق إليه ، حكمن المحكمة فى الدعوى وفى حالة خلو وظيفة المفتى أو غيابه أو قيام مانع لديه يندب وزير العدل بقرار منه من يقوم مقامه . ولا يجوز الطعن فى أحكام محاكم الجنايات إلا بطريق النقض أو إعادة النظر."}, {"number": "382", "chapter": "الفصل الثانى", "text": "إذا رأت محكمة الجنايات أن الواقعة كما هى مبينة فى أمر الإحالة ، وقبل تحقيقها بالجلسة ، تعد جنحة ، فلها أن تحكم بعدم الاختصاص وتحيلها إلى المحكمة الجزئية . أما إذا لم تر ذلك إلا بعد التحقيق ، تحكم فيها ."}, {"number": "383", "chapter": "الفصل الثانى", "text": "لمحكمة الجنايات ، إذا أحيلت إليها جنحة مرتبطة بجناية ورأت قبل تحقيقها أن لاوجه لهذا الارتباط أن تفصل الجنحة وتعيدها إلى المحكمة الجزئية ."}, {"number": "384", "chapter": "الفصل الثالث", "text": "إذا صدر أمر بإحالة متهم بجناية إلى محكمة الجنايات ولم يحضر يوم الجلسة بعد إعلانه قانونا بأمر الإحالة وورقة التكليف بالحضور يكون للمحكمة أن تحكم فى غيبته ، ويجوز لها أن تؤجل الدعوى وتأمر بإعادة تكليفه بالحضور ."}, {"number": "385", "chapter": "الفصل الثالث", "text": "ملغاة بالقانون رقم 535 لسنة 1953 )"}, {"number": "386", "chapter": "الفصل الثالث", "text": "معدلة بالقانون رقم 353 لسنة 1955 ) يتلى فى الجلسة أمر الإحالة ، ثم الأوراق المثبتة لإعلان المتهم وتبدى النيابة العامة والمدعى بالحقوق المدنية ، إن وجد ، أقوالهما وطلباتهما وتسمع المحكمة الشهود ، إذا رأت ضرورة لذلك ، ثم تفصل فى الدعوى ."}, {"number": "387", "chapter": "الفصل الثالث", "text": "إذا كان المتهم مقيما خارج مصر ، يعلن إليه أمر الإحالة وورقة التكليف بالحضور بمحل إقامته إن كان معلوما ، وذلك قبل الجلسة المحددة لنظر الدعوى بشهر على الأقل ، غير مواعيد المسافة فإذا لم يحضر بعد إعلانه يجوز الحكم فى غيبته ."}, {"number": "388", "chapter": "الفصل الثالث", "text": "لا يجوز لأحد أن يحضر أمام المحكمة ليدافع أو ينوب عن المتهم الغائب ، ومع ذلك يجوز أن يحضر وكيله أو أحد أقاربه أو أصهاره ويبدى عذره فى عدم الحضور ، فإذا رأت المحكمة أن العذر مقبول ، تعين ميعادا لحضور المتهم أمامها ."}, {"number": "389", "chapter": "الفصل الثالث", "text": "ملغاة بالقانون رقم 535 لسنة 1953 )"}, {"number": "390", "chapter": "الفصل الثالث", "text": "كل حكم يصدر بإدانة فى غيبة المتهم يستلزم حتما حرمانه من أن يتصرف فى أمواله أو أن يديرها ، أو أن يرفع أية دعوى باسمه وكل تصرف أو التزام يتعهد به المحكوم عليه يكون باطلا من نفسه . وتعين المحكمة الابتدائية لواقع فى دائرتها أموال المحكوم عليه حارسا لإدارتها بناء على طلب النيابة العامة ، أو كل ذى مصلحة فى ذلك ، وللمحكمة أن تلزم الحارس الذى تنصبه بتقديم كفالة ، ويكون تابعا لها فى جميع ما يتعلق بالحراسة وتقديم الحساب ."}, {"number": "391", "chapter": "الفصل الثالث", "text": "تنتهى الحراسة بصدور حكم حضوري فى الدعوى أو بموت المتهم حقيقة أو حكما وفقا لقانون الأحوال الشخصية ، وبعد إنتهاء الحراسة يقدم الحارس حسابا عن إدارته ."}, {"number": "392", "chapter": "الفصل الثالث", "text": "ينفذ من الحكم الغيابى كل العقوبات التى يمكن تنفيذها ."}, {"number": "393", "chapter": "الفصل الثالث", "text": "يجوز تنفيذ الحكم بالتضمينات من وقت صدوره . ويجب على المدعى بالحقوق المدنية أن يقدم كفالة ، مالم ينص الحكم على خلاف ذلك أو تقرر المحكمة الابتدائية إعفاءه منها . وتنتهي الكفالة بمضى خمس سنوات من صدور الحكم ."}, {"number": "394", "chapter": "الفصل الثالث", "text": "لا يسقط الحكم الصادر غيابيا من محكمة الجنايات فى جناية بمضى المدة . وإنما تسقط العقوبة المحكوم بها ويصبح الحكم نهائيا بسقوطها ."}, {"number": "395", "chapter": "الفصل الثالث", "text": "\" إذا حضر المحكوم عليه فى غيبته أو قبض عليه قبل سقوط العقوبة بمضى المدة ، يحدد رئيس محكمة الإستئناف أقرب جلسة لنظر الدعوى ، ويعرض المقبوض عليه محبوسا بهذه الجلسة ، وللمحكمة أن تأمر بالإفراج عنه أو حبسه إحتياطيا حتى الإنتهاء من نظر الدعوى ، ولايسقط الحكم الغيابى سواء فيما يتعلق بالعقوبة أو التعويضات إلا بحضور من صدر ضده الحكم جلسات المحاكمة ، ولا يجوز للمحكمة فى هذه الحالة التشديد عما قضى به الحكم الغيابى . \" فإذا تخلف المحكوم عليه فى غيبته من حضور الجلسه المحددة لإعادة نظر دعواه ، إعتبر الحكم ضده قائما ، فإذا حضر مرة أخرى قبل سقوط العقوبة بمضى المدة تأمر النيابة بالقبض عليه ويحدد رئيس محكمة الإستئناف أقرب جلسه لإعادة نظر الدعوى ، ويعرض محبوسا بهذه الجلسة ، وللمحكمة أن تأمر بالإفراج عنه أو حبسه إحتياطيا حتى الإنتهاء من نظر الدعوى \" وإذا كان الحكم السابق بالتضمينات قد نفذ تأمر المحكمة برد المبالغ المتحصلة كلها أو بعضها وإذا توفى من حكم عليه فى غيبته يعاد الحكم فى التضمينات فى مواجهة الورثة ."}, {"number": "396", "chapter": "الفصل الثالث", "text": "لايترتب على غياب متهم تأخير الحكم فى الدعوى بالنسبة لغيره من المتهمين معه ."}, {"number": "397", "chapter": "الفصل الثالث", "text": "إذا غاب المتهم بجنحة مقدمة إلى محكمة الجنايات تتبع فى شأنه الإجراءات المعمول بها أمام محكمة الجنح ، ويكون الحكم الصادر فيها قابلا للمعارضة"}, {"number": "398", "chapter": "الباب الأول", "text": "تقبل المعارضة فى الأحكام الغيابية الصادرة فى الجنح المعاقب عليها بعقوبة مقيدة للحرية ، وذلك من المتهم أو من المسئول عن الحقوق المدنية فى خلال العشرة أيام التالية لإعلانه بالحكم الغيابى خلاف ميعاد المسافة القانونية ، ويجوز أن يحصل هذا الإعلان بملخص على نموذج يصدر به قرار من وزير العدل ، وفى جميع الأحوال لايعتد بالإعلان لجهة الإدارة . ومع ذلك إذا كان إ‘لان الحكم لم يحصل لشخص المتهم فإن ميعاد المعارضة بالنسبة إليه فيما يختص بالعقوبة المحكوم بها يبدأ من يوم علمه بحصول الإعلان ، وإلا كانت المعارضة جائزة حتى تسقط الدعوى بمضى المدة . ويجوز أن يكون إعلان الأحك ام الغيابية والأحكام المعتبرة حضورية طيقا للمواد 238 إلى 241 بواسطة أحد رجال السلطة العامة وذلك فى الحالات المنصوص عليها فى الفقرة الثانية من المادة 234"}, {"number": "398", "chapter": "الباب الأول", "text": "تقبل المعارضة فى الأحكام الغيابية الصادرة فى المخالفات والجنح وذلك من المتهم أو من المسئول عن الحقوق المدنية فى ظرف العشرة أيام التالية لإعلانه بالحكم الغيابى خلاف ميعاد المسافة القانونية ، ويجوز أن يحصل هذا الإعلان بملخص على النموذج الذى يقرره وزير العدل . ومع ذلك إذا كان إ‘لان الحكم لم يحصل لشخص المتهم فإن ميعاد المعارضة بالنسبة إليه فيما يختص بالعقوبة المحكوم بها يبدأ من يوم علمه بحصول الإعلان ، وإلا كانت المعارضة جائزة حتى تسقط الدعوى بمضى المدة . ويجوز أن يكون إعلان الأحكام الغيابية والأحكام المعتبرة حضورية طيقا للمواد 238 إلى 241 بواسطة أحد رجال السلطة العامة وذلك فى الحالات المنصوص عليها فى الفقرة الثانية من المادة 234"}, {"number": "399", "chapter": "الباب الأول", "text": "لاتقبل المعارضة من المدعى بالحقوق المدنية"}, {"number": "400", "chapter": "الباب الأول", "text": "تحصل المعارضة بتقرير فى قلم كتاب المحكمة التى أصدرت الحكم يثبت فيه تاريخ الجلسة التى حددت لنظرها ويعتبر ذلك إعلانا لها ولو كان التقرير من وكيل ، ويجب على النيابة العامة تكليف باقى الخصوم فى الدعوى بالحضور وإعلان الشهود للجلسة المذكورة ."}, {"number": "401", "chapter": "الباب الأول", "text": "يترتب على المعارضة إعادة نظر الدعوى بالنسبة إلى المعارض أمام المحكمة التى أصدرت الحكم الغيابي ، ولا يجوز بأية حال أن يضار المعارض بناء على المعارضة المرفوعة منه . . ومع ذلك إذا لم يضر المعارض فى أى من الجلسات المحددة لنظر الدعوى تعتبر المعارضة كأن لم تكن ، ويجوز للمحكمة فى هذه الحالة أن تحكم عليه بغرامة إجرائية لاتجاوز مائة جنيه فى مواد الجنح ولاتجاوز عشرة جنيهات فى مواد المخالفات ، ولها أن تأمر بالنفاذ المؤقت ولو مع حصول الإستئناف بالنسبة للتعويضات المحكوم بها وذلك حسب ماهو مقرر بالمادة ( 467) من هذا القانون . ولايقبل من المعارض بأى حال المعارضة فى الحكم الصادر فى غيبته ، وللمحكمة فى هذه الحالة أن تحكم عليه بغرامة إجرائية لاتقل عن خمسين جنيها ولاتجاوز مائتى جنيه فى مواد الجنح ولاتقل عن عشرة جنيهات ولا تجاوز عشرين جنيها فى مواد المخالفات"}, {"number": "402", "chapter": "الباب الثاني", "text": "لكل من المتهم والنيابة العامة أن يستأنف الأحكام الصادرة فى الدعوى الجنائية من المحكمة الجزئية فى مواد الجنح ، ومع ذلك إذا كان الحكم صادرا فى إحد ى الجنح المعاقب عليها بغرامة لاتجاوز ثلاثمائة جنيه فضلا عن الرد والمصاريف فلا يجوز استئنافه إلا لمخالفة القانون أو خطأ فى تطبيقه أو فى تأويله أو لوقوع بطلان فى الحكم أو فى الإجراءات أثر فى الحكم . أما فى الأحكام الصادرة مناه فى مواد المخالفات فيجوز استئنافها : ( 1 ) من المتهم إذا حكم عليه بغير الغرامة والمصاريف . ( 2 ) من النيابة العامة إذا طلبت الحكم بغير الغرامة والمصاريف وحكم ببراءة المتهم أو لم يحكم بما طلبته . وفيما عدا هاتين الحالتين لا يجوز رفع الاستئناف من المتهم أو من النيابة العامة إلا لمخالفة القانون أو لخطأ فى تطبيقه أو تأويله ولوقوع بطلان فى الحكم أو فى الإجراءات أثر فى الحكم ."}, {"number": "403", "chapter": "الباب الثاني", "text": "يجوز إستئناف الأحكام الصادرة فى الدعوى المدنية من المحكمة الجزئية ة فى المخالفات والجنح من المدعى بالحقوق المدنية ومن المسئول عنها أو المتهم فيما يختص بالحقوق المدنية وحدها ، إذا كانت التعويضات تزيد على النصاب الذى يحكم فيه القاضى الجزئى نهائيا ."}, {"number": "404", "chapter": "الباب الثاني", "text": "يجوز إستئناف الحكم الصادر فى الجرائم المرتبطة بعضها ببعض إرتباطا لايقبل التجزئة ، فى حكم المادة 32 من قانون العقوبات ، ولولم يكن الإستئناف جائزا للمستأنف إلا بالنسبة لبعض هذه الجرائم فقط ."}, {"number": "405", "chapter": "الباب الثاني", "text": "لا يجوز قبل أن يفصل فى موضوع الدعوى ، إستئناف الأحكام التحضيرية والتمهيدية الصادرة فى مسائل فرعية . ويترتب حتما على إستئناف الحكم الصادر فى الموضوع إستئناف هذه الأحكام . ومع ذلك فجميع الأحكام الصادرة بعدم الإختصاص يجوز إستئنافها ، كما يجوز إستئناف الأحكام الصادرة بالإختصاص إذا لم يكن للمحكمة ولاية الحكم فىالدعوى ."}, {"number": "406", "chapter": "الباب الثاني", "text": "يحصل الإستئناف بتقرير فى قلم كتاب المحكمة التى أًصدرت الحكم فى ظرف عشرة أيام من تاريخ النطق بالحكم الحضورى أو إعلان الحكم الغيابى ، أو من تاريخ الحكم الصادر فىالمعارضة فى الحالات التى يجوز فيها ذلك . وللنائب العام أن يستأنف فى ميعاد ثلاثين يوما من وقت صدور الحكم وله أن يقرر بالإستئناف فى قلم كتاب المحكمة المختصة بنظر الاستئناف"}, {"number": "407", "chapter": "الباب الثاني", "text": "الأحكام الصادرة فى غيبة المتهم والمعتبره حضوريا طبقا للمواد 238 إلى 241، يبدأ ميعاد استئنافها بالنسبة للمتهم من تاريخ إعلانه بها ."}, {"number": "408", "chapter": "الباب الثاني", "text": "يحدد قلم الكتاب للمستأنف فى تقرير الإستئناف تاريخ الجلسة التى حددت لنظره ويعتبر ذلك إعلانا لها ولوكان التقرير من الوكيل ، ولايكون هذا التاريخ قبل مضى ثلاثة أيام كاملة ، وتكلف النيابة العامة الخصوم الأخرين بالحضور ."}, {"number": "409", "chapter": "الباب الثاني", "text": "إذا إستأنف أحد الخصوم فى مدة العشرة أيام المقررة ، يمتد ميعاد الإستئناف لمن له حق الإستئناف من باقى الخصوم خمسة أيام من تاريخ إنتهاء العشرة أيام المذكورة ."}, {"number": "410", "chapter": "الباب الثاني", "text": "يرفع الإستئناف للمحكمة الإبتدائية الكائنة فى دائرتها المحكمة التى أصدرت الحكم ،ويقدم فى ثلاثين يوما على الأكثر إلى الدائرة المختصة بنظر الاستئناف فى مواد المخالفات والجنح . وإذا كان المتهم محبوسا ، وجب على النيابة العامة نقله فى الوقت المناسب إلى السجن بالجهة الموجودة بها المحكمة الإبتدائية ، وينظر الإستئناف على وجه السرعة ."}, {"number": "411", "chapter": "الباب الثاني", "text": "يضع أحد أعضاء الدائرة المنوط بها الحكم فى الإستئناف تقريرا موقعا عليه منه ، ويجب أن يشمل هذا التقرير ملخص وقائع الدعوى وظروفها وأدلة الثبوت والنفى وجميع المسائل الفرعية التى رفعت والإجراءات التى تمت . وبعد تلاوة هذا التقرير وقبل إبداء رأى فى الدعوى من واضع التقرير أو بقية الأعضاء ، تسمع أقوال المستأنف والأوجه المستند إليه فى استئنافه . ثم يتكلم بعد ذلك باقى الخصوم ويكون المتهم أخر من يتكلم ثم تصدر المحكمة حكمها بعد إطلاعها على الأوراق ."}, {"number": "412", "chapter": "الباب الثاني", "text": "يسقط الاستئناف المرفوع من المحكوم عليه بعقوبة مقيدة للحرية واجبة النفاذ إذا لم يتقدم للتنفيذ قبل الجلسة التى تنظر فيها الد عوى . ومع ذلك فللمحكمة عند نظر الإستئناف أن تأمر بوقف تنفيذ العقوبة مؤقتا أو الإفراج عن المحكوم عليه بكفالة أو بغيرها ، وذلك إلى حين الفصل فى الإٍِستئناف ."}, {"number": "413", "chapter": "الباب الثاني", "text": "تسمع المحكمة الإستئنافية بنفسها ، أو بواسطة أحد القضاة تندبه لذلك الشهود الذين كان يجب سماعهم أمام محكمة أول درجة وتستوفى كل نقص أخر فى إجراءات التحقيق . ويسوغ لها فى كل الأحوال أن تأمر بما ترى لزومه من إستيفاء تحقيق أو سماع شهود . ولا يجوز تكليف أى شاهد بالحضور إلا إذا أمرت المحكمة بذلك ."}, {"number": "414", "chapter": "الباب الثاني", "text": "إذا تبين للمحكمة أن الواقعة جناية أو أنها جنحة من الجنح التى تقع بواسطة الصحف أو غيرها من طرق النشر على غير الأفراد ، تحكم بعدم الاختصاص وتحيل الدعوى إلى النيابة العامة لاتخاذ ما يلزم فيها ."}, {"number": "415", "chapter": "الباب الثاني", "text": "ملغاة )"}, {"number": "416", "chapter": "الباب الثاني", "text": "إذا ألغى الحكم الصادر بالتعويضات ، وكان قد نفذ بها تنفيذا مؤقتا ترد بناء على حكم الإلغاء ."}, {"number": "417", "chapter": "الباب الثاني", "text": "إذا كان الاستئناف مرفوعا من النيابة العامة فللمحكمة أن تؤيد الحكم أو تلغيه أو تعدله سواء ضد المتهم أو لمصلحته . ولا يجوز تشديد العقوبة المحكوم بها ولا إلغاء الحكم الصادر بالبراءة إلا بإجماع آراء قضاة المحكمة . أما إذا كان الإٍستئناف مرفوعا من غير النيابة العامة فليس للمحكمة إلا أن تؤيد الحكم أو تعدله لمصلحة رافع الإسئتناف ويجوز لها إذا قضت بسقوط الإستئناف أو بعدم قبوله أو بعدم جوازه أو برفضه – أن تحكم على رافعه بغرامة لاتتجاوز خمسة جنيهات"}, {"number": "418", "chapter": "الباب الثاني", "text": "يتبع فى الأحكام الغيابية والمعارضة فيها أمام المحكمة الاستئنافية ماهو مقرر أمام محكمة أول درجة."}, {"number": "419", "chapter": "الباب الثاني", "text": "إذا حكمت محكمة أول درجة فى الموضوع ، ورأت المحكمة الإٍستئنافية أن هناك بطلانا فى الإجراءات أو فى الحكم ، أن تصحح البطلان وتحكم فى الدعوى . أما إذا حكمت بعدم الاختصاص أو بقبول دفع فرعى يترتب عليه منع السير فى الدعوى ، وحكمت المحكمة الاستئنافية بإلغاء الحكم وباختصاص المحكمة أو برفض الدفع الفرعى وبنظر الدعوى يجب عليها أن تعيد القضية لمحكمة أول درجة للفصل فى موضوعها ."}, {"number": "441", "chapter": "الباب الرابع", "text": "يجوز طلب إعادة النزر فى الأحكام النهائية الصادرة بالعقوبة فى مواد الجنايات والجنح فى الأحوال الأتية : 1 - إذا حكم على المتهم فى جريمة قتل ، ثم وجد المدعى قتله حيا 2 -إذا صدرحكم على شخص من أجل واقعة ، ثم صدر حكم على شخص أخر من أجل الواقعة عينها ، وكان بين الحكمين تناقض بحيث يستنتج منه براءة أحد المحكوم عليهما. 3 -إذا حكم على أحد الشهود أو الخبراء بالعقوبة لشهادة الزور ، وفقا لأحكام الباب السادس من الكتاب الثالث من قانون العقوبات ، أو إذا حكم بتزوير ورقة قدمت أثناء نظر الدعوى ، وكان للشهادة أو تقرير الخبير أو الورقة تأثير فى الحكم . 4 - إذا كان الحكم مبنيا على حكم صادر من محكمة مدنية أومن إحدى محاكم الأحوال الشخصية وألغى هذا الحكم 5 - إذا حدثت أو ظهرت بعد الحكم وقائع ، أو إذا قدمت أوراق لم تكن معلومة وقت المحاكمة ، وكان من شأن هذه الوقائع أو الأوراق ثبوت براءة المحكوم عليه ."}, {"number": "442", "chapter": "الباب الرابع", "text": "فى الأحوال الأربع الأولى من المادة السابقة ، يكون لكل من النائب العام والمحكوم عليه أو من يمثله قانونا إذا كان عديم الأهلية أو مفقودا أو لأقاربه أو زوجه من بعد موته حق طلب إعادة النظر . وإذا كان الطالب غير النيابة العامة فعليه تقديم الطلب إلى النائب العام بعريضة يبين فيها الحكم المطلوب إعادة النظر فيه ، والوجه الذى يستند عليه ، ويشفعه بالمستندات المؤيدة له . ويرفع النائب العام الطلب سواء كان مقدما منه أو من غيره مع التحقيقات التى يكون قد رأى إجراءها إلى محكمة النقض بتقرير يبين فيه رأيه وأسباب التى يستند عليها . ويجب أن يرفع الطلب إلى المحكمة فى الثلاثة أشهر التالية لتقديمه ."}, {"number": "443", "chapter": "الباب الرابع", "text": "فى الحالة الخامسة من المادة 441 يكون حق طلب إعادة النظر للنائب العام وحده سواء من تلقاء نفسه أو بناء على طلب أصحاب الشأن ، وإذا رأى له محلا يرفعه مع التحقيقات التى يكون قد رأى لزومها إلى لجنة مشكلة من أحد مستشارى محكمة النقض وإثنين من مستشارى محكمة الاستئناف تعين كلا منهم الجمعية العامة بالمحكمة التابع لها . ويجب أن يبين فى الطلب الواقعة أو الورقة التى يستند عليها . وتفصل اللجنة فى الطلب بعد الإطلاع على الأوراق واستيفاء ما تراه من التحقيق وتأمر بإحالته إلى محكمة النقض إذا رأت قبوله . ولا يقبل الطعن بأى وجه فى القرار الصادر من النائب العام أو فى الأمر الصادر من اللجنة المشار إليها بقبول الطلب أو عدم قبوله"}, {"number": "444", "chapter": "الباب الرابع", "text": "لايقبل النائب العام طلب إعادة النظر من المتهم أو ممن يحل محله فى الأحوال الأربع الأولى من المادة 441 إلا إذا أ,دع الطالب خزانة المحكمة مبلغ خمسة جنيهات كفالة ، تخصص لوفاء الغرامة المنصوص عليها بالمادة 449 . مالم يكن قد أعفى من إيداعه بقرار من لجنة المساعدة القضائية بمحكمة النقض ."}, {"number": "445", "chapter": "الباب الرابع", "text": "تعلن النيابة العامة الخصوم للجلسة التى تحدد لنظر الطلب أمام محكمة النقض قبل انعقادها بثلاثة أيام كاملة على الأٌقل ."}, {"number": "446", "chapter": "الباب الرابع", "text": "تفصل محكمة النقض فى الطلب بعد سماع أقوال النيابة العامة والخصوم وبعد إجراء ما تراه لازما من التحقيق بنفسها أو بواسطة من تندبه لذلك ، إلا إذا رأت قبول الطلب تحكم بإلغاء الحكم وتقضى ببراءة المتهم إذا كانت البراءة ظاهرة ، وإلا فتحيل الدعوى إلى المحكمة التى أصدرت الحكم مشكلة من قضاة آخرين للفصل فى موضوعها مالم ترى إجراء ذلك بنفسها . ومع ذلك إذا كان من غير الممكن إعادة المحاكمة ، كما فى حالة وفاة المحكوم عليه أو عتهه أو سقوط الدعوى الجنائية بمضى المدة ، تنظر محكمة النقض موضوع الدعوى ، ولا تلغى من الحكم إلا ما يظهر لها خطؤه ."}, {"number": "447", "chapter": "الباب الرابع", "text": "إذا توفى المحكوم عليه ولم يكن الطلب مقدما من أحد الأقارب أو الزوج تنظر المحكمة الدعوى فى مواجهة من تعينه للدفاع عن ذكراه ، ويكون بقدر الإمكان من الأقارب وفى هذه الحالة تحكم عند الاقتضاء بمحو ما يمس هذه الذكرى ."}, {"number": "448", "chapter": "الباب الرابع", "text": "لا يترتب على طلب إعادة النظر إيقاف تنفيذ الحكم إلا إذا كان صادرا بالإعدام ."}, {"number": "449", "chapter": "الباب الرابع", "text": "فى الأحوال الأربع الأولى من المادة 441 يحكم على طالب إعادة النظر إذا كان غير النائب العام ، بغرامة لاتزيد على خمسة جنيهات إذا لم يقبل طلبه ."}, {"number": "450", "chapter": "الباب الرابع", "text": "كل حكم صادر بالبراءة بناء على إعادة النظر يجب نشره على نفقة الحكومة فى الجريدة الرسمية بناء على طلب النيابة العامة ، وفى جريدتين يعينهما صاحب الشأن ."}, {"number": "451", "chapter": "الباب الرابع", "text": "يترتب على إلغاء الحكم المطعون فيه سقوط الحكم بالتعويضات ، ووجوب رد ما نفذ منها بدون إخلال بقواعد سقوط الحق بمضى المدة ."}, {"number": "452", "chapter": "الباب الرابع", "text": "إذا رفض طلب إعادة النظر ، فلايجوز تجديده بناء على ذات الوقائع التى بنى عليها"}, {"number": "453", "chapter": "الباب الرابع", "text": "الأحكام التى تصدر فى موضوع الدعوى بناء على طلب إعادة النظر من غير محكمة النقض يجوز الطعن فيها بجميع الطرق المقررة فى القانون . ولا يجوز أن يقضى على المتهم بأِشد من العقوبة السابق الحكم بها عليه"}, {"number": "454", "chapter": "الباب الخامس", "text": "تنقضى الدعوى الجنائية بالنسبة للمتهم المرفوعة عليه والوقائع المسندة فيها إليه ، بصدور حكم نهائى فيها بالبراءة أ, الإدانة . وإذا صدر حكم فى موضوع الدعوى الجنائية ، فلا يجوز إعادة نظرها إلا بالطعن فى هذا الحكم بالطرق المقررة فى القانون ."}, {"number": "455", "chapter": "الباب الخامس", "text": "لا يجوز الرجوع إلى الدعوى الجنائية بعد الحكم فيها نهائيا ، بناء على ظهور أدلة جديدة أو ظروف جديدة أو بناء على تغيير الوصف القانونى للجريمة ."}, {"number": "456", "chapter": "الباب الخامس", "text": "يكون للحكم الجنائي الصادر من المحكمة الجنائية فى موضوع الدعوى الجنائية بالبراءة أو بالإدانة قوة الشىء المحكوم به أمام المحاكم المدنية فى الدعاوى التى لم يكن قد فصل فيها نهائيا فيما بتعلق بوقوع الجريمة وبوصفها القانونى ونسبتها إلى فاعلها ويكون للحكم بالبراءة هذه القوة سواء بنى على إنتفاء التهمة أو على عدم كفاية الأدلة ، ولاتكون له هذه القوة إذا كان مبنيا على أن الفعل لا يعاقب عليه القانون ."}, {"number": "457", "chapter": "الباب الخامس", "text": "لاتكون للأحكام الصادرة من المحاكم قوة الشىء المحكوم به أمام المحاكم الجنائية فيما يتعلق بوقوع الجريمة ونسبتها إلى فاعلها ."}, {"number": "458", "chapter": "الباب الخامس", "text": "تكون للأحكام الصادرة من محاكم الأحوال الشخصية فى حدود اختصاصها قوة الشيء المحكوم به أمام المحاكم الجنائية فى المسائل التى يتوقف عليها الفصل فى الدعوى الجنائية."}, {"number": "459", "chapter": "الباب الأول", "text": "لا يجوز توقيع العقوبات المقررة بالقانون لأية جريمة إلا بمقتضى حكم صادر من محكمة مختصة بذلك ."}, {"number": "460", "chapter": "الباب الأول", "text": "لاتنفذ الأحكام الصادر من المحاكم الجنائية إلا متى صارت نهائية ، مالم يكن فى القانون نص على خلاف ذلك ."}, {"number": "461", "chapter": "الباب الأول", "text": "يكون تنفيذ الأحكام الصادرة فى الدعوى الجنائية يناء على طلب النسيابة العامة وفقا لماهو مقرر فى القانون . والأحكام الصادرة فى الدعوى المدنية يكونه تنفيذها بناء على طلب المدعى بالحقوق المدنية وفقا لما هو مقرر بقانون المرافعات فى المواد المدنية والتجارية ."}, {"number": "462", "chapter": "الباب الأول", "text": "على النيابة العامة أن تبادر إلى تنفيذ الأحكام الواجبة التنفيذ الصادرة فى الدعوى الجنائية . ولها عند اللزوم أن تسعتين بالقوة العسكرية مباشرة ."}, {"number": "463", "chapter": "الباب الأول", "text": "الأحكام الصادرة بالغرامة والمصاريف تكون واجبة التنفيذ فورا ، ولو مع حصول إستئنافها ، وكذلك الأحكام الصادرة بالحبس فى سرقة أو على متهم عائد أو ليس له محل إقامة ثابت بمصر ، وكذلك الحال فى الأحوال الأخرى إذا كان الحكم صادرا بالحبس ، إلا إذا قدم المتهم كفالة بأنه إذا إستأنفه يحضر فى الجلسة ولايفر من تنفيذ الحكم الذى يصدر ، وكل حكم يصدر بعقوبة الحبس فى هذه الأحوال يعين فيه المبلغ الذى يجب تقديم الكفالة به . وإذا كان المتهم محبوسا حبسا إحتياطيا يجوز للمحكمة أن تأمر بتنفيذ الحكم تنفيذا مؤقتا . وللمحكمة عند الحكم بالتعويضات للمدعى بالحقوق المدنية أن تأمر بالتنفيذ المؤقت ولو مع حصول الإستئناف على حسب ماهو المقرر بالمادة 467."}, {"number": "464", "chapter": "الباب الأول", "text": "تنفذ أيضا العقوبات التبعية المقيدة للحرية المحكوم بها ، مع عقوبة الحبس إذا نفذت عقوبة الحبس طبقا للمادة السابقة ."}, {"number": "465", "chapter": "الباب الأول", "text": "يفرج فى الحال عن المتهم المحبوس إحتياطيا ، إذا كان الحكم صادرا بالبراءة أو بعقوبة أخرى لا يقتضى تنفيذها الحبس أو إذا أمر فى الحكم بوقف تنفيذ العقوبة أو إذا كان المتهم قد قضى فى الحبس الاحتياطي مدة العقوبة المحكوم بها ."}, {"number": "466", "chapter": "الباب الأول", "text": "فى غير الأحوال المتقدمة يوقف التنفيذ أثناء الميعاد المقرر للإستئناف بالمادة 4.6 وأثناء الاستئناف الذى يرفع فى المدة المذكورة ."}, {"number": "467", "chapter": "الباب الأول", "text": "يجوز تنفيذ الحكم الغيابى بالعقوبة إذا لم يعارض فيه المحكوم عليه فى الميعاد المبين بالفقرة الأولى من المادة 398 . وللمحكمة عند الحكم بالتضمينات للمدعى بالحقوق المدنية أن تأمر التنفيذ المؤقت مع تقديم كفالة ولو معى حصول المعارضة أو الاستئناف بالنسبة لكل المبلغ المحكوم به أو بعضه . ولها أن تعفى المحكوم له من الكفالة ."}, {"number": "468", "chapter": "الباب الأول", "text": "للمحكمة عند الحكم غيابيا بالحبس مدة شهر فأكثر إذا لم يكن للمتهم محل إقامة معين بمصر ، أو إذا كان صادرا ضده أمر بالحبس الاحتياطي ، أن تأمر بناء على طلب النيابة العامة بالقبض عليه وحبسه . ويحبس المتهم عند القبض عليه تنفيذا لهذا الأمر حتى يحكم فى المعارضة التى يرفعها أو ينقضى الميعاد المقرر لها ، ولا يجوز بأية حال أن يبقى فى الحبس مدة تزيد على المدة المحكوم بها ، وذلك كله مالم تر المحكمة المرفوعة إليها المعارضة الإفراج عنه قبل الفصل فيها ."}, {"number": "469", "chapter": "الباب الأول", "text": "لا يترتب على الطعن بطريق النقض إيقاف التنفيذ آلا إذا كان الحكم صادرا بالإعدام ، أو كان صادرا بالاختصاص فى الحالة المبينة بالفقرة الأخيرة من المادة 421 ."}, {"number": "470", "chapter": "الباب الثانى", "text": "متى صار الحكمة بالإعدام نهائيا ، وجب رفع أوراق الدعوى فورا إلى رئيس الجمهورية بواسطة وزير العدل . وينفذ الحكم إذا لم يصدر الأمر بالعفو أو بإبدال العقوبة فى ظرف أربعة عشر يوما ."}, {"number": "471", "chapter": "الباب الثانى", "text": "يودع المحكوم عليه بالإعدام فى السجن بناء على أمر تصدره النيابة العامة على النموذج الذى يقرره وزير العدل إلى أن ينفذ فيه الحكم ."}, {"number": "472", "chapter": "الباب الثانى", "text": "لأقارب المحكوم عليه بالإعدام أن يقابلوه فى اليوم الذى يعين لتنفيذ الحكم ، على أن يكون ذلك بعيدا عن محل التنفيذ . وإذا كانت ديانة المحكوم عليه نفرض عليه الاعتراف أو غيره من الفروض الدينية قبل الموت ، وجب إجراء التسهيلات اللازمة لتمكين أحد رجال الدين من مقابلته ."}, {"number": "473", "chapter": "الباب الثانى", "text": "تنفذ عقوبة الإعدام داخل السجن ، أو فى مكان أخر مستور ، بناء على طلب من النائب العام يبين فيه استيفاء الإجراءات المنصوص عليها فى المادة 470 ."}, {"number": "474", "chapter": "الباب الثانى", "text": "يجب أن يكون تنفيذ عقوبة الإعدام بحضور أحد وكلاء النائب العام ومأمور السجن وطبيب السجن أو طبيب أخر تندبه النيابة العامة ولا يجوز لغير من ذكر أن يحضروا التنفيذ إلا بإذن خاص من النيابة العامة ويجب دائما أن يؤذن للمدافع عن المحكوم عليه بالحضور . ويجب أ، يتلى من الحكم الصادر بالإعدام منطوقه والتهمة المحكوم من أجلها على المحكوم عليه ، وذلك فى مكان التنفيذ بمسمع من الحاضرين وإذا رغب المحكوم عليه فى أداء أقواله ، حرر وكيل النائب محضرا بها . وعند تمام التنفيذ يحرر وكيل النائب العام محضرا بذلك ، ويثبت فيه شهادة الطبيب بالوفاة وساعة حصولها ."}, {"number": "475", "chapter": "الباب الثانى", "text": "لا يجوز تنفيذ عقوبة الإعدام فى أيام الأعياد الرسمية أو الأعياد الخاصة بديانة المحكوم عليه"}, {"number": "476", "chapter": "الباب الثانى", "text": "يوقف تنفيذ عقوبة الإعدام على الحبلى وإلى ما بعد شهرين من وضعها ."}, {"number": "477", "chapter": "الباب الثانى", "text": "ندفن الحكومة على نفقتها جثة من يحكم عليه بالإعدام مالم يكن له أقارب يطلبون القيام بذلك . ويجب أن يكون الدفن بغير احتفال ما ."}, {"number": "478", "chapter": "الباب الثالث", "text": "تنفذ الأحكام الصادرة بالعقوبات المقيدة للحرية فى السجون المعدة لذلك بمقتضى أمر يصدر من النيابة العامة على النموذج الذى يقرره وزير العدل ."}, {"number": "479", "chapter": "الباب الثالث", "text": "لكل محكوم عليه بالحبس البسيط لمدة لاتتجاوز ثلاثة أشهر أن يطلب بدلا من تنفيذ عقوبة الحبس عليه تشغيله خارج السجن ، وفقا لماهو مقرر بالمواد 520 ومابعدها ، وذلك مالم ينهص الحكم على حرمانه من هذا الخيار ."}, {"number": "480", "chapter": "الباب الثالث", "text": "يحسب اليوم الذى يبدأ فيه التنفيذ من مدة العقوبة ويفرج عن المحكوم عليه فى اليوم التالى ليوم انتهاء العقوبة فى الوقت المحدد للإفراج عن المسجونين ."}, {"number": "481", "chapter": "الباب الثالث", "text": "إذا كانت مدة عقوبة الحبس المحكوم بها على المتهم أربعا وعشرين ساعة ينتهى تنفيذها فى اليوم التالى للقبض عليه فى الوقت المحدد للإفراج عن المسجونين ."}, {"number": "482", "chapter": "الباب الثالث", "text": "تبتدىء مدة العقوبة المقيدة للحرية من يوم القبض علىالمحكوم عليه بناء على الحكم الواجب التنفيذ مع مراعاة إنقاصها بمقدار مدة الحبس الإحتياطى ومدة القبض ."}, {"number": "483", "chapter": "الباب الثالث", "text": "إذا حكم ببراءة المتهم من الجريمة التى حبس إحتياطيا من أجلها وجب خصم مدة الحبس من المدة المحكوم بها فى أية جريمة يكون قد ارتكبها أو حقق فيها أثناء الحبس الإحتياطى."}, {"number": "484", "chapter": "الباب الثالث", "text": "يكون إستنزال مدةو الحبس الإحتياطى عند تعدد العقوبات المقيدة للحرية المحكوم بها على المتهم من العقوبة الأخف أولا ."}, {"number": "485", "chapter": "الباب الثالث", "text": "إذا كانت المحكوم عليها بعقوبة مقيدة للحرية حبلى فى الشهر السادس من الحمل جاز تأجيل التنفيذ عليها حتى تضع حملها وتمضى مدة شهرين على الوضع . وإذا رؤى التنفيذ على المحكوم عليها ، أو ظهر فى أثناء التنفيذ أنها حبلى وجبت معاملتها فى السجن معاملة المحبوسين إحتياطيا حنى تمضى المدة المقررة بالفقرة السابقة . اامادة- 486 - إذا كان المحكوم عليه بعقوبة مقيدة للحرية مصابا بمرض يهدد بذاته أو بسبب التنفيذ حياته بالخطر ن جاز تأجيل تنفيذ العقوبة عليه ."}, {"number": "487", "chapter": "الباب الثالث", "text": "إذا أصيب المحكوم عليه بعقوبة مقيدة للحرية بإضطراب عقلى ، وجب تأجيل تنفيذ العقوبة حتى يبرأ ، ويجوز للنيابة العامة أن تأمر بوضعه فى أحد المحال المعدة للأمراض النفسية ، وفى هذه الحالة تستنزل المدة التى يقضيها فى هذا المحل من مدة العقوبة المحكوم بها ."}, {"number": "488", "chapter": "الباب الثالث", "text": "إذا كان محكوما على الرجل وزوجته بالحبس مدة لاتزيد على سنة ولو عن جرائم مختلفة ولم يكونا مسجونين من قبل ، جاز تأجيل تنفيذ العقوبات على أحدهما حتى يفرج عن الأخر وذلك إذا كانا يكفلان صغير لم يتجاوز خمسة عشر سنة كاملة وكان لهما محل إقامة معروف بمصر ."}, {"number": "489", "chapter": "الباب الثالث", "text": "للنيابة العامة فى الأحوال التى يجوز فيها تأجيل تنفيذ العقوبة على المحكوم عليه أن تطلب منه تقديم كفالة بأنه لايفر من التنفيذ عند زوال سبب الـتأجيل ، ويقدر مبلغ الكفالة فى الأمر الصادر بالتأجيل . ولها أيضا أن تشترط لتأجيل التنفيذ ماتراه من الإحتياطيات الكفيلة بمنع المحكوم عليه من الهرب ."}, {"number": "490", "chapter": "الباب الثالث", "text": "لا يجوز فى غير الأحوال المبينة فى القانون إخلاء سبيل المسجون المحكوم عليه قبل أن يستوفى مدة العقوبة ."}, {"number": "505", "chapter": "الباب الخامس", "text": "عندتسوية المبالغ المستحقة للحكومة عن الغرامة وما يجب رده والتعويضات والمصاريف ، يجب على النيابة العامة قبل التنفيذ بها إعلان المحكوم عليه بمقدار هذه المبالغ ن مالم تكن مقدرة فى الحكم ."}, {"number": "506", "chapter": "الباب الخامس", "text": "يجوز تحصيل المبالغ المستحقة للحكومة بالطرق المقررة فى قانون المرافعات فى المواد المدنية والتجارية أو بالطرق الإدارية المقررة لتحصيل الأموال الأميرية ."}, {"number": "507", "chapter": "الباب الخامس", "text": "إذا لم يدفع المتهم المبالغ المستحقة للحكومة تصدر النيابة العامة أمرا بالإكراه البدنى وفقا للأحكام المقررة بالمواد 511 وما بعدها ."}, {"number": "508", "chapter": "الباب الخامس", "text": "إذا حكم بالغرامة وما يجب رده والتعويضات والمصاريف معا وكانت أموال المحكوم عليه لاتفى بذلك كله ، وجب توزيع ما يتحصل منها بين ذوى الحقوق على حسب الترتيب الأتى : أولا : المصاريف المستحقة للحكومة ثانيا : المبالغ المستحقة للمدعى المدنى ثالثا : الغرامة وما تستحقه الحكومة من الرد والتعويض ."}, {"number": "509", "chapter": "الباب الخامس", "text": "إذا حبس شخص احتياطيا ، ولم يحكم عليه إلا بالغرامة وجب أ، ينقص منها عند التنفيذ خمسة جنيهات عن كل يوم من أيام الحبس المذكورة ، وإذا حكم عليه بالحبس والغرامة معا وكانت المدة التى قضاها فى الحبس الإحتياطى تزيد على مدة الحبس المحكوم به ، وجب أن ينقص من الغرامة المبلغ المذكور عن كل يوم من أيام الزيادة المذكورة ."}, {"number": "510", "chapter": "الباب الخامس", "text": "لقاضى المحكمة الجزئية فى الجهة التى يجرى التنفيذ فيها أن يمنح المتهم فى الأحوال الإستئنائية بناء على طلبه وبعد أخذ رأى النيابة العامة أجلا لدفع المبالغ المستحق للحكومة ، أو أن يأذن له بدفعها على أقساط ، بشرط ألا تزيد المدة على تسعة أِشهر ولا يجوز الطعن فى الأمر الذى يصدر بقبول الطلب أو رفضه . وإذا تأخر المتهم عن دفع قسط حلت باقى الأقساط ، ويجوز للقاضى الرجوع فى الأمر الصادر منه إذا وجد ما يدعو لذلك ."}, {"number": "511", "chapter": "الباب السادس", "text": "يجوز الإكراه البدنى لتحصيل المبالغ الناشئة عن الجريمة المقضي بها للحكومة ضد مرتكب الجريمة ، ويكون هذا الإكراه بالحبس البسيط وتقدر مدته باعتبار يوم واحد عن كل خمسة جنيهات أو أقل . ومع ذلك ، ففى مواد المخالفات لاتزيد مدة الإكراه على سبعة أيام للغرامة ، وعلى سبعة أيام للمصاريف وما يجب رده والتعويضات . وفى مواد الجنح والجنايات لاتزيد مدة الإكراه البدنى على ثلاثة أشهر للغرامة وثلاثة أشهر للمصاريف وما يجب رده والتعويضات ."}, {"number": "512", "chapter": "الباب السادس", "text": "لا يجوز التنفيذ بطريق الإكراه البدنى على المحكوم عليهم الذين لم يبلغوا من العمر خمس عشرة سنة كاملة وقت ارتكاب الجريمة ولاعلى المحكوم عليهم بعقوبة الحبس مع وقف التنفيذ ."}, {"number": "513", "chapter": "الباب السادس", "text": "تسرى أحكام المواد 485- 488 فيما يتعلق بالتنفيذ بطريق الإكراه البدنى ."}, {"number": "514", "chapter": "الباب السادس", "text": "إذا تعددت الأحكام ، وكانت صادرة فى مخالفات أو فى جنح ، أو فى جنايات ، يكون التنفيذ بإعتبار مجموع المبالغ المحكوم بها وفى هذه الحالة لا يجوز أن تزيد مدة الإكراه على ضعف الحد الأقصى فى الجنح والجنايات ولا على واحد وعشرين يوما فى المخالفات . أما إذا كانت الجرائم مختلفة النوع . يراعى الحد الأقصى المقرر لكل منها ، ولا يجوز بأية حال أن تزيد مدة الإكراه على ستة أشهر للغرامات ، وستة أشهر للمصاريف ومايجب رده والتعويضات ."}, {"number": "515", "chapter": "الباب السادس", "text": "إذا كانت الجرائم المحكوم فيها مختلفة يستنزل المبالغ المدفوعة أو التى تحصلت بطريق التنفيذ على ممتلكات المحكوم عليه أولا من المبالغ المحكوم بها فى الجنايات ثم فى الجنح ، ثم فى المخالفات ."}, {"number": "516", "chapter": "الباب السادس", "text": "يكون تنفيذ الإكراه البدنى بأمر يصدر من النيابة العامة على النموذج الذى يقرره وزير العدل ويشرع فيه فى أى وقت كان بعد إعلان المتهم طبقا للمادة 5 . 5 وبعد أن يكون قد أمضى جميع مدد العقوبات المقيدة للحرية المحكوم بها ."}, {"number": "517", "chapter": "الباب السادس", "text": "ينتهى الإكراه البدنى متى صار المبلغ الموازى للمدة التى أمضاها المحكوم عليه فى الإكراه محسوبا على مقتضى المواد السابقة مساويا للمبلغ المطلوب أصلا بعد استنزال ما يكون المحكوم عليه قد دفعه أو تحصل منه بالتنفيذ على ممتلكاته ."}, {"number": "518", "chapter": "الباب السادس", "text": "لاتبرأ ذمة المحكوم عليه من المصاريف ومايجب رده والتعويضات بتنفيذ الإكراه البدنى ، ولاتبرأ من الغرامة إلا بإعتبار خمسة جنيهات عن كل يوم ."}, {"number": "519", "chapter": "الباب السادس", "text": "إذا لم يقم المحكوم عليه بتنفيذ الحكم الصادر لغير الحكومة بالتعويضات بعد التنبيه عليه بالدفع ، جاز لمحكمة الجنح التى بدائرتها محله ، إذا ثبت لديها أنه قادر على الدفع ، وأمرته به فلم يمتثل ، أن تحكم عليه بالإكراه البدنى ، ولا يجوز أن تزيد مدة هذا الإكراه على ثلاثة أِشهر ، ولا يخصم شئ من التعويض نظير الإكراه فى هذه الحالة ، وترفع الدعوى من المحكوم له بالطرق المعتادة."}, {"number": "520", "chapter": "الباب السادس", "text": "للمحكوم عليه أن يطلب فى أى وقت من النيابة العامة قبل صدور الأمر بالإكراه البدنى إبداله بعمل يدوى أو صناعى يقوم به ."}, {"number": "521", "chapter": "الباب السادس", "text": "يشتغل المحكوم عليه فى هذا العمل بلا مقابل لأحد جهات الحكومة أو البلديات مدة من الزمن مساوية لمدة الإكراه التى كان يجب التنفيذ عليه بها ، وتعين أنواع الأعمال التى يجوز تشغيل المحكوم عليه فيها والجهات الإدارية التى تقرر هذه الأعمال بقرار يصدر من الوزير المختص . ولا يجوز تشغيل المحكوم عليه خارج المدينة الساكن بها أو المركز التابع له . ويراعى فى العمل الذى يعرض عليه يوميا أن يكون قادرا على إتمامه فى ظرف ست ساعات بحسب حالة بنيته ."}, {"number": "522", "chapter": "الباب السادس", "text": "المحكوم عليه الذى تقرر معاملته بمقتضى المادة 520 ولا يحضر إلى المحل المعد لشغله ، أو يتغيب عن شغله أو لايتمم العمل المفروض عليه تأديته يوميا بلا عذر تراه جهات الإدارة مقبولا ، يرسل إلى السجن للتنفيذ عليه بالإكراه البدنى الذى كان يستحق التنفيذ به عليه ويخصم له من مدته الأيام التى يكون قد أتم فيها ما فرض عليه تأديته من الأعمال . ويجب التنفيذ بالإكراه البدنى على المحكوم عليه الذى أختار الشغل بدل الإكراه إذا لم يوجد عمل يكون من وراء شغله فيه فائدة ."}, {"number": "523", "chapter": "الباب السادس", "text": "يستنزل من المبالغ المستحقة للحكومة من الغرامة وما يجب رده والتعويضات والمصاريف مقابل شغل المحكوم عليه باعتبار خمسة جنيهات عن كل يوم ."}, {"number": "524", "chapter": "الباب السابع", "text": "كل إشكال من المحكوم عليه فى التنفيذ يرفع إلى محكمة الجنايات إذا كان صادرا منها وإلى محكمة الجنح المستأنفة فيمت عدا ذلك ، وينعقد الاختصاص فى الحالين للمحكمة التى تختص محليا بنظر الدعوى المستشكل فى تنفيذ الحكم الصادر فيها ."}, {"number": "525", "chapter": "الباب السابع", "text": "يقدم النزاع إلى المحكمة بواسطة النيابة العامة على وجه السرعة ، ويعلن ذو الشأن بالجلسة التى تحدد لنظره ، وتفصل المحكمة فيه فى غرفة المشورة بعد سماع النيابة العامة وذوى الشأن وللمحكمة أن تجرى التحقيقات التى ترى لزومها ، ولها فى كل الأحوال أن تأمر بوقف التنفيذ حتى يفصل فى النزاع . وللنيابة العامة عند الإقتضاء وقبل تقديم النزاع إلى المحكمة أن توقف تنفيذ الحكم مؤقتا"}, {"number": "526", "chapter": "الباب السابع", "text": "إذا حصل نزاع فى شخصية المحكوم عليه يفصل فى ذلك النمزاع بالكيفية والأوضاع المقررة فى المادتين السابقتين ."}, {"number": "527", "chapter": "الباب السابع", "text": "فى حالة تنفيذ الأحكام المالية على أموال المحكوم عليه إذا قام نزاع من غير المتهم بشأن الأموال المطلوب التنفيذ عليها ، يرفع الأمر إلى المحكمة المدنية طبقا لما هو مقرر فى قانون المرافعات ."}, {"number": "528", "chapter": "الباب الثامن", "text": "تسقط العقوبة المحكوم بها فى جناية بمضى عشرين سنة ميلادية إلا عقوبة الإعدام فإنها تسقط بمضى ثلاثين سنة . وتسقط العقوبة المحكوم بها فى جنحة بمضى خمس سنين . وتسقط العقوبة المحكوم بها فى مخالفة بمضى سنتين ."}, {"number": "529", "chapter": "الباب الثامن", "text": "تبدأ المدة من وقت صيرورة الحكم نهائيا ، إلا إذا كانت العقوبة المحكوم بها غيابيا من محكمة الجنايات فى جناية تبدأ المدة من يوم صدور الحكم"}, {"number": "530", "chapter": "الباب الثامن", "text": "تنقطع المدة بالقبض على المحكوم عليه بعقوبة مقيدة للحرية ، وبكل إجراء من إجراءات التنفيذ التى تتخذ فى مواجهته أو تصل إلى علمه ."}, {"number": "531", "chapter": "الباب الثامن", "text": "فى غير مواد المخالفات تنقطع المدة أيضا ، إذا إرتكب المحكوم عليه فى خلالها جريمة من نوع الجريمة المحكوم عليه من أجلها أو مماثلة لها ."}, {"number": "532", "chapter": "الباب الثامن", "text": "يوقف سريان المدة كل مانع بحول دون مباشرة التنفيذ سواء كان قانونيا أو ماديا ، ويعتبر وجود المحكوم عليه فى الخارج مانعا يوقف سريان المدة ."}, {"number": "533", "chapter": "الباب الثامن", "text": "لا يجوز للمحكوم عليه بالإعدام أو بالأشغال الشاقة فى جناية قتل أو شروع فيه أو ضرب أفضى إلى موت أن يقيم بعد سقوط عقوبته بمضى المدة فى دائرة المديرية أو المحافظة التى وقعت فيها الجريمة إلا إذا رخص له فى ذلك المدير أو المحافظ فإذا خالف ذلك ، يحكم عليه بالحبس مدة لاتزيد عن سنة . وللمدير أو المحافظ أن يأمر بإلغاء الترخيص إذا رأى مايدعو لذلك ويكلف المحكوم عليه أن يتخذ له فى مدة عشرة أيام محل إقامة خارج دائرة المديرية أن المحافظة ، وإذا خالف المحكوم عليه ذلك يعاقب بالعقوبة المتقدمة . ولوزير الداخلية فى جميع الأحوال المذكورة أن يعين للمحكوم عليه محل إقامة ، وتتبع فى ذلك الأحكام الخاصة بمراقبة البوليس ."}, {"number": "534", "chapter": "الباب الثامن", "text": "تتبع الأحكام المقررة لمضى المدة فى القانون المدنى فيما يختص بالتعويضات وما يجب رده والمصاريف المحكوم بها . ومع ذلك فلا يجوز التنفيذ بطريق الإكراه البدنى بعد مضى المدة المقررة لسقوط العقوبة ."}, {"number": "535", "chapter": "الباب الثامن", "text": "إذا توفى المحكوم عليه بعد الحكم عليه نهائيا ، تنفذ العقوبات المالية والتعويضات وما يجب رده والمصاريف فى تركته ."}, {"number": "536", "chapter": "الباب التاسع", "text": "يجوز رد الاعتبار إلى كل محكوم عليه فى جناية أو جنحة ويصدر الحكم بذلك من محكمة الجنايات التابع لها محل إقامة المحكوم عليه وذلك بناء على طلبه ."}, {"number": "537", "chapter": "الباب التاسع", "text": "يجب لرد الإعتبار : ( أولا ) أن تكون العقوبة قد نفذت تنفيذا كاملا أو صدر عفو عنها وسقطت بمضى المدة (ثانيا) أن يكون قد إنقضى من تاريخ تنفيذ العقوبة ، أو صدور العفو عنها مدة ست سنوات إذا كانت عقوبة جناية ، أو ثلاث سنوات إذا كانت عقوبة جنحة . وتضاعف هذه المدة فى حالتى الحكم للعود وسقوط العقوبة بمضى المدة ."}, {"number": "538", "chapter": "الباب التاسع", "text": "إذا كان المحكوم عليه قد وضع تحت مراقبة البوليس بعد انقضاء العقوبة الأصلية ، تبتدئ المدة من اليوم الذى تنتهى فيه مدة المراقبة . وإذا كان قد أفرج عن المحكوم عليه تحت شرط ، فلا تبتدئ المدة إلا من التاريخ المقرر لانقضاء العقوبة أو التاريخ الذى يصبح فيه الإفراج تحت شرط نهائيا ."}, {"number": "539", "chapter": "الباب التاسع", "text": "يجب للحكم برد الإعتبار أن يوفى المحكوم عليه كل ماحكم به عليه من غرامة أو رد أو تعويض أو مصاريف وللمحكمة أن تتجاوز عن هذا إذا أثبت المحكوم عليه أنه ليس بحال يستطيع معها الوفاء . وإذا لم يوجد المحكوم له بالتعويضات أو الرد أو المصاريف ، أو امتنع عن قبولها وجب على المحكوم عليه أن يودعها طبقا لماهو مقرر فى قانون المرافعات فى المواد المدنية والتجارية ، ويجوز له أن يستردها إذا مضت خمس سنوات ولم يطلبها المحكوم له . وإذا كان المحكوم عليه قد صدر عليه الحكم بالتضامن يكفى أن يدفع مقدار ما يخصه شخصيا فى الدين ، وعند الاقتضاء تعين المحكمة الحصة التى يجب عليه دفعها ."}, {"number": "540", "chapter": "الباب التاسع", "text": "فى حالة الحكم فى جريمة تفالس يجب على الطالب أن يثبت أنه قد حصل على حكم برد إعتباره التجارى"}, {"number": "541", "chapter": "الباب التاسع", "text": "إذا كان الطالب قد صدرت عليه أحكام فلا يحكم برد اعتباره إلا إذا تحققت الشروط المنصوص عليها فى المواد السابقة بالنسبة إلى كل حكم منها . على أن يراعي فى حساب المدة إسنادها إلى أحدث الأحكام ."}, {"number": "542", "chapter": "الباب التاسع", "text": "يقدم طلب رد الاعتبار بعريضة إلى النيابة العامة ويجب أن يشتمل على البيانات اللازمة لتعيين شخصية الطالب ، وأن يبين فيها تاريخ الحكم الصادر عليه والأماكن التى أقام فيها من ذلك الحين ."}, {"number": "543", "chapter": "الباب التاسع", "text": "تجرى النيابة العامة تحقيقا بشأن الطلب للإستيثاق من تاريخ إقامة الطالب فى كل مكان نزله من وقت الحكم عليه ، ومدة تلك الإقامة وللوقوف على سلوكه ووسائل ارتزاقه ، وبوجه عام تتقصى كل ماتراه لازما من المعلومات ويضم التحقيق إلى الطلب وترفعه إلى المحكمة فى الثلاثة أِشهر التالية لتقديمه بتقرير يدون فيه رأيها ، وتبين الأسباب التى بنى عليها ويرفق بالطلب : 1 - صورة الحكم الصادر على الطالب 2 - شهادة سوابقه 3 - تقرير عن سلوكه أثناء وجوده فى السجن ."}, {"number": "544", "chapter": "الباب التاسع", "text": "تنظر المحكمة الطلب وتفصل فيه فى غرفة المشورة ويجوز لها سماع أقوال النيابة العامة والطالب ، كما يجوز لها استيفاء كل ما تراه لازما من المعلومات . ويكون إعلان الطالب بالحضور قبل الجلسة بثمانية أيام على الأٌقل . ولا يقبل الطعن فى الحكم إلا بطريق النقض لخطأ فى تطبيق القانون أو فى تأويله ، وتتبع فى الطعن الأوضاع والمواعيد المقررة للطعن بطريق النقض فى الأحكام ."}, {"number": "545", "chapter": "الباب التاسع", "text": "متى توافر الشرطان المذكوران فى المادة 537 تحكم المحكمة برد الاعتبار إذا رأت أن سلوك الطالب منذ صدور الحكم عليه يدعو إلى الثقة بتقويم نفسه ."}, {"number": "546", "chapter": "الباب التاسع", "text": "ترسل النيابة العامة صور من حكم رد الاعتبار إلى المحكمة التى صدر منها الحكم بالعقوبة للتأشير به على هامشه ، وتأمر بأن يؤشر به فى قلم السوابق ."}, {"number": "547", "chapter": "الباب التاسع", "text": "لا يجوز الحكم برد إعتبار المحكوم عليه إلا لمرة واحدة ."}, {"number": "548", "chapter": "الباب التاسع", "text": "إذا رفض طلب رد الاعتبار بسبب راجع إلى سلوك المحكوم عليه ، فلا يجوز تجديده إلا بعد مضى سنتين . أما فى الأحوال الأخرى فيجوز تجديده متى توافرت الشروط اللازم توافرها ."}, {"number": "549", "chapter": "الباب التاسع", "text": "يجوز الغاء الحكم الصادر برد الإعتبار ، إذا ظهر أن المحكوم عليه قد صدرت ضده أحكام أخرى لم تكن المحكمة علمت بها ، أو إذا حكم عليه بعد رد الاعتبار فى جريمة وقعت قبله . ويصدر الحكم فى هذه الحالة من المحكمة التى حكمت برد الاعتبار بناء على طلب النيابة العامة ."}, {"number": "550", "chapter": "الباب التاسع", "text": "يرد الإعتبار بحكم القانون إذا لم يصدر خلال الآجال الآتية على المحكوم عليه بعقوبة جناية أو جنحة مما يحفظ عنه بصحيفة قلم السوابق : (أولا) بالنسبة إلى المحكوم عليه بعقوبة جناية أو بعقوبة جنحة فى جريمة سرقة أو إخفاء أشياء مسروقة أو نصب أو خيانة أمانة أو تزوير أو شروع فى هذه الجرائم المنصوص عليها فى المواد 355، 356 ، 367 ،368 من قانون العقوبات متى مضى على تنفيذ العقوبة أو العفو عنها أو سقوطها بمضى المدة اثنتا عشرة سنة . ( ثانيا) بالنسبة إلى المحكوم عليه بعقوبة جنحة فى غير ماذكر متى مضى على تنفيذ العقوبة أو العفو عنها ست سنوات ، إلا إذا كان الحكم قد إعتبر المحكوم عليه عائدا ، أو كانت العقوبة قد سقطت بمضى المدة فتكون المدة إثنتى عشرة سنة"}, {"number": "551", "chapter": "الباب التاسع", "text": "إذا كان المحكوم عليه قد صدرت ضده عدة أحكام فلا يرد اعتباره إليه بحكم القانون إلا إذا تحققت بالنسبة لكل منها الشروط المنصوص عليها فى المادة السابقة ، على أن يراعى فى حساب المدة إسنادها إلى أحدث الأحكام ."}, {"number": "552", "chapter": "الباب التاسع", "text": "يترتب على رد الاعتبار محو الحكم القاضى بالإدانة بالنسبة للمستقبل ، وزوال كل ما يترتب عليه من انعدام الأهلية والحرمان من الحقوق وسائر الآثار الجنائية ."}, {"number": "553", "chapter": "الباب التاسع", "text": "لا يجوز الاحتجاج برد الاعتبار على الغير فيما يتعلق بالحقوق التى تترتب لهم من الحكم بالإدانة ، وعلى الأخص فيما يتعلق بالرد والتعويضات . أحكام عامة فى الإجراءات التى تتبع فى حالة فقد الأوراق أو الأحكام"}, {"number": "554", "chapter": "الباب التاسع", "text": "إذا فقدت النسخة الأصلية للحكم قبل تنفيذه أو فقدت أوراق التحقيق كلها أو بعضها قبل صدور قرار فيه تتبع الإجراءات المقررة فى المواد الآتية :"}, {"number": "555", "chapter": "الباب التاسع", "text": "إذا وجدت صورة رسمية من الحكم ، فهذه الصورة تقوم مقام النسخة الأصلية . وإذا كانت الصورة تحت يد شخص أوجهه ما تستصدر النيابة العامة أمرا من رئيس المحكمة التى أصدرت الحكم بتسليمها ، ولمن أخذت منه أن يطلب تسليمه صورة مطابقة بغير مصاريف"}, {"number": "556", "chapter": "الباب التاسع", "text": "لا يترتب على فقد نسخة الحكم الأصلية إعادة المحاكمة متى كانت طرق الطعن فى الحكم قد استنفدت ."}, {"number": "557", "chapter": "الباب التاسع", "text": "إذا كانت القضية منظورة أمام محكمة النقض ولم ستيسر الحصول على صورة من الحكم ، تقضى المحكمة بإعادة المحاكمة متى كانت جميع الإجراءات المقررة للطعن قد استوفيت"}, {"number": "558", "chapter": "الباب التاسع", "text": "إذا فقدت أوراق التحقيق كلها أو بعضها ، قبل صدور قرار فيه ، يعاد التحقيق فيما فقدت أوراقه . وإذا كانت القضية مرفوعة أمام المحكمة تتولى هى إجراء ماتراه من التحقيق"}, {"number": "559", "chapter": "الباب التاسع", "text": "إذا فقدت أوراق التحقيق كلها أو بعضها ، وكان الحكم موجودا والقضية منظورة أمام محكمة النقض ، فلا تعاد الإجراءات إلا إذا رأت المحكمة محلا لذلك . فى حساب المدد"}, {"number": "560", "chapter": "الباب التاسع", "text": "جميع المدد المبينة فى هذا القانون تحسب بالتقويم الميلادي ."}]};